  function getTranslationValueFromObject(dictionary, key) {
    const keys = String(key || "").split(".");
    let value = dictionary;
    for (const k of keys) value = value?.[k];
    return value;
  }

  function fillMissingTranslationKeys(base, override) {
    const result = { ...(base || {}) };
    const src = override || {};

    for (const [key, value] of Object.entries(src)) {
      if (value && typeof value === "object" && !Array.isArray(value)) {
        result[key] = fillMissingTranslationKeys(base?.[key], value);
      } else {
        result[key] = value;
      }
    }

    return result;
  }

