  const API_BASE_DEFAULT = "https://api.gntd.us";
  const API_BASE_DEV_KEY = "dev.apiBase.v1";
  function resolveApiBase() {
    const fallback = API_BASE_DEFAULT;
    if (!DEV_TOOLS_ENABLED) return fallback;
    let raw = "";
    try {
      raw = String(localStorage.getItem(API_BASE_DEV_KEY) || "").trim();
    } catch {}
    if (!raw) return fallback;

    try {
      const url = new URL(raw);
      const origin = url.origin.replace(/\/$/, "");
      const isAllowedLocal = url.protocol === "http:"
        && (url.hostname === "127.0.0.1" || url.hostname === "localhost")
        && url.port === "3000";
      const isAllowedProd = origin === API_BASE_DEFAULT;
      return isAllowedLocal || isAllowedProd ? origin : fallback;
    } catch {
      return fallback;
    }
  }
