  function debugWarn(...args) {
    if (DEBUG_LOGS_ENABLED) console.warn(...args);
  }

  function startPerf(label) {
    if (!DEBUG_PERF_ENABLED || typeof performance?.now !== "function") return null;
    return { label, startedAt: performance.now() };
  }

  function endPerf(marker, details) {
    if (!marker || !DEBUG_PERF_ENABLED || typeof performance?.now !== "function") return;
    const durationMs = performance.now() - marker.startedAt;
    if (details !== undefined) {
      console.log(`[PERF] ${marker.label}: ${durationMs.toFixed(1)}ms`, details);
      return;
    }
    console.log(`[PERF] ${marker.label}: ${durationMs.toFixed(1)}ms`);
  }

