  async function handleGntdBroadcastMessage(message) {
    await runGntdBroadcastRefresh(async () => {
      switch (message.type) {
        case "BACKGROUND_CHANGED":
          await reloadBackgroundStateFromStorage();
          break;
        case "LAYOUT_CHANGED":
          await reloadLayoutStateFromStorage();
          break;
        case "BOOKMARKS_CHANGED":
          await reloadBookmarkStateFromStorage();
          break;
        case "WIDGETS_CHANGED":
          await reloadWidgetStateFromStorage();
          break;
        case "TODO_CHANGED":
          await reloadTodoStateFromStorage();
          break;
        case "NOTES_CHANGED":
          await reloadNotesStateFromStorage();
          break;
        case "AUTH_CHANGED":
          await refreshAccountStateFromStorage();
          break;
        case "PREMIUM_CHANGED":
          await refreshPremiumStateFromStorage();
          break;
        case "SYNC_PULL_COMPLETED":
        case "SYNC_PUSH_COMPLETED":
        case "FULL_STATE_REFRESH_REQUIRED":
          scheduleFullStateRefresh();
          break;
        default:
          console.debug("[GNTD Broadcast] Unknown message type:", message.type);
      }
    });
  }

