    if (!toggleButton || !statusEl) return;

    const userEnabled = isCloudSyncUserEnabled();
    const hasPremiumAccess = hasCloudSyncPremiumEntitlement(state);
    const effectiveEnabled = userEnabled && hasPremiumAccess;
    toggleButton.textContent = effectiveEnabled ? "Disable" : "Enable";
    toggleButton.setAttribute("aria-pressed", effectiveEnabled ? "true" : "false");
    applyPremiumGate(toggleButton, PREMIUM_FEATURE_CLOUD_SYNC, getPremiumFeatureLabel(PREMIUM_FEATURE_CLOUD_SYNC), state);

    const uiStatus = resolveCloudSyncUiStatus(state);
    statusEl.dataset.syncStatus = uiStatus;
    statusEl.textContent = getCloudSyncStatusLabel(uiStatus);
    refreshSecurityCenterUi();
