  function normalizePremiumFeatures(rawFeatures) {
    const out = {};

    if (Array.isArray(rawFeatures)) {
      rawFeatures.forEach((item) => {
        const key = normalizeFeatureName(item);
        if (key) out[key] = true;
      });
      return out;
    }

    if (!rawFeatures || typeof rawFeatures !== "object") {
      return out;
    }

    Object.entries(rawFeatures).forEach(([rawKey, rawValue]) => {
      const key = normalizeFeatureName(rawKey);
      if (!key) return;

      if (typeof rawValue === "boolean") {
        out[key] = rawValue;
        return;
      }

      if (rawValue && typeof rawValue === "object" && Object.prototype.hasOwnProperty.call(rawValue, "enabled")) {
        out[key] = !!rawValue.enabled;
        return;
      }

      if (typeof rawValue === "string") {
        const normalized = rawValue.trim().toLowerCase();
        out[key] = normalized === "1"
          || normalized === "true"
          || normalized === "enabled"
          || normalized === "active"
          || normalized === "premium";
        return;
      }

      out[key] = !!rawValue;
    });

    return out;
  }

  function getPremiumCandidates(payload) {
    const candidates = [
      payload,
      payload?.billing,
      payload?.premium,
      payload?.subscription,
      payload?.account,
      payload?.user,
      payload?.profile,
      payload?.me,
      payload?.data,
      payload?.data?.billing,
      payload?.data?.premium,
      payload?.data?.subscription,
      payload?.data?.account,
      payload?.data?.user,
      payload?.result,
      payload?.result?.billing,
      payload?.result?.premium,
      payload?.result?.subscription,
      payload?.result?.account,
      payload?.result?.user
    ];

    return candidates.filter((item) => item && typeof item === "object");
  }

  function getFirstDefined(candidates, keys) {
    for (const candidate of candidates) {
      for (const key of keys) {
        if (candidate && Object.prototype.hasOwnProperty.call(candidate, key) && candidate[key] != null) {
          return candidate[key];
        }
      }
    }
    return undefined;
  }

  function getFirstBoolean(candidates, keys) {
    const raw = getFirstDefined(candidates, keys);
    if (typeof raw === "boolean") return raw;
    if (typeof raw === "number") return raw === 1;
    if (typeof raw === "string") {
      const normalized = raw.trim().toLowerCase();
      if (["1", "true", "yes", "active", "premium", "paid", "enabled", "entitled"].includes(normalized)) return true;
      if (["0", "false", "no", "free", "inactive", "disabled", "not_entitled"].includes(normalized)) return false;
    }
    return null;
  }

  function normalizeSubscriptionStatus(rawValue) {
    const value = String(rawValue || "").trim().toLowerCase();
    if (!value) return "";
    if (value === "trial") return "trialing";
    if (value === "paid") return "active";
    if (value === "cancelled") return "canceled";
    return value;
  }

  function normalizePremiumPayload(payload) {
    const candidates = getPremiumCandidates(payload);
    if (!candidates.length) return null;

    const rawPlan = getFirstDefined(candidates, ["plan", "planName", "plan_name", "tier", "subscriptionPlan", "subscription_plan"]);
    let rawStatus;
    for (const candidate of candidates) {
      if (!candidate || typeof candidate !== "object") continue;
      const possibleStatus = [
        candidate.status,
        candidate.state,
        candidate.subscriptionState,
        candidate.subscription_state,
        candidate.subscriptionStatus,
        candidate.subscription_status,
        candidate.planStatus,
        candidate.plan_status,
        candidate.billingStatus,
        candidate.billing_status
      ];
      const normalizedStatus = possibleStatus
        .map((value) => normalizeSubscriptionStatus(value))
        .find((value) => PREMIUM_KNOWN_SUBSCRIPTION_STATUSES.has(value));
      if (normalizedStatus) {
        rawStatus = normalizedStatus;
        break;
      }
    }
    const rawCurrentPeriodEnd = getFirstDefined(candidates, ["currentPeriodEnd", "current_period_end", "premiumUntil", "premium_until", "premiumExpiresAt", "premium_expires_at", "expiresAt", "expires_at"]);
    const rawFeatures = getFirstDefined(candidates, ["features", "featureFlags", "feature_flags", "premiumFeatures", "premium_features", "entitlements"]);
    const rawIsPremium = getFirstBoolean(candidates, [
      "isPremium",
      "is_premium",
      "premium",
      "paid",
      "hasPremium",
      "has_premium",
      "premiumAccess",
      "premium_access",
      "entitled",
      "isEntitled",
      "is_entitled",
      "active",
      "isActive",
      "is_active"
    ]);

    const hasPremiumSignals = rawPlan != null || rawStatus != null || rawCurrentPeriodEnd != null || rawFeatures != null || rawIsPremium != null;
    if (!hasPremiumSignals) return null;

    const plan = String(rawPlan || "").trim().toLowerCase();
    let billingStatus = String(rawStatus || "").trim().toLowerCase() || null;
    const premiumUntil = toIsoDate(rawCurrentPeriodEnd);
    const features = normalizePremiumFeatures(rawFeatures);
    if (!billingStatus && rawIsPremium === true) {
      // Backend may omit status while still returning an explicit premium flag.
      // Treat this as active to avoid false-negative premium locks.
      billingStatus = "active";
    }

    const statusAllowsPremium = billingStatus ? PREMIUM_ACTIVE_SUBSCRIPTION_STATUSES.has(billingStatus) : false;
    const hasPlanPremiumSignal = !!plan && /premium|pro|paid|plus|business|team|enterprise/.test(plan);
    const hasFeaturePremiumSignal = Object.values(features).some((enabled) => enabled === true);
    const inferredPremiumFlag = rawIsPremium === null
      ? (statusAllowsPremium || hasPlanPremiumSignal || hasFeaturePremiumSignal)
      : false;
    const premiumFlagAllowed = rawIsPremium === false ? false : (rawIsPremium === true || inferredPremiumFlag);
    // Premium decision: accept explicit isPremium=true, or infer from statuses/plan/features if explicitly false is not set
    const isPremium = rawIsPremium === true
      ? true
      : (rawIsPremium === false
          ? false
          : (statusAllowsPremium || hasPlanPremiumSignal || hasFeaturePremiumSignal));
    const isExpired = billingStatus === "canceled"
      || billingStatus === "cancelled"
      || billingStatus === "past_due"
      || billingStatus === "incomplete_expired"
      || billingStatus === "expired"
      || (!!premiumUntil && compareIsoDates(premiumUntil, new Date().toISOString()) <= 0);
    const status = isPremium
      ? PREMIUM_STATUS_PREMIUM
      : (isExpired ? PREMIUM_STATUS_EXPIRED : PREMIUM_STATUS_FREE);

    return {
      plan: plan || (isPremium ? "premium" : "free"),
      billingStatus,
      premiumUntil: premiumUntil || null,
      features,
      isPremium,
      isPremiumInferred: inferredPremiumFlag,
      loaded: true,
      hasSession: true,
      status,
      updatedAt: new Date().toISOString()
    };
  }

  function isLikelyDevExtensionBuild() {
    try {
      const manifest = chrome?.runtime?.getManifest?.();
      if (!manifest || typeof manifest !== "object") return false;
      return !manifest.update_url;
    } catch {
      return false;
    }
  }

  function isDevTestAuthEnabled() {
    if (!DEV_TOOLS_ENABLED) return false;
    const raw = String(localStorage.getItem(DEV_AUTH_MOCK_KEY) || "").trim().toLowerCase();
    if (["0", "false", "off", "no"].includes(raw)) return false;
    if (["1", "true", "on", "yes"].includes(raw)) return true;
    return false;
  }

  function getDevTestAccount(email) {
    const normalizedEmail = String(email || "").trim().toLowerCase();
    return DEV_AUTH_TEST_ACCOUNTS[normalizedEmail] || null;
  }

  function buildDevPremiumFeatures(account) {
    if (!account?.isPremium) return {};
    const out = {};
    DEFAULT_PREMIUM_FEATURES.forEach((featureName) => {
      out[normalizeFeatureName(featureName)] = true;
    });
    return out;
  }

  function buildDevPremiumPayload(account, email) {
    const normalizedEmail = String(email || "").trim().toLowerCase();
    const isPremium = account?.isPremium === true;
    const premiumUntil = isPremium
      ? new Date(Date.now() + (1000 * 60 * 60 * 24 * 90)).toISOString()
      : null;
    const billingStatus = isPremium ? "active" : "free";
    const features = buildDevPremiumFeatures(account);
    const profile = {
      id: account?.id || `dev-user-${normalizedEmail}`,
      email: normalizedEmail,
      name: account?.name || normalizedEmail,
      emailVerified: true,
      email_verified: true,
      plan: isPremium ? "premium" : "free",
      isPremium,
      is_premium: isPremium,
      status: billingStatus,
      billingStatus,
      premiumUntil,
      features
    };

    return {
      ok: true,
      devMock: true,
      emailVerified: true,
      email_verified: true,
      plan: profile.plan,
      status: billingStatus,
      billingStatus,
      premiumUntil,
      isPremium,
      is_premium: isPremium,
      features,
      user: profile,
      account: profile,
      billing: {
        plan: profile.plan,
        status: billingStatus,
        billingStatus,
        premiumUntil,
        isPremium,
        features
      }
    };
  }

  function extractEmailFromDevAuthToken(token) {
    const parts = String(token || "").trim().split(":");
    if (parts[0] !== "dev-token" || !parts[1]) return "";
    try {
      return decodeURIComponent(parts[1]);
    } catch {
      return "";
    }
  }

  function buildDevAuthResponse(email) {
    const normalizedEmail = String(email || "").trim().toLowerCase();
    const account = getDevTestAccount(normalizedEmail);
    if (!account) return null;
    const data = buildDevPremiumPayload(account, normalizedEmail);
    return {
      token: `dev-token:${encodeURIComponent(normalizedEmail)}:${Date.now()}`,
      refreshToken: `dev-refresh-token:${encodeURIComponent(normalizedEmail)}:${Date.now()}`,
      data
    };
  }

  function getDevTestAuthResult(email, password) {
    const normalizedEmail = String(email || "").trim().toLowerCase();
    if (!isDevTestAuthEnabled()) return null;
    if (String(password || "") !== DEV_AUTH_TEST_PASSWORD) return null;
    return buildDevAuthResponse(normalizedEmail);
  }

  function persistPremiumState() {
    const safeState = {
      plan: String(premiumState?.plan || "free"),
      billingStatus: premiumState?.billingStatus ? String(premiumState.billingStatus) : null,
      premiumUntil: premiumState?.premiumUntil || null,
      features: premiumState?.features && typeof premiumState.features === "object" ? premiumState.features : {},
      isPremium: !!premiumState?.isPremium,
      loaded: !!premiumState?.loaded,
      hasSession: !!premiumState?.hasSession,
      status: String(premiumState?.status || PREMIUM_STATUS_FREE),
      uiOverride: !!premiumState?.uiOverride,
      source: String(premiumState?.source || "unknown"),
      updatedAt: premiumState?.updatedAt || new Date().toISOString()
    };

    try {
      localStorage.setItem(PREMIUM_STATE_KEY, JSON.stringify(safeState));
    } catch {}

    if (hasChromeStorage) {
      try {
        chrome.storage.local.set({ [PREMIUM_STATE_KEY]: safeState }, () => {});
      } catch {}
    }
  }

  function hydratePremiumStateFromStorage() {
    let cachedState = null;

    try {
      const raw = localStorage.getItem(PREMIUM_STATE_KEY);
      cachedState = raw ? JSON.parse(raw) : null;
    } catch {
      cachedState = null;
    }

    if (!cachedState || typeof cachedState !== "object") {
      return premiumState;
    }

    const hasStoredSession = cachedState.hasSession === true
      || !!localStorage.getItem(CLOUD_AUTH_TOKEN_KEY)
      || !!localStorage.getItem(LEGACY_AUTH_TOKEN_KEY)
      || !!localStorage.getItem(CLOUD_AUTH_REFRESH_TOKEN_KEY);
    const resolvedIsPremium = cachedState.isPremium === true;
    const resolvedStatus = !hasStoredSession
      ? PREMIUM_STATUS_GUEST
      : (resolvedIsPremium
          ? PREMIUM_STATUS_PREMIUM
          : (cachedState.status === PREMIUM_STATUS_EXPIRED ? PREMIUM_STATUS_EXPIRED : PREMIUM_STATUS_FREE));

    premiumState = {
      ...buildFreePremiumState(),
      plan: String(cachedState.plan || (resolvedIsPremium ? "premium" : "free")),
      billingStatus: cachedState.billingStatus ? String(cachedState.billingStatus) : null,
      premiumUntil: cachedState.premiumUntil || null,
      features: normalizePremiumFeatures(cachedState.features),
      isPremium: resolvedIsPremium,
      loaded: true,
      hasSession: hasStoredSession,
      status: resolvedStatus,
      uiOverride: !!cachedState.uiOverride,
      source: `${String(cachedState.source || "bootstrap")}:cache`,
      updatedAt: cachedState.updatedAt || new Date().toISOString()
    };

    return premiumState;
  }

  hydratePremiumStateFromStorage();

  function getAppNoticeRefs() {
    return {
      modal: document.getElementById("appNotice"),
      title: document.getElementById("appNoticeTitle"),
      text: document.getElementById("appNoticeText")
    };
  }

  let activeAppNoticeCleanup = null;

  function clearActiveAppNoticeHandlers() {
    if (typeof activeAppNoticeCleanup === "function") {
      const cleanup = activeAppNoticeCleanup;
      activeAppNoticeCleanup = null;
      cleanup();
    }
  }

  function resetGlobalAppNoticeButtons(notice) {
    const okBtn = document.getElementById("appNoticeOk");
    const cancelBtn = document.getElementById("appNoticeCancel");
    if (okBtn) okBtn.textContent = notice.ok;
    if (cancelBtn) {
      cancelBtn.textContent = notice.cancel;
      cancelBtn.hidden = true;
    }
  }

  function hideGlobalAppNotice() {
    clearActiveAppNoticeHandlers();
    const { modal } = getAppNoticeRefs();
    if (modal) modal.hidden = true;
  }

