  function showGlobalAppNotice(title, text) {
    const notice = getNoticeTexts();
    const refs = getAppNoticeRefs();
    if (!refs.modal || !refs.title || !refs.text) {
      alert(String(text || title || notice.title));
      return;
    }

    clearActiveAppNoticeHandlers();
    refs.title.textContent = String(title || notice.title);
    refs.text.textContent = String(text || "");
    resetGlobalAppNoticeButtons(notice);
    refs.modal.hidden = false;
  }

  function showConfirmNotice(title, text, onConfirm, options = {}) {
    const notice = getNoticeTexts();
    const refs = getAppNoticeRefs();
    if (!refs.modal || !refs.title || !refs.text) {
      if (confirm(String(text || title))) onConfirm();
      return;
    }

    clearActiveAppNoticeHandlers();
    refs.title.textContent = String(title || notice.areYouSure);
    refs.text.textContent = String(text || "");

    const okBtn = document.getElementById("appNoticeOk");
    const cancelBtn = document.getElementById("appNoticeCancel");
    const confirmLabel = String(options.confirmLabel || notice.yesLogout);
    const cancelLabel = String(options.cancelLabel || notice.cancel);

    if (okBtn) okBtn.textContent = confirmLabel;
    if (cancelBtn) {
      cancelBtn.textContent = cancelLabel;
      cancelBtn.hidden = false;
    }

    const cleanup = () => {
      resetGlobalAppNoticeButtons(notice);
      okBtn?.removeEventListener("click", onYes);
      cancelBtn?.removeEventListener("click", onNo);
    };
    const onYes = () => {
      hideGlobalAppNotice();
      onConfirm();
    };
    const onNo = () => {
      hideGlobalAppNotice();
      if (typeof options.onCancel === "function") {
        options.onCancel();
      }
    };

    activeAppNoticeCleanup = cleanup;
    okBtn?.addEventListener("click", onYes);
    cancelBtn?.addEventListener("click", onNo);

    refs.modal.hidden = false;
  }

  let miniNoticeTimer = 0;
  function showMiniNotice(text, isError = false) {
    if (!text) return;

    let el = document.getElementById("miniNotice");
    if (!el) {
      el = document.createElement("div");
      el.id = "miniNotice";
      el.className = "mini-notice";
      document.body.appendChild(el);
    }

    el.textContent = String(text);
    el.classList.toggle("is-error", !!isError);
    el.classList.add("is-visible");

    if (miniNoticeTimer) window.clearTimeout(miniNoticeTimer);
    miniNoticeTimer = window.setTimeout(() => {
      el.classList.remove("is-visible");
    }, 1800);
  }

  function applyPremiumState(nextState) {
    premiumState = {
      ...buildFreePremiumState(),
      ...(nextState || {}),
      loaded: true,
      hasSession: (nextState && typeof nextState.hasSession === "boolean") ? nextState.hasSession : true,
      status: String(nextState?.status || (nextState?.isPremium ? PREMIUM_STATUS_PREMIUM : PREMIUM_STATUS_FREE)),
      updatedAt: (nextState && nextState.updatedAt) || new Date().toISOString()
    };
    persistPremiumState();
    refreshPremiumUi();
    broadcastGntdStateChange("PREMIUM_CHANGED");
    window.dispatchEvent(new CustomEvent("premium:state-changed", { detail: { state: { ...premiumState } } }));
    return premiumState;
  }

  function setPremiumLoadingState(reason = "server-loading") {
    premiumState = buildPremiumLoadingState({ source: reason, updatedAt: new Date().toISOString() });
    persistPremiumState();
    refreshPremiumUi();
    return premiumState;
  }

  function setGuestPremiumState(reason = "guest") {
    premiumState = buildFreePremiumState({
      source: reason,
      loaded: true,
      hasSession: false,
      status: PREMIUM_STATUS_GUEST,
      updatedAt: new Date().toISOString()
    });
    persistPremiumState();
    refreshPremiumUi();
    broadcastGntdStateChange("PREMIUM_CHANGED");
    return premiumState;
  }

  function setFreePremiumState(reason = "server:free") {
    return applyPremiumState({
      ...buildFreePremiumState({
        source: reason,
        loaded: true,
        hasSession: true,
        status: PREMIUM_STATUS_FREE
      })
    });
  }

  function resetPremiumState(reason = "free-fallback") {
    return setGuestPremiumState(reason);
  }

  function getDevPremiumUiOverride() {
    if (!DEV_TOOLS_ENABLED) return null;
    const devModeEnabled = String(localStorage.getItem(PREMIUM_DEV_MODE_KEY) || "").trim() === "1"
      || /localhost|127\.0\.0\.1/i.test(String(API_BASE || ""));

    if (!devModeEnabled) return null;

    const raw = String(localStorage.getItem(PREMIUM_DEV_UI_OVERRIDE_KEY) || "").trim();
    if (!raw || raw === "0" || raw.toLowerCase() === "off" || raw.toLowerCase() === "false") return null;

    if (["1", "true", "premium", "on"].includes(raw.toLowerCase())) {
      return {
        plan: "premium",
        billingStatus: "active",
        premiumUntil: new Date(Date.now() + (1000 * 60 * 60 * 24 * 30)).toISOString(),
        features: {
          widgetresize: true,
          photoswidget: true,
          custombackground: true,
          cloudsync: true
        },
        isPremium: true,
        loaded: true,
        hasSession: !!premiumState?.hasSession,
        status: PREMIUM_STATUS_PREMIUM,
        uiOverride: true,
        source: "dev-ui-override",
        updatedAt: new Date().toISOString()
      };
    }

    if (raw.toLowerCase() === "expired") {
      return {
        plan: "premium",
        billingStatus: "expired",
        premiumUntil: new Date(Date.now() - (1000 * 60 * 60 * 24)).toISOString(),
        features: {},
        isPremium: false,
        loaded: true,
        hasSession: !!premiumState?.hasSession,
        status: PREMIUM_STATUS_EXPIRED,
        uiOverride: true,
        source: "dev-ui-override:expired",
        updatedAt: new Date().toISOString()
      };
    }

    try {
      const parsed = JSON.parse(raw);
      const normalized = normalizePremiumPayload(parsed) || {};
      return {
        ...buildFreePremiumState(),
        ...normalized,
        hasSession: !!premiumState?.hasSession,
        loaded: true,
        uiOverride: true,
        source: "dev-ui-override:custom",
        updatedAt: new Date().toISOString()
      };
    } catch {
      return null;
    }
  }

  function getEffectivePremiumState() {
    const override = getDevPremiumUiOverride();
    if (!override) return { ...premiumState, uiOverride: false };
    return {
      ...premiumState,
      ...override,
      hasSession: premiumState?.hasSession || override?.hasSession,
      loaded: true,
      uiOverride: true
    };
  }

  function hasPremium(state = getEffectivePremiumState()) {
    if (state?.isPremium !== true) return false;
    const billingStatus = String(state?.billingStatus || "").trim().toLowerCase();
    return PREMIUM_ACTIVE_SUBSCRIPTION_STATUSES.has(billingStatus);
  }

  function hasFeature(featureName, state = getEffectivePremiumState()) {
    const key = normalizeFeatureName(featureName);
    if (!key) return false;

    if (UNLOCKED_PREMIUM_FEATURES.has(key)) {
      return true;
    }

    if (state?.features && Object.prototype.hasOwnProperty.call(state.features, key)) {
      return !!state.features[key];
    }

    return hasPremium(state) && DEFAULT_PREMIUM_FEATURES.has(key);
  }

  function hasServerFeature(featureName) {
    return hasFeature(featureName, premiumState);
  }

  function getPremiumStatus(state = getEffectivePremiumState()) {
    if (!state?.hasSession) return PREMIUM_STATUS_GUEST;
    if (!state?.loaded) return PREMIUM_STATUS_LOADING;
    if (hasPremium(state)) return PREMIUM_STATUS_PREMIUM;
    if (state?.status === PREMIUM_STATUS_EXPIRED) return PREMIUM_STATUS_EXPIRED;
    return PREMIUM_STATUS_FREE;
  }

  function formatPremiumUntil(value) {
    const iso = toIsoDate(value);
    if (!iso) return "—";

    try {
      return new Date(iso).toLocaleString(getLocale(), {
        year: "numeric",
        month: "short",
        day: "2-digit"
      });
    } catch {
      return iso.slice(0, 10);
    }
  }

  function getProfileDisplayName(email = "") {
    const nickname = String(localStorage.getItem("user.nickname") || "").trim();
    if (nickname && nickname.toLowerCase() !== "friend") return nickname;

    const welcomeName = String(document.getElementById("welcomeName")?.textContent || "").trim();
    if (welcomeName && welcomeName.toLowerCase() !== "friend") return welcomeName;

    const localPart = String(email || "").trim().split("@")[0] || "";
    if (localPart) {
      return localPart.charAt(0).toUpperCase() + localPart.slice(1);
    }

    return "Profile";
  }

  function setPremiumGateState(element, { locked = false, pending = false, badge = "PREMIUM", title = "Premium feature" } = {}) {
    if (!element) return;

    if (!element.dataset.premiumOriginalTitle) {
      element.dataset.premiumOriginalTitle = element.getAttribute("title") || "";
    }

    element.classList.add("premium-gated");
    element.classList.toggle("is-locked", !!locked);
    element.classList.toggle("is-pending", !!pending);
    if ("disabled" in element) {
      // Keep locked controls clickable so we can redirect users to premium purchase page.
      element.disabled = !!pending;
    }
    element.setAttribute("aria-disabled", (locked || pending) ? "true" : "false");

    if (pending) {
      element.removeAttribute("data-premium-badge");
      element.setAttribute("title", getPremiumCheckingText());
      return;
    }

    if (locked) {
      element.setAttribute("data-premium-badge", badge);
      element.setAttribute("title", title || element.dataset.premiumOriginalTitle || "Premium feature");
      return;
    }

    element.removeAttribute("data-premium-badge");
    element.setAttribute("title", element.dataset.premiumOriginalTitle || "");
  }

  function openPremiumUpgradePage(reason = "premium-required") {
    debugWarn("[premium] opening premium page", {
      reason,
      state: {
        isPremium: premiumState?.isPremium,
        status: premiumState?.billingStatus,
        plan: premiumState?.plan,
        currentPeriodEnd: premiumState?.premiumUntil,
        source: premiumState?.source
      }
    });
    safeOpenInNewTab(PREMIUM_UPGRADE_URL);
  }

  function showPremiumUpgradePrompt(featureLabel, reason = "premium-required") {
    showConfirmNotice(
      getPremiumRequiredTitle(),
      getPremiumUpgradePromptText(featureLabel),
      () => openPremiumUpgradePage(reason),
      {
        confirmLabel: getPremiumUpgradeButtonText(),
        cancelLabel: getNoticeTexts().cancel
      }
    );
  }

  function redirectToPremiumPage(reason = "premium-required") {
    showPremiumUpgradePrompt(null, reason);
  }

  function bindPremiumLockedRedirect() {
    if (window.__premiumLockedRedirectBound) return;
    window.__premiumLockedRedirectBound = true;

    const handleLockedTarget = (event) => {
      const target = event?.target;
      if (!(target instanceof Element)) return false;
      const locked = target.closest(".premium-gated.is-locked");
      if (!locked) return false;
      event.preventDefault();
      event.stopPropagation();
      if (typeof event.stopImmediatePropagation === "function") {
        event.stopImmediatePropagation();
      }
      redirectToPremiumPage("locked-premium-gated-element");
      return true;
    };

    document.addEventListener("click", (event) => {
      handleLockedTarget(event);
    }, true);

    document.addEventListener("keydown", (event) => {
      if (event.key !== "Enter" && event.key !== " ") return;
      handleLockedTarget(event);
    }, true);
  }

  function getPremiumFeatureLabel(featureName) {
    const map = {
      [PREMIUM_FEATURE_PHOTOS_WIDGET]: t("customize.actionAddPhotos", "Photos widget"),
      [PREMIUM_FEATURE_DASHBOARD_FOLDERS]: t("customize.actionAddFolder", "Dashboard folders"),
      [PREMIUM_FEATURE_CUSTOM_BACKGROUND]: t("customize.changeBackground", "Custom background"),
      [PREMIUM_FEATURE_WIDGET_RESIZE]: t("customize.actionWidgetSize", "Widget resizing"),
      [PREMIUM_FEATURE_WIDGET_TRANSPARENCY]: t("customize.actionWidgetTransparency", "Widgets transparency"),
      [PREMIUM_FEATURE_WALLPAPER_ROTATION]: t("customize.rotationFeatureName", "Wallpaper rotation"),
      [PREMIUM_FEATURE_CLOUD_SYNC]: t("premium.syncFeature", "Cloud sync"),
      [PREMIUM_FEATURE_DATE_TODO_PREVIEW]: t("widgets.dateTodayTodos", "Today tasks"),
      [PREMIUM_FEATURE_GOOGLE_WORKSPACE_SYNC]: t("premium.googleWorkspaceSyncFeature", "Google Calendar and Tasks sync")
    };

    return map[featureName] || t("premium.thisFeature", "This feature");
  }

