  function applyPremiumGate(element, featureName, featureLabel, state = getEffectivePremiumState()) {
    if (!element) return;

    const effectiveState = state;
    const status = getPremiumStatus(effectiveState);
    const pending = status === PREMIUM_STATUS_LOADING;
    const allowed = hasFeature(featureName, effectiveState);

    setPremiumGateState(element, {
      locked: !pending && !allowed,
      pending,
      badge: effectiveState?.uiOverride ? "DEV PRO" : "PRO",
      title: getPremiumOnlyMessage(featureLabel)
    });
  }

  function refreshThemeRotationPremiumUi(root = document) {
    const featureName = PREMIUM_FEATURE_WALLPAPER_ROTATION;
    const featureLabel = getPremiumFeatureLabel(featureName);
    const wrap = root.querySelector("#layoutThemeRotationWrap");
    if (!wrap) return;

    applyPremiumGate(wrap, featureName, featureLabel);

    wrap.querySelectorAll("#layoutThemeRotationToggle, #layoutThemeRotationCreateList, #layoutThemeRotationClearList, .theme-rotation-remove").forEach((element) => {
      applyPremiumGate(element, featureName, featureLabel);
    });
  }

  async function syncFolderWidgetsPremiumUi(state = getEffectivePremiumState()) {
    const mountEl = document.getElementById("dashArea") || document.querySelector(".widgets .dash-area");
    if (!mountEl) return;

    // Do not mutate folder widgets until premium status is resolved.
    // This prevents startup flash/remove/recreate cycles.
    const premiumStatus = getPremiumStatus(state);
    if (premiumStatus === PREMIUM_STATUS_LOADING) {
      return;
    }

    const hasRenderedFolderWidgets = !!mountEl.querySelector('.widget.folder-widget[data-instance]');
    if (hasRenderedFolderWidgets) return;
    if (folderWidgetsRestoreAttempted) return;
    if (folderWidgetsRestoreInFlight) {
      await folderWidgetsRestoreInFlight;
      return;
    }

    folderWidgetsRestoreInFlight = (async () => {
      try {
        await restoreFolderWidgets({ mountEl });
        document.dispatchEvent(new CustomEvent("layout:widgets-restored", {
          detail: { source: "premium-sync" }
        }));
      } finally {
        folderWidgetsRestoreAttempted = true;
        folderWidgetsRestoreInFlight = null;
      }
    })();

    await folderWidgetsRestoreInFlight;
  }

  function refreshPremiumUi() {
    const effectiveState = getEffectivePremiumState();
    const premiumActive = hasPremium(effectiveState);
    const premiumStatus = getPremiumStatus(effectiveState);
    const accountButton = document.getElementById("createAccountBtn");

    const accountPlanEl = document.getElementById("authAccountPlan");
    const accountPremiumUntilEl = document.getElementById("authAccountPremiumUntil");

    document.body.dataset.premiumStatus = premiumStatus;
    document.body.dataset.premiumSource = String(effectiveState?.source || "unknown");
    document.body.classList.toggle("premium-active", premiumActive);
    document.body.classList.toggle("premium-loading", premiumStatus === PREMIUM_STATUS_LOADING);
    document.body.classList.toggle("premium-ui-override", !!effectiveState?.uiOverride);

    if (accountPlanEl) {
      const planLabel = premiumStatus === PREMIUM_STATUS_LOADING
        ? "loading..."
        : (effectiveState?.uiOverride
            ? `${String(effectiveState?.plan || "free")} (dev)`
            : String(effectiveState?.plan || "free"));
      accountPlanEl.textContent = planLabel;
      accountPlanEl.classList.toggle("is-premium", premiumActive);
    }

    if (accountPremiumUntilEl) {
      accountPremiumUntilEl.textContent = premiumStatus === PREMIUM_STATUS_LOADING
        ? "Checking..."
        : (premiumActive ? formatPremiumUntil(effectiveState?.premiumUntil) : "—");
      accountPremiumUntilEl.classList.toggle("is-premium", premiumActive);
    }

    if (accountButton?.classList.contains("is-auth")) {
      if (premiumStatus === PREMIUM_STATUS_LOADING) {
        accountButton.title = "Cloud account (checking premium access)";
      } else if (effectiveState?.uiOverride) {
        accountButton.title = premiumActive ? "Cloud account (premium UI override)" : "Cloud account (dev UI override)";
      } else {
        accountButton.title = premiumActive ? "Cloud account (premium)" : "Cloud account (connected)";
      }
      accountButton.setAttribute("aria-label", accountButton.title);
    }

    [
      [document.getElementById("addPhotosBtn"), PREMIUM_FEATURE_PHOTOS_WIDGET, getPremiumFeatureLabel(PREMIUM_FEATURE_PHOTOS_WIDGET)],
      [document.getElementById("bgPickPhoto"), PREMIUM_FEATURE_CUSTOM_BACKGROUND, getPremiumFeatureLabel(PREMIUM_FEATURE_CUSTOM_BACKGROUND)],
      [document.getElementById("bgPickVideo"), PREMIUM_FEATURE_CUSTOM_BACKGROUND, getPremiumFeatureLabel(PREMIUM_FEATURE_CUSTOM_BACKGROUND)],
      [document.getElementById("bgUrlApply"), PREMIUM_FEATURE_CUSTOM_BACKGROUND, getPremiumFeatureLabel(PREMIUM_FEATURE_CUSTOM_BACKGROUND)],
      [document.getElementById("widgetSizeSm"), PREMIUM_FEATURE_WIDGET_RESIZE, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_RESIZE)],
      [document.getElementById("widgetSizeLg"), PREMIUM_FEATURE_WIDGET_RESIZE, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_RESIZE)],
      [document.getElementById("folderOpacitySlider"), PREMIUM_FEATURE_WIDGET_TRANSPARENCY, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_TRANSPARENCY)],
      [document.getElementById("layoutButtonColorPicker"), PREMIUM_FEATURE_WIDGET_TRANSPARENCY, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_TRANSPARENCY)],
      [document.getElementById("layoutButtonColorReset"), PREMIUM_FEATURE_WIDGET_TRANSPARENCY, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_TRANSPARENCY)]
    ].forEach(([element, featureName, featureLabel]) => {
      applyPremiumGate(element, featureName, featureLabel, effectiveState);
    });

    refreshCloudSyncSettingUi(effectiveState);
    if (!canUseCloudSync(effectiveState) && cloudSyncRuntimeStarted) {
      stopCloudSyncRuntime();
    }

    if (!hasFeature(PREMIUM_FEATURE_WIDGET_TRANSPARENCY, effectiveState)) {
      applyButtonColorHex("");
    }

    document.querySelectorAll("#layoutBgPickPhoto, #layoutBgPickVideo, #layoutBgUrlApply").forEach((element) => {
      applyPremiumGate(element, PREMIUM_FEATURE_CUSTOM_BACKGROUND, getPremiumFeatureLabel(PREMIUM_FEATURE_CUSTOM_BACKGROUND), effectiveState);
    });

    document.querySelectorAll(".widget.photos, .widget.photos [data-act]").forEach((element) => {
      applyPremiumGate(element, PREMIUM_FEATURE_PHOTOS_WIDGET, getPremiumFeatureLabel(PREMIUM_FEATURE_PHOTOS_WIDGET), effectiveState);
    });

    document.querySelectorAll("#btnWeatherSizeToggle, #btnDateSizeToggle, #btnSearchSizeToggle, #btnFavLayoutToggle, .widget-resize-btn, [data-act=\"size-toggle\"]").forEach((element) => {
      applyPremiumGate(element, PREMIUM_FEATURE_WIDGET_RESIZE, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_RESIZE), effectiveState);
    });

    document.querySelectorAll("#timeGoogleConnect, #timeGoogleSyncNow").forEach((element) => {
      applyPremiumGate(element, PREMIUM_FEATURE_GOOGLE_WORKSPACE_SYNC, getPremiumFeatureLabel(PREMIUM_FEATURE_GOOGLE_WORKSPACE_SYNC), effectiveState);
    });

    refreshThemeRotationPremiumUi();
    updateDateTodoPreview();
    void syncFolderWidgetsPremiumUi(effectiveState);
  }

  function showPremiumRequiredNotice(featureLabel) {
    showPremiumUpgradePrompt(featureLabel, `premium-feature-blocked:${String(featureLabel || "unknown-feature")}`);
  }

  function ensurePremiumFeature(featureName, featureLabel) {
    const effectiveState = getEffectivePremiumState();
    const premiumStatus = getPremiumStatus(effectiveState);
    if (premiumStatus === PREMIUM_STATUS_LOADING) {
      debugInfo("[premium] premium guard deferred while status is loading", {
        featureName,
        featureLabel,
        state: {
          source: effectiveState?.source,
          status: effectiveState?.billingStatus,
          loaded: effectiveState?.loaded,
          hasSession: effectiveState?.hasSession
        }
      });
      showMiniNotice(getPremiumCheckingText(), false);
      return false;
    }

    const hasPremiumAccess = hasPremium(effectiveState);
    const allowed = hasFeature(featureName, effectiveState);
    if (allowed) return true;

    debugWarn("[premium] premium guard blocked feature", {
      featureName,
      featureLabel,
      state: {
        isPremium: effectiveState?.isPremium,
        status: effectiveState?.billingStatus,
        plan: effectiveState?.plan,
        currentPeriodEnd: effectiveState?.premiumUntil,
        source: effectiveState?.source,
        hasPremiumAccess,
        featureExplicitlyEnabled: !!(effectiveState?.features && effectiveState.features[normalizeFeatureName(featureName)])
      },
      failedCheck: hasPremiumAccess
        ? "feature not enabled for current plan"
        : "requires isPremium=true and status in [active, trialing]"
    });

    showPremiumRequiredNotice(featureLabel);
    return false;
  }

  function canUseCloudSync(state = getEffectivePremiumState()) {
    return canUseFullCloudSync(state);
  }

  function buildCloudSyncGateDebug({ state = getEffectivePremiumState(), reason = "unknown", tokenPresent = false } = {}) {
    const premiumStateRaw = { ...premiumState };
    const accountStateRaw = lastPremiumRefreshPayload?.account || lastPremiumRefreshPayload?.data?.account || lastPremiumRefreshPayload?.user || null;
    const billingStateRaw = lastPremiumRefreshPayload?.billing || lastPremiumRefreshPayload?.data?.billing || lastPremiumRefreshPayload || null;
    const planValue = String(state?.plan || premiumState?.plan || "").trim();
    const isPremiumValue = state?.isPremium === true;
    const featuresValue = state?.features && typeof state.features === "object" ? state.features : {};
    const cloudSyncFeatureValue = featuresValue[normalizeFeatureName(PREMIUM_FEATURE_CLOUD_SYNC)] === true;
    const premiumUiText = document.getElementById("authAccountPlan")?.textContent || "";
    const premiumStateLoaded = !!state?.loaded;
    const resolvedIsPremium = hasPremium(state);
    const resolvedCloudSyncAllowed = canUseSharedCloudSync();
    const resolvedFullCloudSyncAllowed = canUseFullCloudSync(state);

    return {
      tokenPresent: !!tokenPresent,
      premiumStateRaw,
      accountStateRaw,
      billingStateRaw,
      planValue,
      isPremiumValue,
      featuresValue,
      cloudSyncFeatureValue,
      premiumUiText,
      premiumState: getPremiumStatus(state),
      resolvedIsPremium,
      resolvedCloudSyncAllowed,
      resolvedFullCloudSyncAllowed,
      premiumStateLoaded,
      reason
    };
  }

  function evaluateCloudSyncStartupGate({ token = "", state = getEffectivePremiumState(), reason = "startup" } = {}) {
    const tokenPresent = !!String(token || "").trim();
    const premiumStateLoaded = !!state?.loaded;
    const resolvedCloudSyncAllowed = tokenPresent && isEmailVerifiedForCloudSync();
    const resolvedFullCloudSyncAllowed = resolvedCloudSyncAllowed && hasCloudSyncPremiumEntitlement(state);

    if (!tokenPresent) {
      return { ready: true, allowed: false, reason: "no-token", tokenPresent, premiumStateLoaded, resolvedCloudSyncAllowed, resolvedFullCloudSyncAllowed };
    }

    if (!premiumStateLoaded || getPremiumStatus(state) === PREMIUM_STATUS_LOADING) {
      return { ready: false, allowed: false, reason: "premium-loading", tokenPresent, premiumStateLoaded, resolvedCloudSyncAllowed, resolvedFullCloudSyncAllowed };
    }

    if (!isEmailVerifiedForCloudSync()) {
      return { ready: true, allowed: false, reason: "email-not-verified", tokenPresent, premiumStateLoaded, resolvedCloudSyncAllowed, resolvedFullCloudSyncAllowed };
    }

    if (!hasCloudSyncPremiumEntitlement(state)) {
      return { ready: true, allowed: false, reason: "premium-required", tokenPresent, premiumStateLoaded, resolvedCloudSyncAllowed, resolvedFullCloudSyncAllowed };
    }

    if (!isCloudSyncUserEnabled()) {
      return { ready: true, allowed: false, reason: "sync-disabled", tokenPresent, premiumStateLoaded, resolvedCloudSyncAllowed, resolvedFullCloudSyncAllowed };
    }

    return { ready: true, allowed: true, reason, tokenPresent, premiumStateLoaded, resolvedCloudSyncAllowed, resolvedFullCloudSyncAllowed };
  }

  async function startCloudSyncInitialPull(reason = "premium-resolved") {
    if (cloudStartupPullTriggered) return;
    if (!canUseCloudSync()) return;
    cloudStartupPullTriggered = true;
    debugLog("[SYNC] startup sync decision", {
      reason,
      allowed: true,
      initialPullCompleted: cloudInitialSyncLoaded
    });
    debugLog("[CLOUD SYNC] starting after premium state resolved", { reason });
    startCloudSyncRuntime();
    debugLog("[CLOUD SYNC] initial GET /sync", { reason });
    await syncPullOnStartup();
    await pullServerSharedBookmarkGroups(reason);
  }

  async function refreshPremiumStateBeforeSync() {
    const token = await getCloudAuthToken();
    if (!token) return { ready: true, allowed: false, reason: "no-token" };

    try {
      await refreshPremiumAccess("startup-pre-sync", { token });
      const state = getEffectivePremiumState();
      const gate = evaluateCloudSyncStartupGate({ token, state, reason: "premium-state-resolved" });
      return {
        ready: gate.ready,
        allowed: gate.allowed,
        reason: gate.reason,
        account: lastPremiumRefreshPayload
      };
    } catch (err) {
      debugLog("[CLOUD SYNC] premium refresh failed", err);
      return { ready: true, allowed: false, reason: "premium-refresh-failed" };
    }
  }

  async function refreshPremiumAccess(reason = "manual", { token = "", payload = null } = {}) {
    const authToken = String(token || await getCloudAuthToken() || "").trim();
    if (!authToken) {
      return setGuestPremiumState(`${reason}:no-token`);
    }

    if (isDevAuthTokenValue(authToken)) {
      const storedEmail = await getCloudAuthEmail();
      const tokenEmail = extractEmailFromDevAuthToken(authToken);
      const email = String(storedEmail || tokenEmail || "").trim().toLowerCase();
      const account = getDevTestAccount(email);
      const devPayload = account ? buildDevPremiumPayload(account, email) : payload;
      const normalized = normalizePremiumPayload(devPayload);
      if (normalized) {
        lastPremiumRefreshPayload = devPayload;
        setCloudEmailVerified(true);
        debugInfo("[premium] dev auth mock state", { reason, email, plan: normalized.plan });
        return applyPremiumState({
          ...normalized,
          source: `${reason}:dev-auth`
        });
      }
      return setFreePremiumState(`${reason}:dev-auth:unknown-account`);
    }

    const previousStateSnapshot = {
      ...premiumState,
      features: premiumState?.features && typeof premiumState.features === "object"
        ? { ...premiumState.features }
        : {}
    };

    setPremiumLoadingState(`${reason}:loading`);

    debugInfo(`[premium] refresh start (reason=${reason}, endpoint=${PREMIUM_BILLING_STATUS_ENDPOINT})`);

    if (payload != null) {
      debugInfo("[premium] ignoring non-billing payload for premium decision; using billing status endpoint as single source of truth", {
        reason
      });
    }

    try {
      debugInfo(`[premium] requesting ${PREMIUM_BILLING_STATUS_ENDPOINT}`);
      const endpointPayload = await cloudApiRequest(PREMIUM_BILLING_STATUS_ENDPOINT, { method: "GET", token: authToken });
      lastPremiumRefreshPayload = endpointPayload;
      debugInfo("[premium] billing status response", endpointPayload);

      const emailVerified = getEmailVerificationState(endpointPayload);
      if (emailVerified !== null) {
        setCloudEmailVerified(emailVerified === true);
      }

      const normalized = normalizePremiumPayload(endpointPayload);
      if (!normalized) {
        debugWarn("[premium] billing status response missing required fields; keeping previous state", {
          reason,
          endpoint: PREMIUM_BILLING_STATUS_ENDPOINT
        });
        return applyPremiumState({
          ...previousStateSnapshot,
          loaded: true,
          hasSession: true,
          source: `${reason}:billing-status:invalid-response`,
          updatedAt: new Date().toISOString()
        });
      }

      debugInfo("[premium] premium decision", {
        endpoint: PREMIUM_BILLING_STATUS_ENDPOINT,
        isPremiumField: normalized.isPremium,
        isPremiumInferred: !!normalized.isPremiumInferred,
        statusField: normalized.billingStatus,
        planField: normalized.plan,
        currentPeriodEndField: normalized.premiumUntil,
        premiumGranted: normalized.isPremium === true,
        decisionReason: normalized.isPremium
          ? (normalized.isPremiumInferred
              ? "premium granted: inferred isPremium from active/trialing status and premium plan/features"
              : "premium granted: isPremium=true and status in [active, trialing]")
          : "premium denied: requires active/trialing subscription and premium entitlement signal"
      });
      debugInfo("[premium] premium decision json", JSON.stringify({
        endpoint: PREMIUM_BILLING_STATUS_ENDPOINT,
        reason,
        normalized,
        raw: endpointPayload
      }));

      return applyPremiumState({
        ...normalized,
        source: `${reason}:billing-status`
      });
    } catch (err) {
      if (isCloudHostPermissionDeniedError(err)) {
        debugWarn("[premium] host permission not granted; skipping premium refresh", { reason });
        return applyPremiumState({
          ...previousStateSnapshot,
          loaded: true,
          hasSession: true,
          source: `${reason}:host-permission-missing`,
          updatedAt: new Date().toISOString()
        });
      }

      debugWarn(`[premium] refresh failed for ${PREMIUM_BILLING_STATUS_ENDPOINT}:`, err?.message || err);
      debugWarn("[premium] keeping previous premium state after refresh failure", {
        reason,
        previous: {
          isPremium: previousStateSnapshot?.isPremium,
          status: previousStateSnapshot?.billingStatus,
          plan: previousStateSnapshot?.plan,
          currentPeriodEnd: previousStateSnapshot?.premiumUntil
        }
      });
      return applyPremiumState({
        ...previousStateSnapshot,
        loaded: true,
        hasSession: true,
        source: `${reason}:billing-status:error`,
        updatedAt: new Date().toISOString()
      });
    }
  }

  async function cancelPremiumSubscription({ token } = {}) {
    const authToken = String(token || "").trim();
    if (!authToken) {
      throw new Error("Session expired");
    }

    const attempts = [
      { path: PREMIUM_BILLING_CANCEL_ENDPOINTS[0], method: "POST" },
      { path: PREMIUM_BILLING_CANCEL_ENDPOINTS[1], method: "POST" },
      { path: PREMIUM_BILLING_CANCEL_ENDPOINTS[2], method: "POST" },
      { path: PREMIUM_BILLING_CANCEL_ENDPOINTS[0], method: "DELETE" }
    ];

    let lastError = null;
    for (const attempt of attempts) {
      try {
        const requestOptions = {
          method: attempt.method,
          token: authToken
        };

        if (attempt.method === "POST" || attempt.method === "PUT") {
          requestOptions.body = {};
        }

        return await cloudApiRequest(attempt.path, {
          ...requestOptions
        });
      } catch (err) {
        lastError = err;
        const status = Number(err?.status || 0);
        if (status === 404 || status === 405) {
          continue;
        }
        throw err;
      }
    }

    if (lastError) {
      throw lastError;
    }

    throw new Error("Cancellation endpoint unavailable");
  }

  function captureLocalSyncSnapshot() {
    const out = {};
    LOCAL_SYNC_KEYS.forEach((key) => {
      const raw = localStorage.getItem(key);
      if (raw === null) return;

      if (key === CLOUD_BG_STATE_SYNC_KEY) {
        const safeBgState = sanitizeBackgroundStateForCloud(raw);
        if (safeBgState === null) {
          debugLog("[BG SYNC] local background skipped for sync", {
            reason: getBackgroundSyncSkipReason(raw),
            state: describeBackgroundStateForLog(raw)
          });
          return;
        }
        debugLog("[BG SYNC] local background included in sync payload", {
          state: describeBackgroundStateForLog(raw)
        });
        out[key] = safeBgState;
        return;
      }

      out[key] = raw;
    });
    return out;
  }

  function sanitizeBackgroundStateForCloud(raw) {
    if (raw == null) return null;

    let state = null;
    try {
      state = typeof raw === "string" ? JSON.parse(raw) : raw;
    } catch {
      return null;
    }

    if (!state || typeof state !== "object") return null;
    const value = String(state.value || "").trim();
    if (!value) return null;

    if (/^(data:|blob:|idb:)/i.test(value)) {
      return null;
    }

    const safeState = { ...state, value };
    if (typeof safeState.binary === "string") delete safeState.binary;
    if (typeof safeState.base64 === "string") delete safeState.base64;
    return JSON.stringify(safeState);
  }

  function getBackgroundSyncSkipReason(raw) {
    if (raw == null) return "missing";
    let state = null;
    try {
      state = typeof raw === "string" ? JSON.parse(raw) : raw;
    } catch {
      return "invalid-json";
    }
    const value = String(state?.value || "").trim();
    if (!value) return "missing-value";
    if (/^data:/i.test(value)) return "data-url-not-synced";
    if (/^blob:/i.test(value)) return "blob-url-not-synced";
    if (/^idb:/i.test(value)) return "local-file-not-synced";
    return "";
  }

  function describeBackgroundStateForLog(raw) {
    if (raw == null) {
      return { present: false, reason: "missing" };
    }

    let state = null;
    try {
      state = typeof raw === "string" ? JSON.parse(raw) : raw;
    } catch {
      return { present: true, reason: "invalid-json" };
    }

    const value = String(state?.value || "").trim();
    let valueType = "missing";
    if (/^https:\/\//i.test(value)) valueType = "https-url";
    else if (/^chrome-extension:\/\//i.test(value)) valueType = "extension-url";
    else if (/^data:/i.test(value)) valueType = "data-url";
    else if (/^blob:/i.test(value)) valueType = "blob-url";
    else if (/^idb:/i.test(value)) valueType = "local-idb";
    else if (value) valueType = "other";

    return {
      present: true,
      kind: state?.kind || "",
      valueType,
      syncable: sanitizeBackgroundStateForCloud(raw) !== null,
      isDefault: isDefaultBackgroundValue(raw)
    };
  }

  async function captureChromeSyncSnapshot() {
    if (!hasChromeStorage) {
      const out = {};
      CHROME_SYNC_KEYS.forEach((key) => {
        try {
          out[key] = JSON.parse(localStorage.getItem(key) || "null");
        } catch {
          out[key] = null;
        }
      });
      for (let i = 0; i < localStorage.length; i += 1) {
        const key = localStorage.key(i);
        if (!isChromeDynamicSyncKey(key)) continue;
        try {
          out[key] = JSON.parse(localStorage.getItem(key) || "null");
        } catch {
          out[key] = null;
        }
      }
      return out;
    }

    // Fetch static keys first
    const staticData = await new Promise((resolve) => {
      chrome.storage.local.get(CHROME_SYNC_KEYS, (res) => resolve(res || {}));
    });
    const staticWithFallback = { ...staticData };
    CHROME_SYNC_KEYS.forEach((key) => {
      if (!bookmarkStorageFallbackDirtyKeys.has(key)) return;
      const raw = localStorage.getItem(key);
      if (raw == null) return;
      staticWithFallback[key] = parseLocalStorageBackupValue(raw);
    });

    // Also fetch all dynamic widget data keys
    const allStorage = await new Promise((resolve) => {
      chrome.storage.local.get(null, (res) => resolve(res || {}));
    });
    const dynamicEntries = Object.entries(allStorage).filter(
      ([k]) => isChromeDynamicSyncKey(k)
    );
    const dynamicData = Object.fromEntries(dynamicEntries);

    return { ...staticWithFallback, ...dynamicData };
  }

  async function captureSharedGroupsSyncSnapshot() {
    if (typeof syncAllSharedGroupBookmarkSnapshots === "function") {
      try { syncAllSharedGroupBookmarkSnapshots(); } catch {}
    }
    try {
      if (sharedGroups && typeof sharedGroups === "object") {
        return { [SHARED_GROUPS_SYNC_KEY]: normalizeSharedGroupState(sharedGroups) };
      }
    } catch {}

    if (!hasChromeStorage) {
      try {
        return {
          [SHARED_GROUPS_SYNC_KEY]: JSON.parse(localStorage.getItem(SHARED_GROUPS_SYNC_KEY) || "null") || {}
        };
      } catch {
        return { [SHARED_GROUPS_SYNC_KEY]: {} };
      }
    }

    return new Promise((resolve) => {
      chrome.storage.local.get([SHARED_GROUPS_SYNC_KEY], (res) => {
        resolve({ [SHARED_GROUPS_SYNC_KEY]: res?.[SHARED_GROUPS_SYNC_KEY] || {} });
      });
    });
  }

  async function buildCloudSyncPayload() {
    const meta = getCloudMeta();
    const updatedAt = toIsoDate(meta.localUpdatedAt) || new Date().toISOString();
    const fullSync = canUseFullCloudSync();
    const localSnapshot = fullSync ? captureLocalSyncSnapshot() : {};
    const chromeSnapshot = fullSync
      ? await captureChromeSyncSnapshot()
      : await captureSharedGroupsSyncSnapshot();
    const bgRaw = localStorage.getItem(CLOUD_BG_STATE_SYNC_KEY);
    debugLog("[CLOUD SYNC] build payload", {
      updatedAt,
      localKeys: Object.keys(localSnapshot),
      chromeKeys: Object.keys(chromeSnapshot || {})
    });
    debugLog("[SYNC] payload snapshot", {
      updatedAt,
      localKeys: Object.keys(localSnapshot),
      chromeKeys: Object.keys(chromeSnapshot || {}),
      hasBgState: Object.prototype.hasOwnProperty.call(localSnapshot, CLOUD_BG_STATE_SYNC_KEY)
    });
    debugLog("[BG SYNC] payload background state", {
      included: Object.prototype.hasOwnProperty.call(localSnapshot, CLOUD_BG_STATE_SYNC_KEY),
      local: describeBackgroundStateForLog(bgRaw)
    });
    return {
      updated_at: updatedAt,
      local_storage: localSnapshot,
      chrome_storage: chromeSnapshot
    };
  }

  async function getCloudAuthToken() {
    if (!hasChromeStorage) {
      return localStorage.getItem(CLOUD_AUTH_TOKEN_KEY)
        || localStorage.getItem(LEGACY_AUTH_TOKEN_KEY)
        || "";
    }
    return new Promise((resolve) => {
      chrome.storage.local.get([CLOUD_AUTH_TOKEN_KEY, LEGACY_AUTH_TOKEN_KEY], (res) => {
        const token = typeof res?.[CLOUD_AUTH_TOKEN_KEY] === "string"
          ? res[CLOUD_AUTH_TOKEN_KEY]
          : (typeof res?.[LEGACY_AUTH_TOKEN_KEY] === "string"
              ? res[LEGACY_AUTH_TOKEN_KEY]
              : (localStorage.getItem(CLOUD_AUTH_TOKEN_KEY) || localStorage.getItem(LEGACY_AUTH_TOKEN_KEY) || ""));
        resolve(token);
      });
    });
  }

  async function getToken() {
    return getCloudAuthToken();
  }

  async function getCloudAuthRefreshToken() {
    if (!hasChromeStorage) {
      return localStorage.getItem(CLOUD_AUTH_REFRESH_TOKEN_KEY) || "";
    }
    return new Promise((resolve) => {
      chrome.storage.local.get([CLOUD_AUTH_REFRESH_TOKEN_KEY], (res) => {
        const token = typeof res?.[CLOUD_AUTH_REFRESH_TOKEN_KEY] === "string"
          ? res[CLOUD_AUTH_REFRESH_TOKEN_KEY]
          : (localStorage.getItem(CLOUD_AUTH_REFRESH_TOKEN_KEY) || "");
        resolve(token);
      });
    });
  }

  async function setCloudAuthToken(token, refreshToken = null) {
    const safeToken = String(token || "").trim();
    if (!safeToken) return;
    localStorage.setItem(CLOUD_AUTH_TOKEN_KEY, safeToken);
    localStorage.setItem(LEGACY_AUTH_TOKEN_KEY, safeToken);
    if (refreshToken) {
      const safeRefreshToken = String(refreshToken).trim();
      localStorage.setItem(CLOUD_AUTH_REFRESH_TOKEN_KEY, safeRefreshToken);
    }
    if (!hasChromeStorage) {
      sessionExpiryHandled = false;
      broadcastGntdStateChange("AUTH_CHANGED");
      return;
    }
    const storageUpdate = {
      [CLOUD_AUTH_TOKEN_KEY]: safeToken,
      [LEGACY_AUTH_TOKEN_KEY]: safeToken
    };
    if (refreshToken) {
      const safeRefreshToken = String(refreshToken).trim();
      storageUpdate[CLOUD_AUTH_REFRESH_TOKEN_KEY] = safeRefreshToken;
    }
    await new Promise((resolve) => {
      chrome.storage.local.set(storageUpdate, () => resolve());
    });
    sessionExpiryHandled = false;
    broadcastGntdStateChange("AUTH_CHANGED");
  }

  async function getCloudAuthEmail() {
    if (!hasChromeStorage) {
      return String(localStorage.getItem(CLOUD_AUTH_EMAIL_KEY) || "").trim();
    }
    return new Promise((resolve) => {
      chrome.storage.local.get([CLOUD_AUTH_EMAIL_KEY], (res) => {
        const email = typeof res?.[CLOUD_AUTH_EMAIL_KEY] === "string"
          ? res[CLOUD_AUTH_EMAIL_KEY]
          : String(localStorage.getItem(CLOUD_AUTH_EMAIL_KEY) || "").trim();
        resolve(String(email || "").trim());
      });
    });
  }

  async function setCloudAuthEmail(email) {
    const safeEmail = String(email || "").trim();
    if (!safeEmail) return;
    localStorage.setItem(CLOUD_AUTH_EMAIL_KEY, safeEmail);
    await rememberRecentCloudAccount(safeEmail);
    if (!hasChromeStorage) {
      broadcastGntdStateChange("AUTH_CHANGED");
      return;
    }
    await new Promise((resolve) => {
      chrome.storage.local.set({
        [CLOUD_AUTH_EMAIL_KEY]: safeEmail
      }, () => resolve());
    });
    broadcastGntdStateChange("AUTH_CHANGED");
  }

  function normalizeRecentCloudAccount(item) {
    const email = normalizeAuthEmail(typeof item === "string" ? item : item?.email);
    if (!email) return null;
    return {
      email,
      lastUsedAt: Number(item?.lastUsedAt || Date.now()) || Date.now()
    };
  }

  async function getRecentCloudAccounts() {
    const parse = (value) => {
      try {
        const parsed = typeof value === "string" ? JSON.parse(value) : value;
        return (Array.isArray(parsed) ? parsed : [])
          .map(normalizeRecentCloudAccount)
          .filter(Boolean)
          .sort((a, b) => b.lastUsedAt - a.lastUsedAt)
          .slice(0, 5);
      } catch {
        return [];
      }
    };

    if (!hasChromeStorage) {
      return parse(localStorage.getItem(CLOUD_AUTH_RECENT_ACCOUNTS_KEY) || "[]");
    }

    return new Promise((resolve) => {
      chrome.storage.local.get([CLOUD_AUTH_RECENT_ACCOUNTS_KEY], (res) => {
        const value = res?.[CLOUD_AUTH_RECENT_ACCOUNTS_KEY]
          ?? localStorage.getItem(CLOUD_AUTH_RECENT_ACCOUNTS_KEY)
          ?? "[]";
        resolve(parse(value));
      });
    });
  }

  async function setRecentCloudAccounts(accounts) {
    const normalized = (Array.isArray(accounts) ? accounts : [])
      .map(normalizeRecentCloudAccount)
      .filter(Boolean)
      .slice(0, 5);
    const serialized = JSON.stringify(normalized);
    localStorage.setItem(CLOUD_AUTH_RECENT_ACCOUNTS_KEY, serialized);

    if (!hasChromeStorage) return;
    await new Promise((resolve) => {
      chrome.storage.local.set({ [CLOUD_AUTH_RECENT_ACCOUNTS_KEY]: normalized }, () => resolve());
    });
  }

  async function rememberRecentCloudAccount(email) {
    const safeEmail = normalizeAuthEmail(email);
    if (!safeEmail) return;
    const existing = await getRecentCloudAccounts();
    const next = [
      { email: safeEmail, lastUsedAt: Date.now() },
      ...existing.filter((item) => item.email !== safeEmail)
    ];
    await setRecentCloudAccounts(next);
  }

  function getPendingVerificationEmail() {
    return String(localStorage.getItem(CLOUD_VERIFY_PENDING_EMAIL_KEY) || "").trim();
  }

  function setPendingVerificationEmail(email) {
    const safeEmail = normalizeAuthEmail(email);
    if (!safeEmail) return;
    localStorage.setItem(CLOUD_VERIFY_PENDING_EMAIL_KEY, safeEmail);
    broadcastGntdStateChange("AUTH_CHANGED");
  }

  function clearPendingVerificationEmail() {
    localStorage.removeItem(CLOUD_VERIFY_PENDING_EMAIL_KEY);
    broadcastGntdStateChange("AUTH_CHANGED");
  }

  async function clearCloudAuthToken() {
    localStorage.removeItem(CLOUD_AUTH_TOKEN_KEY);
    localStorage.removeItem(LEGACY_AUTH_TOKEN_KEY);
    localStorage.removeItem(CLOUD_AUTH_REFRESH_TOKEN_KEY);
    localStorage.removeItem(CLOUD_AUTH_EMAIL_KEY);
    localStorage.removeItem(CLOUD_EMAIL_VERIFIED_KEY);
    localStorage.removeItem(CLOUD_VERIFY_PENDING_EMAIL_KEY);
    localStorage.removeItem(PREMIUM_STATE_KEY);
    cloudStartupPullTriggered = false;
    cloudPremiumReadyRetryScheduled = false;
    if (!hasChromeStorage) {
      broadcastGntdStateChange("AUTH_CHANGED");
      broadcastGntdStateChange("PREMIUM_CHANGED");
      return;
    }
    await new Promise((resolve) => {
      chrome.storage.local.remove([CLOUD_AUTH_TOKEN_KEY, LEGACY_AUTH_TOKEN_KEY, CLOUD_AUTH_REFRESH_TOKEN_KEY, CLOUD_AUTH_EMAIL_KEY, CLOUD_EMAIL_VERIFIED_KEY, PREMIUM_STATE_KEY], () => resolve());
    });
    broadcastGntdStateChange("AUTH_CHANGED");
    broadcastGntdStateChange("PREMIUM_CHANGED");
  }

  function extractAuthToken(payload) {
    return String(
      payload?.access_token ||
      payload?.accessToken ||
      payload?.token ||
      payload?.auth_token ||
      payload?.authToken ||
      ""
    ).trim();
  }

  function extractRefreshToken(payload, fallback = "") {
    const token = String(
      payload?.refresh_token ||
      payload?.refreshToken ||
      payload?.refresh ||
      fallback ||
      ""
    ).trim();
    return token;
  }

  function createAuthError(message, { status = 0, code = "", payload = null, isDefinitiveSessionExpiry = false, sessionExpiryReason = "" } = {}) {
    const error = new Error(String(message || "Auth error"));
    error.status = Number(status || 0);
    error.code = String(code || "").trim();
    error.payload = payload;
    error.isDefinitiveSessionExpiry = !!isDefinitiveSessionExpiry;
    error.sessionExpiryReason = String(sessionExpiryReason || "").trim();
    return error;
  }

  function isDefinitiveRefreshFailure(status, payload) {
    if (Number(status) === 401) return true;

    const code = String(payload?.code || payload?.error_code || payload?.errorCode || "").trim().toLowerCase();
    const message = String(payload?.message || payload?.error || payload?.detail || "").trim().toLowerCase();

    const definitiveCode = [
      "invalid_refresh_token",
      "refresh_token_invalid",
      "refresh_token_expired",
      "refresh_token_revoked",
      "token_revoked",
      "token_expired",
      "invalid_token"
    ];

    if (definitiveCode.includes(code)) return true;
    return /refresh\s*token.*(invalid|expired|revoked)|invalid\s*refresh|token\s*(expired|revoked)/i.test(message);
  }

  function logAuthPresence(context, accessToken, refreshToken) {
    debugLog("[AUTH]", context, {
      accessTokenPresent: !!String(accessToken || "").trim(),
      refreshTokenPresent: !!String(refreshToken || "").trim()
    });
  }

  function hasControlChars(value) {
    return /[\u0000-\u001F\u007F]/.test(String(value || ""));
  }

  function normalizeAuthEmail(value) {
    return String(value || "").trim().toLowerCase();
  }

  function validatePassword(pw) {
    const password = String(pw || "");

    if (password.length < 8) {
      return "Пароль минимум 8 символов";
    }
    if (!PASSWORD_ALLOWED_RE.test(password)) {
      return "Только латиница, без кириллицы и пробелов";
    }
    if (!PASSWORD_LOWER_RE.test(password)) {
      return "Добавь строчную букву";
    }
    if (!PASSWORD_UPPER_RE.test(password)) {
      return "Добавь заглавную букву";
    }
    if (!PASSWORD_DIGIT_RE.test(password)) {
      return "Добавь цифру";
    }
    if (!PASSWORD_SPECIAL_RE.test(password)) {
      return "Добавь спецсимвол";
    }

    return null;
  }

  function assertSafeApiPath(path) {
    const safePath = String(path || "").trim();
    if (!API_ALLOWED_PATHS.has(safePath) && !API_ALLOWED_PATH_PATTERNS.some((pattern) => pattern.test(safePath))) {
      throw new Error("Blocked API path");
    }
    return safePath;
  }

  function assertSafeApiMethod(method) {
    const safeMethod = String(method || "GET").trim().toUpperCase();
    if (!API_ALLOWED_METHODS.has(safeMethod)) {
      throw new Error("Blocked API method");
    }
    return safeMethod;
  }

  function sanitizeForJson(value) {
    if (value === null || value === undefined) return null;
    if (typeof value === "string") return value;
    if (typeof value === "number" || typeof value === "boolean") return value;

    if (Array.isArray(value)) {
      return value.map((item) => sanitizeForJson(item));
    }

    if (typeof value === "object") {
      const out = {};
      Object.entries(value).forEach(([key, itemValue]) => {
        if (key === "__proto__" || key === "prototype" || key === "constructor") return;
        if (hasControlChars(key)) return;
        out[key] = sanitizeForJson(itemValue);
      });
      return out;
    }

    return null;
  }

  function encodeSafeJsonBody(value) {
    const safeBody = sanitizeForJson(value);
    const json = JSON.stringify(safeBody ?? {});
    if (json.length > MAX_API_BODY_BYTES) {
      throw new Error("Payload is too large");
    }
    return json;
  }

  function safeOpenInNewTab(url) {
    const href = String(url || "").trim();
    if (!href) return;
    try {
      if (chrome?.tabs?.create) {
        chrome.tabs.create({ url: href });
        return;
      }
    } catch (err) {
      console.warn("[open-tab] chrome.tabs.create failed", err);
    }

    const popup = window.open(href, "_blank", "noopener,noreferrer");
    if (!popup) {
      window.location.href = href;
    }
  }

  function initPremiumReminderFlow() {
    const modal = document.getElementById("premiumReminderModal");
    const closeBtn = document.getElementById("premiumReminderClose");
    const laterBtn = document.getElementById("premiumReminderLater");
    const upgradeBtn = document.getElementById("premiumReminderUpgrade");
    const kickerEl = document.getElementById("premiumReminderKicker");
    const titleEl = document.getElementById("premiumReminderTitle");
    const textEl = document.getElementById("premiumReminderText");

    if (!modal || !closeBtn || !laterBtn || !upgradeBtn) return;

    const PREMIUM_REMINDER_OPEN_COUNT_KEY = "premiumReminder.openCount.v1";
    const PREMIUM_REMINDER_LAST_SHOWN_COUNT_KEY = "premiumReminder.lastShownOpenCount.v1";
    const PREMIUM_REMINDER_LAST_DISMISSED_COUNT_KEY = "premiumReminder.lastDismissedOpenCount.v1";
    const PREMIUM_REMINDER_PENDING_KEY = "premiumReminder.pending.v1";
    const PREMIUM_REMINDER_TRIGGER_AFTER_OPENS = 35;
    const PREMIUM_REMINDER_STATE_WAIT_MS = 2500;
    const PREMIUM_REMINDER_UI_RETRY_MS = 900;
    const PREMIUM_REMINDER_MAX_UI_RETRIES = 20;

    const copy = {
      kicker: t("premiumReminder.kicker", "Premium"),
      title: t("premiumReminder.title", "Unlock GNTD Premium"),
      text: t("premiumReminder.text", "Upgrade to Premium to unlock sync, dashboard folders, wallpaper rotation, and more."),
      later: t("premiumReminder.later", "Later"),
      upgrade: t("premiumReminder.upgrade", "Get Premium")
    };

    if (kickerEl) kickerEl.textContent = copy.kicker;
    if (titleEl) titleEl.textContent = copy.title;
    if (textEl) textEl.textContent = copy.text;
    laterBtn.textContent = copy.later;
    upgradeBtn.textContent = copy.upgrade;

    const hide = () => {
      modal.hidden = true;
    };

    const readStoredCount = (key) => (
      Math.max(0, parseInt(localStorage.getItem(key) || "0", 10) || 0)
    );

    const clearPendingReminder = () => {
      localStorage.removeItem(PREMIUM_REMINDER_PENDING_KEY);
    };

    const clearPremiumReminderState = () => {
      hide();
      clearPendingReminder();
      localStorage.removeItem(PREMIUM_REMINDER_OPEN_COUNT_KEY);
      localStorage.removeItem(PREMIUM_REMINDER_LAST_SHOWN_COUNT_KEY);
      localStorage.removeItem(PREMIUM_REMINDER_LAST_DISMISSED_COUNT_KEY);
    };

    const dismiss = () => {
      hide();
      clearPendingReminder();
      localStorage.setItem(PREMIUM_REMINDER_LAST_DISMISSED_COUNT_KEY, String(readStoredCount(PREMIUM_REMINDER_OPEN_COUNT_KEY)));
      localStorage.removeItem(PREMIUM_REMINDER_LAST_SHOWN_COUNT_KEY);
    };

    const isBlockingModalOpen = () => {
      const reviewModal = document.getElementById("reviewModal");
      const tutorialModal = document.getElementById("tutorialModal");
      const authModal = document.getElementById("authModal");
      const appNotice = document.getElementById("appNotice");

      return [reviewModal, tutorialModal, authModal, appNotice]
        .some((el) => el && !el.hidden);
    };

    const showWhenUiFree = (openCount, attempt = 0) => {
      if (hasPremium(getEffectivePremiumState())) {
        clearPremiumReminderState();
        return;
      }

      window.setTimeout(() => {
        if (hasPremium(getEffectivePremiumState())) {
          clearPremiumReminderState();
          return;
        }

        if (isBlockingModalOpen()) {
          if (attempt < PREMIUM_REMINDER_MAX_UI_RETRIES) {
            showWhenUiFree(openCount, attempt + 1);
          }
          return;
        }

        if (!hasPremium(getEffectivePremiumState())) {
          localStorage.setItem(PREMIUM_REMINDER_PENDING_KEY, "1");
          modal.hidden = false;
        }
      }, attempt === 0 ? 800 : PREMIUM_REMINDER_UI_RETRY_MS);
    };

    const incrementAndMaybeShow = () => {
      if (hasPremium(getEffectivePremiumState())) {
        clearPremiumReminderState();
        return;
      }

      const current = readStoredCount(PREMIUM_REMINDER_OPEN_COUNT_KEY);
      const nextCount = current + 1;
      const lastDismissedCount = Math.max(
        readStoredCount(PREMIUM_REMINDER_LAST_DISMISSED_COUNT_KEY),
        readStoredCount(PREMIUM_REMINDER_LAST_SHOWN_COUNT_KEY)
      );
      const reminderPending = localStorage.getItem(PREMIUM_REMINDER_PENDING_KEY) === "1";
      localStorage.setItem(PREMIUM_REMINDER_OPEN_COUNT_KEY, String(nextCount));

      if (reminderPending || nextCount - lastDismissedCount >= PREMIUM_REMINDER_TRIGGER_AFTER_OPENS) {
        localStorage.setItem(PREMIUM_REMINDER_PENDING_KEY, "1");
        showWhenUiFree(nextCount);
      }
    };

    let countedThisOpen = false;
    const resolveAndCount = () => {
      if (countedThisOpen) return;
      countedThisOpen = true;
      incrementAndMaybeShow();
    };

    closeBtn.addEventListener("click", dismiss);
    laterBtn.addEventListener("click", dismiss);
    modal.querySelector(".premium-reminder-backdrop")?.addEventListener("click", dismiss);
    upgradeBtn.addEventListener("click", () => {
      dismiss();
      safeOpenInNewTab(PREMIUM_UPGRADE_URL);
    });

    document.addEventListener("keydown", (event) => {
      if (!modal.hidden && event.key === "Escape") dismiss();
    });

    window.addEventListener("premium:state-changed", (event) => {
      const state = event?.detail?.state || getEffectivePremiumState();
      if (hasPremium(state)) {
        clearPremiumReminderState();
      }
    });

    const effectiveState = getEffectivePremiumState();
    const shouldWaitForPremiumState = hasStoredAuthToken()
      && !hasPremium(effectiveState);

    if (shouldWaitForPremiumState) {
      const timeoutId = window.setTimeout(resolveAndCount, PREMIUM_REMINDER_STATE_WAIT_MS);
      window.addEventListener("premium:state-changed", () => {
        window.clearTimeout(timeoutId);
        resolveAndCount();
      }, { once: true });
      return;
    }

    resolveAndCount();
  }

  function showSessionExpiredUI() {
    // Find or create session-expired notification container
    let container = document.getElementById("session-expired-notification");
    if (!container) {
      container = document.createElement("div");
      container.id = "session-expired-notification";
      container.className = "session-expired-modal";
      document.body.appendChild(container);
    }

    container.innerHTML = `
      <div class="session-expired-overlay"></div>
      <div class="session-expired-content">
        <div class="session-expired-icon">⏱️</div>
        <h2 class="session-expired-title">Session Expired</h2>
        <p class="session-expired-message">Your session has expired. Please log in again to continue.</p>
        <button class="session-expired-btn" id="session-expired-login-btn">Log In</button>
      </div>
    `;

    const loginBtn = container.querySelector("#session-expired-login-btn");
    if (loginBtn && authModal) {
      loginBtn.addEventListener("click", () => {
        container.remove();
        authModal.hidden = false;
        setAuthView("signin");
        emailInput?.focus();
      });
    }
  }

  async function expireSession(reason = "unknown") {
    if (sessionExpiryHandled) return;
    debugWarn("[AUTH] Expiring session", { reason });
    sessionExpiryHandled = true;
    await clearCloudAuthToken();
    resetPremiumState("session-expired");
    updateAuthButtonState(false);
    window.dispatchEvent(new CustomEvent("auth:session-expired", { detail: { reason } }));
    // Show styled UI instead of alert
    showSessionExpiredUI();
  }

  function normalizeSecureMediaUrl(raw) {
    const input = String(raw || "").trim();
    if (!input) return "";

    try {
      const parsed = new URL(input);
      const protocol = String(parsed.protocol || "").toLowerCase();
      if (protocol !== "https:") return "";
      return parsed.href;
    } catch {
      return "";
    }
  }

  function validateAuthCredentials(email, password, minPasswordLength) {
    if (!email || !password) {
      return "Enter email and password";
    }
    if (email.length > MAX_AUTH_EMAIL_LENGTH) {
      return `Email must be no more than ${MAX_AUTH_EMAIL_LENGTH} characters`;
    }
    if (!EMAIL_FORMAT_RE.test(email)) {
      return "Enter a valid email";
    }
    if (hasControlChars(email) || hasControlChars(password)) {
      return "Invalid characters in input";
    }
    const passwordError = validatePassword(password);
    if (passwordError) {
      return passwordError;
    }
    if (password.length < minPasswordLength) {
      return `Password must be at least ${minPasswordLength} characters`;
    }
    return "";
  }

  async function postPublicJson(path, data) {
    await assertCloudApiOriginAccess();
    const safePath = assertSafeApiPath(path);
    const source = (data && typeof data === "object") ? data : {};
    const payload = sanitizeForJson(source) || {};

    if (Object.prototype.hasOwnProperty.call(payload, "email")) {
      payload.email = normalizeAuthEmail(payload.email);
    }
    if (Object.prototype.hasOwnProperty.call(payload, "password")) {
      payload.password = String(payload.password ?? "");
    }

    const res = await fetch(`${API_BASE}${safePath}`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: encodeSafeJsonBody(payload),
    });
    const text = await res.text();
    let json = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = null;
    }
    if (!res.ok) {
      debugLog("[AUTH error]", safePath, res.status, text);
      const message = json?.message || json?.error || json?.detail || text || res.statusText || "Request failed";
      const error = new Error(`HTTP ${res.status}: ${message}`);
      error.status = res.status;
      error.code = String(json?.code || json?.error_code || "").trim();
      error.payload = json;
      throw error;
    }
    return json || {};
  }

  function withPersistentSession(payload = {}) {
    return {
      ...(payload || {}),
      // Multiple aliases increase compatibility with different backend contracts.
      remember_me: true,
      rememberMe: true,
      session_days: AUTH_PERSISTENT_SESSION_DAYS,
      max_age_days: AUTH_PERSISTENT_SESSION_DAYS,
      ttl_days: AUTH_PERSISTENT_SESSION_DAYS
    };
  }

  function getEmailVerificationState(payload) {
    const candidates = [
      payload,
      payload?.user,
      payload?.account,
      payload?.profile,
      payload?.data,
      payload?.data?.user,
      payload?.result,
      payload?.result?.user
    ];

    for (const candidate of candidates) {
      if (!candidate || typeof candidate !== "object") continue;

      const raw = candidate.email_verified ?? candidate.emailVerified ?? candidate.is_email_verified ?? candidate.verified;
      if (typeof raw === "boolean") return raw;
      if (typeof raw === "number") return raw === 1;
      if (typeof raw === "string") {
        const normalized = raw.trim().toLowerCase();
        if (["1", "true", "yes", "verified"].includes(normalized)) return true;
        if (["0", "false", "no", "unverified", "not_verified"].includes(normalized)) return false;
      }
    }

    return null;
  }

  function isEmailNotVerifiedError(error) {
    if (!error) return false;

    const code = String(error?.code || error?.payload?.code || error?.payload?.error_code || "").toLowerCase();
    if (["email_not_verified", "email_unverified", "unverified_email", "account_not_verified"].includes(code)) {
      return true;
    }

    const message = String(error?.message || error?.payload?.message || error?.payload?.error || "");
    return /email\s+(is\s+)?not\s+verified|verify\s+your\s+email|email\s+unverified|confirm\s+your\s+email/i.test(message);
  }

  function getAuthErrorCode(error) {
    return String(error?.code || error?.payload?.code || error?.payload?.error_code || "").trim().toLowerCase();
  }

  function getAuthErrorMessage(error) {
    return String(error?.payload?.message || error?.payload?.error || error?.message || "").trim();
  }

  function isAuthDevMode() {
    return DEV_TOOLS_ENABLED && (DEBUG_LOGS_ENABLED || /localhost|127\.0\.0\.1/i.test(String(API_BASE || "")));
  }

  function isSafeValidationMessage(raw) {
    const message = String(raw || "").trim();
    if (!message || message.length > 220) return false;
    if (/[\u0000-\u001F\u007F]/.test(message)) return false;
    if (/[<>]/.test(message)) return false;
    if (/https?:\/\//i.test(message)) return false;
    if (/token|bearer|authorization|password\s*hash|stack\s*trace|exception|sql\s*state/i.test(message)) return false;
    return true;
  }

  function isExplicitEmailNotFoundError(error) {
    if (!error) return false;

    const code = getAuthErrorCode(error);
    if (["user_not_found", "email_not_found", "user_not_registered", "email_not_registered"].includes(code)) {
      return true;
    }

    if (Number(error?.status || 0) === 404) return true;

    const message = getAuthErrorMessage(error);
    return /user\s+not\s+found|email\s+not\s+(found|registered)|account\s+not\s+found/i.test(message);
  }

  function isEmailNotVerifiedLoginError(error) {
    if (!error) return false;
    if (Number(error?.status || 0) !== 403) return false;
    const code = getAuthErrorCode(error);
    return code === "email_not_verified" || code === "email_unverified" || code === "unverified_email" || code === "account_not_verified";
  }

  function getLoginErrorMessage(error) {
    const status = Number(error?.status || 0);
    const code = getAuthErrorCode(error);

    if (code === "host_permission_denied") {
      return "Cloud access permission was not granted.";
    }

    if (status === 401) {
      return "Invalid email or password.";
    }

    if (isEmailNotVerifiedLoginError(error)) {
      return "Please verify your email first. Check your inbox or resend verification email.";
    }

    if (status === 404 || code === "email_not_found" || code === "user_not_found" || code === "email_not_registered" || code === "user_not_registered") {
      return "Email not registered. Please sign up first.";
    }

    if (status === 429 || code === "too_many_attempts" || code === "too_many_requests" || code === "rate_limited") {
      return "Too many attempts. Please try again later.";
    }

    if (status === 500 || status === 502 || status === 503) {
      return "Server error. Please try again later.";
    }

    return "Login failed. Please try again.";
  }

  function mapSignupError(error) {
    const status = Number(error?.status || 0);
    const code = getAuthErrorCode(error);
    const message = getAuthErrorMessage(error);

    if (code === "host_permission_denied") {
      return "Cloud access permission was not granted.";
    }

    if (status === 409) {
      return "This email is already registered. Please sign in or reset your password.";
    }

    if (status === 400 && isSafeValidationMessage(message)) {
      return message;
    }

    if (status === 403 && (code === "captcha_failed" || code === "captcha_invalid" || /captcha/.test(message))) {
      return "Captcha verification failed. Please try again.";
    }

    if (status === 429 || code === "too_many_attempts" || code === "too_many_requests" || code === "rate_limited") {
      return "Too many attempts. Please try again later.";
    }

    if (status === 500 || status === 502 || status === 503) {
      return "Server error. Please try again later.";
    }

    return "Sign up failed. Please try again.";
  }

  function isEmailNotRegisteredError(error) {
    if (!error) return false;

    return isExplicitEmailNotFoundError(error);
  }

  function extractVerificationEmail(payload, fallback = "") {
    const candidates = [
      payload,
      payload?.data,
      payload?.user,
      payload?.account,
      payload?.profile,
      payload?.payload,
      payload?.result
    ];

    for (const candidate of candidates) {
      if (!candidate || typeof candidate !== "object") continue;
      const raw = candidate.email ?? candidate.user_email ?? candidate.account_email;
      const normalized = normalizeAuthEmail(raw);
      if (normalized) return normalized;
    }

    return normalizeAuthEmail(fallback);
  }

  function parseVerificationRouteState() {
    const url = new URL(window.location.href);
    const params = url.searchParams;
    const hashRaw = String(url.hash || "").replace(/^#/, "");
    const hashParams = new URLSearchParams(hashRaw.startsWith("?") ? hashRaw.slice(1) : hashRaw);

    const readParam = (key) => params.get(key) || hashParams.get(key);

    const token = String(
      readParam("token")
      || readParam("verify_token")
      || readParam("verification_token")
      || ""
    ).trim();

    const status = String(readParam("status") || readParam("verify") || readParam("verified") || "").trim().toLowerCase();
    const success = status === "success" || status === "verified" || status === "1" || status === "true";

    return { token, success };
  }

  function clearVerificationRouteState() {
    try {
      const url = new URL(window.location.href);
      ["token", "verify_token", "verification_token", "status", "verify", "verified"].forEach((key) => {
        url.searchParams.delete(key);
      });

      let nextHash = url.hash;
      const hashRaw = String(url.hash || "").replace(/^#/, "");
      if (hashRaw && hashRaw.includes("=")) {
        const hashParams = new URLSearchParams(hashRaw.startsWith("?") ? hashRaw.slice(1) : hashRaw);
        ["token", "verify_token", "verification_token", "status", "verify", "verified"].forEach((key) => {
          hashParams.delete(key);
        });
        const cleanedHash = hashParams.toString();
        nextHash = cleanedHash ? `#${cleanedHash}` : "";
      }

      const next = `${url.pathname}${url.search}${nextHash}`;
      window.history.replaceState({}, "", next);
    } catch {}
  }

  async function resendVerificationEmail(email) {
    const safeEmail = normalizeAuthEmail(email);
    if (!safeEmail) throw new Error("Email is required");
    return postPublicJson("/auth/resend-email-code", { email: safeEmail });
  }

  async function verifyEmailCode(email, code) {
    const safeEmail = normalizeAuthEmail(email);
    const safeCode = String(code || "").replace(/\D/g, "").slice(0, 6);
    if (!safeEmail) throw new Error("Email is required");
    if (safeCode.length !== 6) throw new Error("Enter a valid 6-digit code");
    return postPublicJson("/auth/verify-email-code", {
      email: safeEmail,
      code: safeCode
    });
  }

  function shouldRequireEmailVerification(payload) {
    const candidates = [
      payload,
      payload?.data,
      payload?.result,
      payload?.user,
      payload?.account
    ].filter((item) => item && typeof item === "object");

    for (const candidate of candidates) {
      const raw = candidate.requiresEmailVerification ?? candidate.requires_email_verification;
      if (typeof raw === "boolean") return raw;
      if (typeof raw === "number") return raw === 1;
      if (typeof raw === "string") {
        const normalized = raw.trim().toLowerCase();
        if (["1", "true", "yes", "required"].includes(normalized)) return true;
        if (["0", "false", "no", "not_required"].includes(normalized)) return false;
      }
    }

    return getEmailVerificationState(payload) === false;
  }

  function getVerifyCodeErrorMessage(error) {
    const code = String(error?.code || error?.payload?.code || error?.payload?.error_code || "").toLowerCase();
    const message = String(error?.message || error?.payload?.message || error?.payload?.error || "");

    if (code === "host_permission_denied") {
      return "Cloud access permission was not granted.";
    }

    if (["invalid_code", "invalid_verification_code", "verification_code_invalid"].includes(code)
      || /invalid\s+code|wrong\s+code|incorrect\s+code/i.test(message)) {
      return "The code is incorrect.";
    }

    if (["code_expired", "verification_code_expired", "expired_code"].includes(code)
      || /code\s+expired|expired\s+code/i.test(message)) {
      return "The code has expired. Request a new one.";
    }

    if (["too_many_attempts", "too_many_requests", "rate_limited"].includes(code)
      || error?.status === 429
      || /too\s+many\s+attempts|too\s+many\s+requests|rate\s+limit/i.test(message)) {
      return "Too many attempts. Please wait and try again.";
    }

    if (["email_already_verified", "already_verified"].includes(code)
      || /already\s+verified/i.test(message)) {
      return "This email is already verified.";
    }

    return message || "Verification failed. Please try again.";
  }

  async function verifyEmailToken(token) {
    await assertCloudApiOriginAccess();
    const safeToken = String(token || "").trim();
    if (!safeToken) throw new Error("Verification token is missing");

    const safePath = assertSafeApiPath("/auth/verify");
    const res = await fetch(`${API_BASE}${safePath}?token=${encodeURIComponent(safeToken)}`, {
      method: "GET",
      headers: { "Accept": "application/json" }
    });

    const text = await res.text();
    let json = null;
    try {
      json = text ? JSON.parse(text) : null;
    } catch {
      json = null;
    }

    if (!res.ok) {
      const message = json?.message || json?.error || json?.detail || text || "Verification failed";
      const error = new Error(message);
      error.status = res.status;
      error.payload = json;
      throw error;
    }

    return json || { ok: true };
  }

  async function signup(email, password) {
    const normalizedEmail = normalizeAuthEmail(email);
    if (isAuthDevMode()) {
      debugLog("[AUTH signup URL]", API_BASE + "/auth/signup");
    }
    try {
      const data = await postPublicJson("/auth/signup", withPersistentSession({ email: normalizedEmail, password }));
      const token = extractAuthToken(data);
      const refreshToken = extractRefreshToken(data);
      return { token, refreshToken, data };
    } catch (error) {
      const mapped = new Error(mapSignupError(error));
      mapped.status = Number(error?.status || 0);
      mapped.code = String(error?.code || error?.payload?.code || error?.payload?.error_code || "").trim();
      mapped.payload = error?.payload || null;
      throw mapped;
    }
  }

  async function login(email, password) {
    const normalizedEmail = normalizeAuthEmail(email);
    const devAuthResult = getDevTestAuthResult(normalizedEmail, password);
    if (devAuthResult) {
      debugLog("[AUTH dev mock] login", {
        email: normalizedEmail,
        plan: devAuthResult?.data?.plan || "free"
      });
      return devAuthResult;
    }
    if (isAuthDevMode()) {
      debugLog("[AUTH login URL]", API_BASE + "/auth/login");
    }
    const data = await postPublicJson("/auth/login", withPersistentSession({ email: normalizedEmail, password }));
    const token = extractAuthToken(data);
    const refreshToken = extractRefreshToken(data);
    return { token, refreshToken, data };
  }

  function getGoogleClientId() {
    const manifestClientId = String(chrome?.runtime?.getManifest?.()?.oauth2?.client_id || "").trim();
    return String(GOOGLE_CLIENT_ID || manifestClientId || "").trim();
  }

  function launchGoogleWebAuthFlow(url) {
    return new Promise((resolve, reject) => {
      chrome.identity.launchWebAuthFlow({ url, interactive: true }, (responseUrl) => {
        const lastError = chrome.runtime?.lastError;
        if (lastError) {
          const message = String(lastError.message || "").trim();
          const cancelled = /cancel|deny|approve|closed/i.test(message);
          const error = new Error(cancelled
            ? "Google login cancelled."
            : (message || "Google login failed."));
          error.code = cancelled ? "google_oauth_cancelled" : "google_oauth_failed";
          reject(error);
          return;
        }

        if (!responseUrl) {
          const error = new Error("Google login cancelled.");
          error.code = "google_oauth_cancelled";
          reject(error);
          return;
        }

        resolve(responseUrl);
      });
    });
  }

  async function loginWithGoogle() {
    if (!chrome?.identity?.getRedirectURL || !chrome?.identity?.launchWebAuthFlow) {
      const error = new Error("Google login is unavailable in this browser.");
      error.code = "google_identity_unavailable";
      throw error;
    }

    const clientId = getGoogleClientId();
    if (!clientId) {
      const error = new Error("Google login is not configured.");
      error.code = "google_client_id_missing";
      throw error;
    }

    const redirectUri = chrome.identity.getRedirectURL();
    console.info("[AUTH Google] Register this redirect URI in Google Cloud OAuth:", redirectUri);
    const authUrl = new URL("https://accounts.google.com/o/oauth2/v2/auth");
    authUrl.searchParams.set("client_id", clientId);
    authUrl.searchParams.set("redirect_uri", redirectUri);
    authUrl.searchParams.set("response_type", "code");
    authUrl.searchParams.set("scope", "openid email profile");
    authUrl.searchParams.set("prompt", "select_account");

    const responseUrl = await launchGoogleWebAuthFlow(authUrl.toString());
    const parsedUrl = new URL(responseUrl);
    const errorParam = parsedUrl.searchParams.get("error");
    if (errorParam) {
      throw new Error(`Google login failed: ${errorParam}`);
    }

    let code = String(parsedUrl.searchParams.get("code") || "").trim();
    if (!code && parsedUrl.hash) {
      const hashParams = new URLSearchParams(parsedUrl.hash.replace(/^#/, ""));
      code = String(hashParams.get("code") || "").trim();
    }
    if (!code) {
      throw new Error("Google login failed: no authorization code was returned.");
    }

    const data = await cloudApiRequest("/auth/google", {
      method: "POST",
      body: { code, redirectUri }
    }, false);
    const token = extractAuthToken(data);
    if (!token) {
      throw new Error("Google login failed: token was not returned by server.");
    }

    const refreshToken = extractRefreshToken(data);
    return { token, refreshToken, data };
  }

  async function deleteAccount() {
    const token = await getCloudAuthToken();
    if (!token) {
      throw new Error("You are not logged in");
    }

    const attempts = [
      { path: ACCOUNT_DELETE_ENDPOINTS[0], method: "DELETE" },
      { path: ACCOUNT_DELETE_ENDPOINTS[0], method: "POST", body: { confirm: "DELETE", action: "delete_account" } },
      { path: ACCOUNT_DELETE_ENDPOINTS[1], method: "DELETE" },
      { path: ACCOUNT_DELETE_ENDPOINTS[1], method: "POST", body: { confirm: "DELETE", action: "delete_account" } },
      { path: ACCOUNT_DELETE_ENDPOINTS[2], method: "POST", body: { confirm: "DELETE", action: "delete_account" } },
      { path: ACCOUNT_DELETE_ENDPOINTS[3], method: "POST", body: { confirm: "DELETE", action: "delete_account" } }
    ];

    let lastError = null;
    for (const attempt of attempts) {
      try {
        return await cloudApiRequest(attempt.path, {
          method: attempt.method,
          token,
          body: attempt.body || null
        });
      } catch (err) {
        lastError = err;
        const status = Number(err?.status || 0);
        const isNetworkMethodMismatch = err?.name === "TypeError";
        if (status === 404 || status === 405 || status === 415 || status === 422 || isNetworkMethodMismatch) {
          continue;
        }
        throw err;
      }
    }

    if (lastError) {
      throw lastError;
    }

    return { ok: true };
  }

  async function clearLocalUserState() {
    const localKeys = new Set([
      ...Array.from(LOCAL_SYNC_KEYS),
      CLOUD_META_KEY,
      CLOUD_AUTH_TOKEN_KEY,
      LEGACY_AUTH_TOKEN_KEY,
      CLOUD_AUTH_REFRESH_TOKEN_KEY,
      CLOUD_AUTH_EMAIL_KEY,
      CLOUD_EMAIL_VERIFIED_KEY,
      CLOUD_VERIFY_PENDING_EMAIL_KEY,
      PREMIUM_STATE_KEY,
      "token"
    ]);

    localKeys.forEach((key) => {
      try {
        localStorage.removeItem(key);
      } catch {}
    });

    if (!hasChromeStorage) return;

    const chromeKeys = new Set([
      ...CHROME_SYNC_KEYS,
      ...Array.from(LOCAL_SYNC_KEYS),
      CLOUD_META_KEY,
      CLOUD_AUTH_TOKEN_KEY,
      LEGACY_AUTH_TOKEN_KEY,
      CLOUD_AUTH_REFRESH_TOKEN_KEY,
      CLOUD_AUTH_EMAIL_KEY,
      CLOUD_EMAIL_VERIFIED_KEY,
      PREMIUM_STATE_KEY,
      "token"
    ]);

    await new Promise((resolve) => {
      chrome.storage.local.remove(Array.from(chromeKeys), () => resolve());
    });
  }

  async function refreshAuthToken() {
    if (authRefreshInProgress) {
      return new Promise((resolve, reject) => {
        authRefreshQueue.push({ resolve, reject });
      });
    }

    authRefreshInProgress = true;
    let refreshedAccessToken = "";
    let refreshError = null;

    try {
      await assertCloudApiOriginAccess({ interactive: false });
      const refreshToken = await getCloudAuthRefreshToken();
      logAuthPresence("Refresh requested", await getCloudAuthToken(), refreshToken);

      if (!refreshToken) {
        throw createAuthError("No refresh token available", {
          isDefinitiveSessionExpiry: true,
          sessionExpiryReason: "missing-refresh-token"
        });
      }

      const safePath = assertSafeApiPath("/auth/refresh");
      try {
        const res = await fetch(`${API_BASE}${safePath}`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Accept": "application/json"
          },
          body: encodeSafeJsonBody(withPersistentSession({
            refresh_token: refreshToken,
            refreshToken
          }))
        });

        const text = await res.text();
        let json = null;
        try {
          json = text ? JSON.parse(text) : null;
        } catch {
          json = null;
        }

        if (!res.ok) {
          const definitive = isDefinitiveRefreshFailure(res.status, json);
          const message = json?.message || json?.error || json?.detail || `Refresh failed (${res.status})`;
          debugWarn("[AUTH] Refresh failed", {
            status: res.status,
            definitive,
            code: json?.code || json?.error_code || null,
            message
          });
          throw createAuthError(message, {
            status: res.status,
            code: json?.code || json?.error_code || "",
            payload: json,
            isDefinitiveSessionExpiry: definitive,
            sessionExpiryReason: definitive ? "refresh-token-invalid" : "refresh-temporary-failure"
          });
        }

        const newAccessToken = extractAuthToken(json);
        if (!newAccessToken) {
          throw createAuthError("Refresh response missing access token", {
            status: res.status,
            payload: json,
            isDefinitiveSessionExpiry: false,
            sessionExpiryReason: "refresh-missing-access-token"
          });
        }

        const newRefreshToken = extractRefreshToken(json, refreshToken);
        await setCloudAuthToken(newAccessToken, newRefreshToken);
        refreshedAccessToken = newAccessToken;
        debugLog("[AUTH] Refresh success", {
          newAccessTokenPresent: !!newAccessToken,
          newRefreshTokenPresent: !!newRefreshToken
        });
        return newAccessToken;
      } catch (err) {
        if (err?.isDefinitiveSessionExpiry) {
          throw err;
        }

        if (err?.name === "TypeError") {
          throw createAuthError("Network error during token refresh", {
            payload: { message: err?.message || "network error" },
            isDefinitiveSessionExpiry: false,
            sessionExpiryReason: "refresh-network-failure"
          });
        }

        throw err;
      }
    } catch (err) {
      refreshError = err;
      debugWarn("[AUTH] refreshAuthToken error", {
        message: err?.message,
        status: err?.status,
        definitive: !!err?.isDefinitiveSessionExpiry,
        reason: err?.sessionExpiryReason || ""
      });
      throw err;
    } finally {
      authRefreshInProgress = false;
      const queue = authRefreshQueue;
      authRefreshQueue = [];
      if (refreshError) {
        queue.forEach(({ reject }) => reject(refreshError));
      } else {
        queue.forEach(({ resolve }) => resolve(refreshedAccessToken));
      }
    }
  }

  async function cloudApiRequest(path, { method = "GET", body = null, token = "" } = {}, retryOnRefresh = true) {
    await assertCloudApiOriginAccess({ interactive: retryOnRefresh && !!navigator?.userActivation?.isActive });
    const safePath = assertSafeApiPath(path);
    const safeMethod = assertSafeApiMethod(method);
    const hasBody = body !== null && body !== undefined;
    const headers = {};
    if (hasBody) headers["Content-Type"] = "application/json";
    if (token) headers.Authorization = `Bearer ${token}`;

    let res;
    try {
      res = await fetch(`${API_BASE}${safePath}`, {
        method: safeMethod,
        headers,
        body: hasBody ? encodeSafeJsonBody(body) : undefined
      });
    } catch (err) {
      debugWarn("[AUTH] Request failed before response", {
        path: safePath,
        method: safeMethod,
        message: err?.message || "network failure"
      });
      throw err;
    }

    let json = null;
    try {
      json = await res.json();
    } catch {
      json = null;
    }

    if (res.status === 401 && retryOnRefresh) {
      debugWarn("[AUTH] Protected request returned 401, attempting refresh", {
        path: safePath,
        method: safeMethod,
        hadAccessToken: !!token
      });
      try {
        const newToken = await refreshAuthToken();
        return cloudApiRequest(path, { method, body, token: newToken }, false);
      } catch (err) {
        if (err?.isDefinitiveSessionExpiry) {
          await expireSession(err?.sessionExpiryReason || "refresh-definitive-failure");
          throw createAuthError("Session expired", {
            status: 401,
            code: err?.code || "",
            payload: err?.payload || null,
            isDefinitiveSessionExpiry: true,
            sessionExpiryReason: err?.sessionExpiryReason || "refresh-definitive-failure"
          });
        }

        debugWarn("[AUTH] Refresh failed due to transient reason, keeping session", {
          reason: err?.sessionExpiryReason || "unknown",
          status: err?.status || 0,
          message: err?.message || ""
        });

        throw createAuthError(err?.message || "Auth refresh temporary failure", {
          status: err?.status || res.status,
          code: err?.code || "",
          payload: err?.payload || json,
          isDefinitiveSessionExpiry: false,
          sessionExpiryReason: err?.sessionExpiryReason || "refresh-temporary-failure"
        });
      }
    }

    if (!res.ok) {
      const message =
        json?.message ||
        json?.error ||
        `Request failed (${res.status})`;
      throw createAuthError(message, {
        status: res.status,
        code: json?.code || json?.error_code || "",
        payload: json,
        isDefinitiveSessionExpiry: false
      });
    }

    return json;
  }

  function markCloudLocalUpdated(reason = "unknown", { allowBeforeInitialSync = false } = {}) {
    if (!canUseCloudSync()) {
      debugLog("[SYNC] local change ignored", { reason, canUseCloudSync: false });
      return;
    }
    if (!canUseFullCloudSync() && String(reason || "") !== SHARED_GROUPS_SYNC_KEY) {
      debugLog("[SYNC] free shared-only sync ignored personal key", { reason });
      return;
    }
    if (cloudApplyingRemote) return;
    if (gntdBroadcastHandling) return;
    // Ignore bootstrap writes until startup/login sync resolves the initial winner.
    if (!cloudInitialSyncLoaded && !allowBeforeInitialSync) {
      debugLog("[CLOUD SYNC] local change ignored before initial sync settles", {
        inProgress: cloudInitialSyncInProgress
      });
      debugLog("[SYNC] local change ignored before initial pull complete", {
        reason,
        inProgress: cloudInitialSyncInProgress,
        initialPullCompleted: cloudInitialSyncLoaded
      });
      return;
    }
    debugLog("[SYNC] local change detected", { key: reason });
    cloudDirty = true;
    debugLog("[SYNC] cloudDirty=true", { reason });
    if (reason === CLOUD_BG_STATE_SYNC_KEY) {
      debugLog("[BG SYNC] local background queued for sync");
    }
    setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCING);
    setCloudMeta({ localUpdatedAt: new Date().toISOString() });
    schedulePush();
  }

  function schedulePush() {
    if (!cloudDirty) return;
    clearTimeout(cloudSaveTimer);
    const delay = Math.max(0, cloudPushBlockedUntil - Date.now(), CLOUD_SYNC_DEBOUNCE_MS);
    debugLog("[SYNC] push scheduled", { debounceMs: delay });
    cloudSaveTimer = setTimeout(() => {
      syncPushLatestState("debounced");
    }, delay);
  }

  function scheduleCloudSave() {
    schedulePush();
  }

  function applyLocalSnapshot(localSnapshot) {
    const incoming = (localSnapshot && typeof localSnapshot === "object") ? localSnapshot : {};
    debugLog("[CLOUD SYNC] applying local snapshot", {
      keys: Object.keys(incoming)
    });
    LOCAL_SYNC_KEYS.forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(incoming, key) && incoming[key] != null) {
        if (key === CLOUD_BG_STATE_SYNC_KEY) {
          debugLog("[BG SYNC] remote bg.state.v2 found");
        }
        localStorage.setItem(key, String(incoming[key]));
      } else {
        if (key === CLOUD_BG_STATE_SYNC_KEY) return;
        localStorage.removeItem(key);
      }
    });
    debugLog("[SYNC] remote local data applied", {
      localKeys: Object.keys(incoming)
    });
  }

  async function applyChromeSnapshot(chromeSnapshot, { partial = false } = {}) {
    const incoming = (chromeSnapshot && typeof chromeSnapshot === "object") ? chromeSnapshot : {};

    // Collect all keys to handle: static keys + dynamic widget data keys from remote
    const allIncomingKeys = Object.keys(incoming);
    const remoteDynamicKeys = allIncomingKeys.filter((k) => isChromeDynamicSyncKey(k));
    const remoteDynamicKeySet = new Set(remoteDynamicKeys);

    if (!hasChromeStorage) {
      const keysToApply = partial ? Object.keys(incoming) : CHROME_SYNC_KEYS;
      keysToApply.forEach((key) => {
        if (Object.prototype.hasOwnProperty.call(incoming, key) && incoming[key] != null) {
          localStorage.setItem(key, JSON.stringify(incoming[key]));
        } else if (!partial) {
          localStorage.removeItem(key);
        }
      });
      if (!partial) {
        const staleDynamicKeys = [];
        for (let i = 0; i < localStorage.length; i += 1) {
          const key = localStorage.key(i);
          if (isChromeDynamicSyncKey(key) && !remoteDynamicKeySet.has(key)) {
            staleDynamicKeys.push(key);
          }
        }
        staleDynamicKeys.forEach((key) => localStorage.removeItem(key));
      }
      remoteDynamicKeys.forEach((key) => {
        if (incoming[key] != null) {
          localStorage.setItem(key, JSON.stringify(incoming[key]));
        } else {
          localStorage.removeItem(key);
        }
      });
      return;
    }

    const toSet = {};
    const toRemove = new Set();
    const keysToApply = partial ? Object.keys(incoming) : CHROME_SYNC_KEYS;
    keysToApply.forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(incoming, key) && incoming[key] != null) {
        toSet[key] = incoming[key];
      } else if (!partial) {
        toRemove.add(key);
      }
    });
    if (!partial) {
      const existingStorage = await new Promise((resolve) => chrome.storage.local.get(null, (res) => resolve(res || {})));
      Object.keys(existingStorage)
        .filter((key) => isChromeDynamicSyncKey(key) && !remoteDynamicKeySet.has(key))
        .forEach((key) => toRemove.add(key));
    }
    // Apply dynamic widget data keys from remote
    remoteDynamicKeys.forEach((key) => {
      if (incoming[key] != null) {
        toSet[key] = incoming[key];
      } else {
        toRemove.add(key);
      }
    });

    if (Object.keys(toSet).length) {
      await new Promise((resolve) => chrome.storage.local.set(toSet, () => resolve()));
    }
    const keysToRemove = Array.from(toRemove);
    if (keysToRemove.length) {
      await new Promise((resolve) => chrome.storage.local.remove(keysToRemove, () => resolve()));
    }
    debugLog("[SYNC] remote chrome data applied", {
      chromeSetKeys: Object.keys(toSet),
      chromeRemovedKeys: keysToRemove
    });
  }

  async function applyRemoteCloudPayload(payload) {
    const data = payload && typeof payload === "object" ? payload : {};
    const sharedGroupsOnly = isSharedGroupsOnlyCloudPayload(data);
    const hasRemoteBackground = Object.prototype.hasOwnProperty.call(data.local_storage || {}, CLOUD_BG_STATE_SYNC_KEY)
      && data.local_storage?.[CLOUD_BG_STATE_SYNC_KEY] != null;
    cloudApplyingRemote = true;
    debugLog("[CLOUD SYNC] 📥 applyRemoteCloudPayload start", { hasLocalStorage: !!data.local_storage, hasChrome: !!data.chrome_storage });
    debugLog("[SYNC] remote data keys received", {
      localKeys: Object.keys(data.local_storage || {}),
      chromeKeys: Object.keys(data.chrome_storage || {})
    });
    try {
      if (!sharedGroupsOnly) {
        applyLocalSnapshot(data.local_storage);
        debugLog("[CLOUD SYNC] 📥 Local snapshot applied");
      }
      await applyChromeSnapshot(data.chrome_storage, { partial: sharedGroupsOnly });
      debugLog("[CLOUD SYNC] 📥 Chrome snapshot applied");
    } finally {
      cloudApplyingRemote = false;
    }
    debugLog("[CLOUD SYNC] 📥 applyRemoteCloudPayload complete");
    debugLog("[SYNC] remote data applied");
    if (hasRemoteBackground) {
      await applySyncedBackgroundToUi();
    }
  }

  async function applySyncedBackgroundToUi() {
    try {
      await applySavedOrDefaultBackground();
      debugLog("[BG SYNC] remote background applied");
    } catch (err) {
      debugWarn("[BG SYNC] remote background apply failed", err?.message || err);
    }
  }

  function getRemoteBackgroundStateRaw(payload) {
    const localStoragePayload = payload?.local_storage;
    if (!localStoragePayload || typeof localStoragePayload !== "object") return null;
    if (!Object.prototype.hasOwnProperty.call(localStoragePayload, CLOUD_BG_STATE_SYNC_KEY)) return null;
    const raw = localStoragePayload[CLOUD_BG_STATE_SYNC_KEY];
    return raw == null ? null : String(raw);
  }

  async function applyRemoteBackgroundStateOnly(payload) {
    const remoteRaw = getRemoteBackgroundStateRaw(payload);
    if (!remoteRaw) return false;

    try {
      cloudApplyingRemote = true;
      localStorage.setItem(CLOUD_BG_STATE_SYNC_KEY, remoteRaw);
    } finally {
      cloudApplyingRemote = false;
    }

    debugLog("[BG SYNC] remote bg.state.v2 found");
    await applySyncedBackgroundToUi();
    return true;
  }

  function shouldProtectRemoteBackgroundFromLocalPush(remotePayload) {
    const remoteRaw = getRemoteBackgroundStateRaw(remotePayload);
    if (!remoteRaw) return false;

    const localRaw = localStorage.getItem(CLOUD_BG_STATE_SYNC_KEY);
    if (localRaw === remoteRaw) return false;

    return (!localRaw || isDefaultBackgroundValue(localRaw)) && isCustomBackgroundValue(remoteRaw);
  }

  function shouldApplyRemoteBackgroundOnStartup(remotePayload) {
    const remoteRaw = getRemoteBackgroundStateRaw(remotePayload);
    if (!remoteRaw) return false;

    const localRaw = localStorage.getItem(CLOUD_BG_STATE_SYNC_KEY);
    if (localRaw === remoteRaw) return false;

    return !localRaw || isDefaultBackgroundValue(localRaw);
  }

  function queueLocalBackgroundSyncIfRemoteMissing(remotePayload) {
    if (getRemoteBackgroundStateRaw(remotePayload)) return false;

    const localRaw = localStorage.getItem(CLOUD_BG_STATE_SYNC_KEY);
    if (!localRaw || isDefaultBackgroundValue(localRaw)) return false;

    const safeBgState = sanitizeBackgroundStateForCloud(localRaw);
    if (safeBgState === null) {
      debugLog("[BG SYNC] local background skipped for sync", {
        reason: getBackgroundSyncSkipReason(localRaw),
        state: describeBackgroundStateForLog(localRaw)
      });
      return false;
    }

    cloudDirty = true;
    setCloudMeta({ localUpdatedAt: new Date().toISOString() });
    debugLog("[BG SYNC] local background queued for sync", {
      state: describeBackgroundStateForLog(localRaw)
    });
    schedulePush();
    return true;
  }

  function refreshUiAfterCloudApply() {
    debugLog("[CLOUD SYNC] refreshing UI after cloud apply");
    // Call registered widget render functions
    callWidgetRender("todos");
    callWidgetRender("bookmarks");
    callWidgetRender("notes");
    callWidgetRender("favorites");
    callWidgetRender("welcome");
    callWidgetRender("layout");
    loadWidgetSizes?.();
    const scale = localStorage.getItem("widget.scale.v1") || "md";
    applyWidgetScale?.(scale);
    loadUiButtonColor?.().then((buttonColor) => applyButtonColorHex?.(buttonColor || "")).catch(() => {});

    // Re-mount dynamic widgets from updated storage
    const widgetMountEl = document.getElementById("dashArea") || document.querySelector(".widgets .dash-area");
    if (widgetMountEl) {
      Promise.all([
        restorePhotosWidgets({ mountEl: widgetMountEl }),
        restoreFolderWidgets({ mountEl: widgetMountEl })
      ])
        .then(() => {
          callWidgetRender("layout");
          loadWidgetSizes?.();
          refreshPremiumUi?.();
          document.dispatchEvent(new CustomEvent("layout:widgets-restored", {
            detail: { source: "cloud-sync" }
          }));
        })
        .catch(() => {});
    }
    debugLog("[CLOUD SYNC] UI refresh after cloud apply completed");
    debugLog("[SYNC] UI re-render after remote apply", {
      widgets: ["todos", "notes", "bookmarks", "favorites", "layout", "folders", "photos"]
    });
  }

  function hookCloudChangeTracking() {
    if (!CLOUD_SYNC_ENABLED) return;

    if (!window.__cloudLocalStoragePatched) {
      const rawSetItem = localStorage.setItem.bind(localStorage);
      const rawRemoveItem = localStorage.removeItem.bind(localStorage);

      localStorage.setItem = function patchedSetItem(key, value) {
        rawSetItem(key, value);
        if (!cloudApplyingRemote && LOCAL_SYNC_KEYS.has(String(key))) {
          if (cloudInitialSyncInProgress) {
            debugLog("[CLOUD SYNC] 🔧 localStorage.setItem('%s') during initial sync", key);
          }
          debugLog("[SYNC] local storage key change detected", { key: String(key), action: "set" });
          markCloudLocalUpdated(String(key));
        }
      };

      localStorage.removeItem = function patchedRemoveItem(key) {
        rawRemoveItem(key);
        if (!cloudApplyingRemote && LOCAL_SYNC_KEYS.has(String(key))) {
          if (cloudInitialSyncInProgress) {
            debugLog("[CLOUD SYNC] 🔧 localStorage.removeItem('%s') during initial sync", key);
          }
          debugLog("[SYNC] local storage key change detected", { key: String(key), action: "remove" });
          markCloudLocalUpdated(String(key));
        }
      };

      window.__cloudLocalStoragePatched = true;
    }

    if (hasChromeStorage && chrome?.storage?.onChanged && !window.__cloudChromeWatchAdded) {
      chrome.storage.onChanged.addListener((changes, area) => {
        if (area !== "local" || cloudApplyingRemote || cloudStorageEchoSuppressions > 0) return;
        const keys = Object.keys(changes || {});
        const trackedKeys = keys.filter(
          (k) => CHROME_SYNC_KEYS.includes(k) || isChromeDynamicSyncKey(k)
        );
        if (trackedKeys.length) {
          trackedKeys.forEach((key) => {
            debugLog("[SYNC] chrome.storage key change detected", { key });
          });
          const reasonKey = trackedKeys.includes(SHARED_GROUPS_SYNC_KEY)
            ? SHARED_GROUPS_SYNC_KEY
            : (trackedKeys[0] || "chrome.storage.local");
          markCloudLocalUpdated(reasonKey);
        }
      });
      window.__cloudChromeWatchAdded = true;
    }
  }

  async function syncPushLatestState(pushReason = "manual") {
    if (!canUseCloudSync()) return;
    const token = await getCloudAuthToken();
    if (!token || cloudSyncBusy || !cloudDirty) return;
    debugLog("[SYNC] push start", {
      reason: pushReason,
      tokenPresent: !!token,
      cloudDirty,
      initialPullCompleted: cloudInitialSyncLoaded
    });
    setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCING);
    
    // ⛔ GUARD: Don't push until initial sync has loaded remote state
    if (!cloudInitialSyncLoaded) {
      debugLog("[CLOUD SYNC] ⛔ PUT /sync blocked - initial sync not yet loaded");
      debugLog("[BG SYNC] PUT blocked because initial pull not completed");
      debugLog("[SYNC] push blocked", { reason: "initial-pull-not-complete" });
      schedulePush();
      return;
    }
    
    if (Date.now() < cloudPushBlockedUntil) {
      debugLog("[SYNC] push delayed by backoff", {
        retryAfterMs: cloudPushBlockedUntil - Date.now()
      });
      schedulePush();
      return;
    }

    cloudSyncBusy = true;
    try {
      const payload = await buildCloudSyncPayload();
      const payloadSize = JSON.stringify({ data_json: payload }).length;
      debugLog("[SYNC] PUT /sync started", { reason: pushReason });
      debugLog("[CLOUD SYNC] push payload prepared", {
        localUpdatedAt: payload.updated_at,
        payloadSize,
        payloadLimit: MAX_SYNC_PAYLOAD_BYTES,
        includedLocalKeys: Object.keys(payload.local_storage || {}),
        includedChromeKeys: Object.keys(payload.chrome_storage || {})
      });
      debugLog("[SYNC] push payload", {
        sizeBytes: payloadSize,
        localKeys: Object.keys(payload.local_storage || {}),
        chromeKeys: Object.keys(payload.chrome_storage || {})
      });
      if (payloadSize > MAX_SYNC_PAYLOAD_BYTES) {
        debugWarn(`Cloud push skipped: payload too large (${payloadSize} bytes)`);
        window.dispatchEvent(new CustomEvent("cloud:sync-error", { detail: { message: "Sync payload too large" } }));
        cloudDirty = false;
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
        return;
      }
      const response = await cloudApiRequest("/sync", {
        method: "PUT",
        token,
        body: { data_json: payload }
      });
      await refreshPremiumAccess("sync-push", { token, payload: response });
      const remoteUpdatedAt = toIsoDate(response?.updated_at || payload.updated_at) || payload.updated_at;
      setCloudMeta({
        localUpdatedAt: payload.updated_at,
        lastCloudUpdatedAt: remoteUpdatedAt,
        lastRemoteUpdatedAt: remoteUpdatedAt,
        lastPushedAt: new Date().toISOString()
      });
      cloudDirty = false;
      setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCED);
      debugLog("[SYNC] push success", { updated_at: remoteUpdatedAt });
      broadcastGntdStateChange("SYNC_PUSH_COMPLETED");
    } catch (err) {
      if (err?.status === 429) {
        cloudPushBlockedUntil = Date.now() + CLOUD_RATE_LIMIT_BACKOFF_MS;
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
        schedulePush();
      } else if (err?.status === 413) {
        cloudDirty = false;
        window.dispatchEvent(new CustomEvent("cloud:sync-error", { detail: { message: "Sync payload too large" } }));
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
      } else {
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
      }
      debugWarn("Cloud push failed:", err?.message || err);
      debugLog("[SYNC] push failure", {
        status: err?.status || 0,
        message: err?.message || "unknown"
      });
    } finally {
      cloudSyncBusy = false;
    }
  }

  async function syncPullIfNeeded(reason = "manual", force = false) {
    if (!canUseCloudSync()) return;
    const token = await getCloudAuthToken();
    if (!token) return;
    setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCING);

    const isStartupPull = reason === "startup" && force;
    if (cloudPullBusy) return;
    if (!force && Date.now() < cloudPullBlockedUntil) return;

    if (isStartupPull) {
      cloudInitialSyncLoaded = false;
      cloudInitialSyncInProgress = true;
      debugLog("[CLOUD SYNC] 🚀 GET /sync STARTING (startup pull to restore remote data)");
      debugLog("[BG SYNC] initial pull started");
      debugLog("[SYNC] initial pull start");
    }

    const localMeta = getCloudMeta();
    const lastPulledAtTs = localMeta?.lastPulledAt ? Date.parse(localMeta.lastPulledAt) : 0;
    if (!force && Number.isFinite(lastPulledAtTs) && lastPulledAtTs > 0) {
      const elapsed = Date.now() - lastPulledAtTs;
      if (elapsed >= 0 && elapsed < CLOUD_PULL_MIN_INTERVAL_MS) {
        return;
      }
    }

    cloudPullBusy = true;
    try {
      debugLog("[CLOUD SYNC] 📡 GET /sync request (reason: %s, force: %s)", reason, force);
      const response = await cloudApiRequest("/sync", { method: "GET", token });
      const dataJson = normalizeCloudDataJson(response?.data_json);
      if (response && response.data_json !== dataJson) {
        response.data_json = dataJson;
      }
      debugLog("[SYNC] initial pull response", {
        hasDataJson: !!dataJson,
        updatedAt: response?.updated_at || dataJson?.updated_at,
        localKeys: Object.keys(dataJson?.local_storage || {}),
        chromeKeys: Object.keys(dataJson?.chrome_storage || {}),
        hasBgState: Object.prototype.hasOwnProperty.call(dataJson?.local_storage || {}, CLOUD_BG_STATE_SYNC_KEY)
      });
      const remoteBgRaw = getRemoteBackgroundStateRaw(dataJson);
      if (remoteBgRaw) {
        debugLog("[BG SYNC] remote bg.state.v2 found", {
          state: describeBackgroundStateForLog(remoteBgRaw)
        });
      } else {
        debugLog("[BG SYNC] remote bg.state.v2 missing from GET", {
          hasDataJson: !!dataJson,
          localKeys: Object.keys(dataJson?.local_storage || {}),
          local: describeBackgroundStateForLog(localStorage.getItem(CLOUD_BG_STATE_SYNC_KEY))
        });
      }
      debugLog("[CLOUD SYNC] pull response received", { remoteTimestamp: response?.updated_at, hasData: !!response?.data_json, reason });
      
      await refreshPremiumAccess("sync-pull", { token, payload: response });
      const remotePayload = normalizeCloudDataJson(response?.data_json);
      const remoteUpdatedAt = toIsoDate(response?.updated_at || remotePayload?.updated_at);
      const localUpdatedAt = toIsoDate(localMeta.localUpdatedAt);
      const lastCloudUpdatedAt = toIsoDate(localMeta.lastCloudUpdatedAt);
      if (isSharedGroupsOnlyCloudPayload(remotePayload)) {
        await applyRemoteCloudPayload(remotePayload);
        await pullServerSharedBookmarkGroups(reason);
        setCloudMeta({
          localUpdatedAt: remoteUpdatedAt || localMeta.localUpdatedAt || new Date().toISOString(),
          lastCloudUpdatedAt: remoteUpdatedAt || null,
          lastRemoteUpdatedAt: remoteUpdatedAt || null,
          lastPullReason: reason
        });
        refreshUiAfterCloudApply();
        setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCED);
        broadcastGntdStateChange("SYNC_PULL_COMPLETED");
        if (isStartupPull) {
          cloudInitialSyncLoaded = true;
          cloudInitialSyncInProgress = false;
        }
        return;
      }
      const winner = decideCloudSyncWinner({
        localUpdatedAt,
        remoteUpdatedAt,
        remotePayload
      });

      debugLog("[CLOUD SYNC] sync decision", {
        localUpdatedAt: localUpdatedAt || null,
        remoteUpdatedAt: remoteUpdatedAt || null,
        lastCloudUpdatedAt: lastCloudUpdatedAt || null,
        winner,
        reason
      });

      setCloudMeta({ lastPulledAt: new Date().toISOString() });

      if (remoteUpdatedAt && compareIsoDates(remoteUpdatedAt, lastCloudUpdatedAt) <= 0) {
        debugLog("[CLOUD SYNC] remote state already processed", {
          remoteUpdatedAt,
          lastCloudUpdatedAt
        });
        if (isStartupPull && shouldApplyRemoteBackgroundOnStartup(remotePayload)) {
          await applyRemoteBackgroundStateOnly(remotePayload);
          broadcastGntdStateChange("BACKGROUND_CHANGED");
          broadcastGntdStateChange("SYNC_PULL_COMPLETED");
        }
        if (isStartupPull) {
          cloudInitialSyncLoaded = true;
          cloudInitialSyncInProgress = false;
          queueLocalBackgroundSyncIfRemoteMissing(remotePayload);
          debugLog("[CLOUD SYNC] initial sync completed (no restore needed)");
        }
        return;
      }

      if (winner === "remote") {
        debugLog("[CLOUD SYNC] applying remote state", {
          localUpdatedAt: localUpdatedAt || null,
          remoteUpdatedAt: remoteUpdatedAt || null,
          reason
        });
        await applyRemoteCloudPayload(remotePayload);
        await pullServerSharedBookmarkGroups(reason);
        debugLog("[CLOUD SYNC] remote state applied successfully");
        debugLog("[SYNC] remote data applied", {
          localKeys: Object.keys(remotePayload?.local_storage || {}),
          chromeKeys: Object.keys(remotePayload?.chrome_storage || {})
        });
        
        setCloudMeta({
          localUpdatedAt: remoteUpdatedAt || new Date().toISOString(),
          lastCloudUpdatedAt: remoteUpdatedAt || null,
          lastRemoteUpdatedAt: remoteUpdatedAt || null,
          lastPullReason: reason
        });
        refreshUiAfterCloudApply();
        setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCED);
        broadcastGntdStateChange("SYNC_PULL_COMPLETED");
        
        if (isStartupPull) {
          cloudInitialSyncLoaded = true;
          cloudInitialSyncInProgress = false;
          queueLocalBackgroundSyncIfRemoteMissing(remotePayload);
          debugLog("[CLOUD SYNC] initial sync completed (restore done)");
        }
        return;
      }

      if (winner === "local") {
        if (isStartupPull && shouldProtectRemoteBackgroundFromLocalPush(remotePayload)) {
          await applyRemoteBackgroundStateOnly(remotePayload);
          broadcastGntdStateChange("BACKGROUND_CHANGED");
          broadcastGntdStateChange("SYNC_PULL_COMPLETED");
        }

        const localPayload = await buildCloudSyncPayload();
        const localHasData = hasNonEmptySyncPayload(localPayload);
        const remoteHasData = hasSyncPayloadData(remotePayload);
        if (!localHasData && remoteHasData) {
          debugWarn("[CLOUD SYNC] local winner payload is empty while remote has data; blocking overwrite");
          setCloudSyncStatus(CLOUD_SYNC_STATUS_CONFLICT);
          cloudDirty = false;
          if (isStartupPull) {
            cloudInitialSyncLoaded = true;
            cloudInitialSyncInProgress = false;
          }
          return;
        }
        const protectedCollectionRisks = isStartupPull
          ? findProtectedEmptyCollectionOverwrites(localPayload, remotePayload)
          : [];
        if (protectedCollectionRisks.length) {
          debugWarn("[CLOUD SYNC] startup local winner would empty protected remote collections; restoring remote", {
            risks: protectedCollectionRisks
          });
          await applyRemoteCloudPayload(remotePayload);
          await pullServerSharedBookmarkGroups(reason);
          setCloudMeta({
            localUpdatedAt: remoteUpdatedAt || new Date().toISOString(),
            lastCloudUpdatedAt: remoteUpdatedAt || null,
            lastRemoteUpdatedAt: remoteUpdatedAt || null,
            lastPullReason: reason
          });
          refreshUiAfterCloudApply();
          setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCED);
          broadcastGntdStateChange("SYNC_PULL_COMPLETED");
          cloudDirty = false;
          cloudInitialSyncLoaded = true;
          cloudInitialSyncInProgress = false;
          queueLocalBackgroundSyncIfRemoteMissing(remotePayload);
          return;
        }

        debugLog("[CLOUD SYNC] local state wins, scheduling push", {
          localUpdatedAt: localUpdatedAt || null,
          remoteUpdatedAt: remoteUpdatedAt || null,
          reason
        });
        cloudDirty = true;
        
        if (isStartupPull) {
          // Even though we'll push, mark startup as complete so future saves can proceed
          cloudInitialSyncLoaded = true;
          cloudInitialSyncInProgress = false;
          debugLog("[CLOUD SYNC] initial sync completed (local is newer, will push)");
        }
        
        await syncPushLatestState();
        return;
      }

      debugLog("[CLOUD SYNC] sync timestamps are equal, keeping current local state", {
        localUpdatedAt: localUpdatedAt || null,
        remoteUpdatedAt: remoteUpdatedAt || null,
        reason
      });
      if (isStartupPull && shouldApplyRemoteBackgroundOnStartup(remotePayload)) {
        await applyRemoteBackgroundStateOnly(remotePayload);
        broadcastGntdStateChange("BACKGROUND_CHANGED");
        broadcastGntdStateChange("SYNC_PULL_COMPLETED");
      }
      setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCED);
      if (isStartupPull) {
        cloudInitialSyncLoaded = true;
        cloudInitialSyncInProgress = false;
        queueLocalBackgroundSyncIfRemoteMissing(remotePayload);
      }
    } catch (err) {
      if (err?.status === 429) {
        cloudPullBlockedUntil = Date.now() + CLOUD_RATE_LIMIT_BACKOFF_MS;
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
      } else {
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
      }
      debugWarn("[CLOUD SYNC] ❌ Cloud pull failed:", err?.message || err);
      cloudInitialSyncInProgress = false;
    } finally {
      cloudPullBusy = false;
    }
  }

  async function syncPullOnStartup() {
    return syncPullIfNeeded("startup", true);
  }

  function stopCloudSyncRuntime() {
    if (cloudPullTimer) {
      window.clearInterval(cloudPullTimer);
      cloudPullTimer = 0;
    }
    cloudSyncRuntimeStarted = false;
  }

  function startCloudSyncRuntime() {
    if (!canUseCloudSync()) return;
    if (cloudSyncRuntimeStarted) return;
    cloudSyncRuntimeStarted = true;
    setCloudSyncStatus(CLOUD_SYNC_STATUS_SYNCING);

    cloudPullTimer = window.setInterval(() => {
      if (document.visibilityState === "visible") {
        syncPullIfNeeded("timer", false);
      }
    }, CLOUD_PULL_INTERVAL_MS);

    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "visible") {
        syncPullIfNeeded("visibility", false);
      }
    });
  }

  async function initApp() {
    // Parallelize token fetching since they don't depend on each other
    let [token, startupRefreshToken] = await Promise.all([
      getToken(),
      getCloudAuthRefreshToken()
    ]);
    logAuthPresence("Startup auth restore", token, startupRefreshToken);

    if (!token && startupRefreshToken) {
      debugLog("[AUTH] Access token missing on startup, trying silent refresh");
      try {
        token = await refreshAuthToken();
        debugLog("[AUTH] Silent refresh on startup succeeded");
      } catch (err) {
        if (err?.isDefinitiveSessionExpiry) {
          await expireSession(err?.sessionExpiryReason || "startup-refresh-definitive-failure");
          return;
        }
        debugWarn("[AUTH] Silent refresh on startup failed temporarily, preserving tokens", {
          message: err?.message || "",
          status: err?.status || 0,
          reason: err?.sessionExpiryReason || ""
        });
      }
    }

    if (!token) {
      debugLog("[CLOUD SYNC] ℹ️  No auth token found, cloud sync disabled");
      resetPremiumState("init:no-token");
      setCloudSyncStatus(CLOUD_SYNC_STATUS_LOGIN_REQUIRED);
      cloudInitialSyncLoaded = true; // Mark as loaded even without auth
      cloudStartupPullTriggered = false;
    }
    updateAuthButtonState(!!token);
    if (token) {
      debugLog("[CLOUD SYNC] 🔐 Authenticated user detected");
      await refreshPremiumAccess("init", { token });
      if (!CLOUD_SYNC_ENABLED) {
        debugLog("[CLOUD SYNC] cloud sync disabled on client");
        setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
        cloudInitialSyncLoaded = true;
        return;
      }

      const effectiveState = getEffectivePremiumState();
      const syncGate = evaluateCloudSyncStartupGate({ token, state: effectiveState, reason: "init" });
      debugLog("[SYNC] startup sync decision", {
        reason: syncGate.reason,
        ready: syncGate.ready,
        allowed: syncGate.allowed,
        tokenPresent: !!token,
        premiumStateLoaded: !!effectiveState?.loaded
      });
      debugLog("[CLOUD SYNC gate]", buildCloudSyncGateDebug({
        state: effectiveState,
        tokenPresent: !!token,
        reason: syncGate.reason
      }));

      if (!syncGate.ready) {
        debugLog("[CLOUD SYNC] waiting for premium status...");
        if (!cloudPremiumReadyRetryScheduled) {
          cloudPremiumReadyRetryScheduled = true;
          window.setTimeout(async () => {
            cloudPremiumReadyRetryScheduled = false;
            const retryGate = await refreshPremiumStateBeforeSync();
            if (retryGate.allowed) {
              await startCloudSyncInitialPull("premium-ready-retry");
            } else {
              debugLog("[CLOUD SYNC] blocked after premium refresh", retryGate);
            }
          }, 700);
        }
        return;
      }

      if (syncGate.allowed) {
        await startCloudSyncInitialPull("init");
      } else {
        debugLog("[CLOUD SYNC DEBUG]", buildCloudSyncGateDebug({
          state: effectiveState,
          tokenPresent: !!token,
          reason: syncGate.reason
        }));
        debugLog("[CLOUD SYNC] blocked after premium refresh", syncGate);
        cloudInitialSyncLoaded = true; // Mark as loaded even if sync not available
        if (!isCloudSyncUserEnabled()) {
          setCloudSyncStatus(CLOUD_SYNC_STATUS_PAUSED);
        } else if (syncGate.reason === "premium-required") {
          setCloudSyncStatus(CLOUD_SYNC_STATUS_PREMIUM_REQUIRED);
        } else {
          setCloudSyncStatus(CLOUD_SYNC_STATUS_LOGIN_REQUIRED);
        }
      }
    }

    if (!window.__cloudPremiumStateSyncHook) {
      window.__cloudPremiumStateSyncHook = true;
      window.addEventListener("premium:state-changed", async () => {
        const token = await getCloudAuthToken();
        if (!token || cloudStartupPullTriggered) return;
        const state = getEffectivePremiumState();
        const gate = evaluateCloudSyncStartupGate({ token, state, reason: "premium-state-change" });
        if (!gate.ready) {
          debugLog("[CLOUD SYNC] skipped: premium state not ready");
          return;
        }
        if (gate.allowed) {
          await startCloudSyncInitialPull("premium-state-change");
        }
      });
    }
  }

  function updateAuthButtonState(isLoggedIn) {
    const btn = document.getElementById("createAccountBtn");
    if (!btn) return;
    const effectiveState = getEffectivePremiumState();
    const premiumStatus = getPremiumStatus(effectiveState);
    const authUi = getAuthUiTexts();
    const pendingEmail = getPendingVerificationEmail();
    btn.classList.toggle("is-auth", !!isLoggedIn);
    btn.title = isLoggedIn
      ? (premiumStatus === PREMIUM_STATUS_LOADING
          ? authUi.cloudChecking
          : (hasPremium(effectiveState) ? authUi.cloudPremium : authUi.cloudConnected))
      : (pendingEmail ? authUi.emailNotVerified : authUi.cloudAccount);
    btn.setAttribute("aria-label", btn.title);
    window.dispatchEvent(new CustomEvent("auth:state-changed", { detail: { isLoggedIn: !!isLoggedIn } }));
  }

