  function applyCustomizeActionFallbacks() {
    const txt = getCustomizeActionFallbackTexts();
    const setText = (key, value) => {
      const el = document.querySelector(`[data-i18n="${key}"]`);
      if (el) el.textContent = value;
    };

    setText("customize.actionAddPhotos", txt.actionAddPhotos);
    setText("customize.actionAddFolder", txt.actionAddFolder);
    setText("customize.addFolder", txt.addFolder);
    setText("customize.actionWidgetTransparency", txt.actionWidgetTransparency);
    setText("customize.actionSidebarMode", txt.actionSidebarMode);
    setText("customize.actionTheme", txt.actionTheme);
    setText("customize.actionWeatherUnit", txt.actionWeatherUnit);
    setText("customize.actionClockFormat", txt.actionClockFormat);
    setText("customize.actionOpenMode", txt.actionOpenMode);
    setText("customize.actionWidgetSize", txt.actionWidgetSize);

    const folderInput = document.querySelector('[data-i18n="customize.folderNamePlaceholder"]');
    if (folderInput && (folderInput.tagName === "INPUT" || folderInput.tagName === "TEXTAREA")) {
      folderInput.placeholder = txt.folderNamePlaceholder;
    }
  }

