  function rowBelongsToActiveTodoProject(row) {
    if (activeTodoProjectId === TODO_PROJECT_ALL) return true;
    if (row.kind === "note") return getTodoProjectId(row.todo) === activeTodoProjectId;
    return getTodoProjectId(row.todo) === activeTodoProjectId;
  }

  function renderTodos() {
    if (!todoList) return;
    todoList.innerHTML = "";
    renderTodoProjects();

    const rows = [
      ...todos.map((todo, index) => ({ kind: "local", todo, index })),
      ...getNoteTodos().map((todo) => ({ kind: "note", todo }))
    ].filter(rowBelongsToActiveTodoProject);

    rows.forEach((row) => {
      const { todo } = row;
      const li = document.createElement("li");
      li.className = "todo-item" + (todo.done ? " done" : "") + (row.kind === "note" ? " todo-item--note" : "");

      const del = document.createElement("button");
      del.className = "todo-del";
      del.type = "button";
      del.textContent = "×";
      del.title = row.kind === "note" ? "Delete from note" : "Delete";

      const main = document.createElement("div");
      main.className = "todo-main";

      const cb = document.createElement("input");
      cb.type = "checkbox";
      cb.checked = !!todo.done;

      const text = document.createElement("span");
      text.className = "todo-text";
      text.textContent = todo.text;

      const dueDateLabel = document.createElement("span");
      dueDateLabel.className = "todo-date";
      dueDateLabel.textContent = formatTodoDate(todo.dueDate);
      dueDateLabel.hidden = !dueDateLabel.textContent;

      const projectLabel = document.createElement("span");
      projectLabel.className = "todo-project-tag";
      projectLabel.textContent = row.kind === "note"
        ? (normalizeTodoProjectName(todo.projectName) || "Notes")
        : getTodoProjectName(getTodoProjectId(todo));
      projectLabel.hidden = !projectLabel.textContent;

      main.append(cb, text, dueDateLabel, projectLabel);
        li.append(main, del);
      todoList.appendChild(li);

      cb.addEventListener("change", () => {
        if (row.kind === "note") {
          setNoteTodoDone(todo, cb.checked);
        } else {
          todo.done = cb.checked;
          saveTodos();
        }
        li.classList.toggle("done", cb.checked);
        renderTodos();
        updateDateTodoPreview();
      });

      del.addEventListener("click", () => {
        if (row.kind === "note") {
          deleteNoteTodo(todo);
          renderTodos();
          updateDateTodoPreview();
          return;
        }
        todos.splice(row.index, 1);
        saveTodos();
        renderTodos();
        updateDateTodoPreview();
      });

      if (row.kind === "note") {
        text.addEventListener("click", () => {
          window.dispatchEvent(new CustomEvent("notes:open", { detail: { id: todo.noteId } }));
        });
      }
    });
  }

