function normVideoClip(clip, duration = 0, maxLen = BG_VIDEO_MAX_CLIP_SECONDS) {
  if (!clip || typeof clip !== "object") return null;

  let start = Number(clip.start);
  let end = Number(clip.end);
  if (!Number.isFinite(start) || !Number.isFinite(end)) return null;

  if (duration > 0) {
    start = clamp(start, 0, duration);
    end = clamp(end, 0, duration);
  } else {
    start = Math.max(0, start);
    end = Math.max(0, end);
  }

  if (end < start) [start, end] = [end, start];

  const len = end - start;
  if (len < BG_VIDEO_MIN_CLIP_SECONDS) return null;

  if (Number.isFinite(maxLen) && maxLen > 0 && len > maxLen) {
    end = start + maxLen;
    if (duration > 0 && end > duration) {
      end = duration;
      start = Math.max(0, end - maxLen);
    }
  }

  return {
    start: Number(start.toFixed(3)),
    end: Number(end.toFixed(3))
  };
}

function applyBgVideoClipLoop(videoEl, clip) {
  if (!videoEl) return;

  try { videoEl.__bgClipCleanup?.(); } catch {}
  videoEl.__bgClipCleanup = null;

  const raw = normVideoClip(clip);
  if (!raw) {
    videoEl.loop = true;
    return;
  }

  videoEl.loop = false;
  const EPS = 0.05;

  const getClip = () => {
    const d = Number(videoEl.duration || 0);
    return normVideoClip(raw, d, BG_VIDEO_MAX_CLIP_SECONDS) || raw;
  };

  const enforceStart = () => {
    const c = getClip();
    if (!c) return;
    const t = Number(videoEl.currentTime || 0);
    if (t < c.start || t > c.end - EPS) {
      try { videoEl.currentTime = c.start; } catch {}
    }
  };

  const onTimeUpdate = () => {
    const c = getClip();
    if (!c) return;
    if (Number(videoEl.currentTime || 0) >= c.end - EPS) {
      try { videoEl.currentTime = c.start; } catch {}
      videoEl.play?.().catch(() => {});
    }
  };

  const onEnded = () => {
    const c = getClip();
    if (!c) return;
    try { videoEl.currentTime = c.start; } catch {}
    videoEl.play?.().catch(() => {});
  };

  const onSeeked = () => enforceStart();
  const onLoadedMetadata = () => enforceStart();

  videoEl.addEventListener("timeupdate", onTimeUpdate);
  videoEl.addEventListener("ended", onEnded);
  videoEl.addEventListener("seeked", onSeeked);
  videoEl.addEventListener("loadedmetadata", onLoadedMetadata);

  videoEl.__bgClipCleanup = () => {
    videoEl.removeEventListener("timeupdate", onTimeUpdate);
    videoEl.removeEventListener("ended", onEnded);
    videoEl.removeEventListener("seeked", onSeeked);
    videoEl.removeEventListener("loadedmetadata", onLoadedMetadata);
  };

  if (videoEl.readyState >= 1) enforceStart();
}

function ensureBgVideoEl() {
  let v = document.getElementById("bgVideo");
  if (v) return v;

  const layer = document.getElementById("bgLayer") || document.body;

  v = document.createElement("video");
  v.id = "bgVideo";
  v.loop = true;
  v.playsInline = true;
  v.autoplay = true;

  // важно: чтобы было как у картинки (cover)
  v.style.position = "absolute";
  v.style.inset = "0";
  v.style.width = "100%";
  v.style.height = "100%";
  v.style.objectFit = "cover";
  v.style.zIndex = "0";

  applyBgVideoSound(v, loadBgState()?.sound);

  layer.appendChild(v);
  return v;
}

function applyBgVideoSound(videoEl, soundOn) {
  if (!videoEl) return;
  const enabled = !!soundOn;
  videoEl.muted = !enabled;
  videoEl.volume = enabled ? 1 : 0;
}

function prepareBgVideoForPlayback(videoEl) {
  if (!videoEl) return;
  videoEl.preload = "auto";
  videoEl.playsInline = true;
  videoEl.autoplay = true;
  videoEl.setAttribute("playsinline", "");
  videoEl.setAttribute("webkit-playsinline", "");
  videoEl.setAttribute("disablepictureinpicture", "");
  videoEl.setAttribute("controlslist", "nodownload noplaybackrate noremoteplayback");
  try { videoEl.disablePictureInPicture = true; } catch {}
  try { videoEl.disableRemotePlayback = true; } catch {}
}

function syncBgVideoPlaybackForVisibility() {
  const videoEl = document.getElementById("bgVideo");
  if (!videoEl || videoEl.hidden || !videoEl.src) return;

  if (document.hidden) {
    try { videoEl.pause(); } catch {}
    return;
  }

  videoEl.play?.().catch(() => {});
}

if (!window.__bgVideoVisibilityListenerAdded) {
  document.addEventListener("visibilitychange", syncBgVideoPlaybackForVisibility);
  window.__bgVideoVisibilityListenerAdded = true;
}


function ensureBgImgEl() {
  let im = document.getElementById("bgImg");
  if (!im) {
    im = document.createElement("img");
    im.id = "bgImg";
    im.alt = "";
    // apply blur from saved state
    try { const b = loadBgState()?.blur || 0; bgImg.style.filter = b ? `blur(${b}px)` : ""; } catch(e){}
    document.body.prepend(im);
  }
  return im;
}


    // apply blur from saved state
    try { const b = loadBgState()?.blur || 0; bgVid.style.filter = b ? `blur(${b}px)` : ""; } catch(e){}
function cleanupBgMedia({ revoke = true } = {}) {
  document.body.classList.remove("bg-video");
  const v = document.getElementById("bgVideo");
  if (v) {
    try { v.pause(); } catch {}
    applyBgVideoClipLoop(v, null);
    v.hidden = true;
    v.style.transform = "";

    // мягкий сброс
    v.src = "";
    try { v.load(); } catch {}
  }

  const im = document.getElementById("bgImg");
  if (im) {
    im.hidden = true;
    im.style.transform = "";
    im.src = "";
  }

  if (revoke && _bgObjectUrl) {
    try { URL.revokeObjectURL(_bgObjectUrl); } catch {}
    _bgObjectUrl = null;
  }
}

async function setVideoBackgroundFromUrl(url) {
  cleanupBgMedia({ revoke: true });

  const v = ensureBgVideoEl();
  v.hidden = false;

  const im = document.getElementById("bgImg");
  if (im) im.hidden = true;

  // атрибуты ДО src/load/play
  v.loop = true;
  v.playsInline = true;
  applyBgVideoSound(v, loadBgState()?.sound);
  applyBgVideoClipLoop(v, loadBgState()?.clip);

  v.src = url;
  v.load();
  try { await v.play(); } catch (e) { console.warn("play blocked", e); }
}

async function setVideoBackgroundFromBlob(blob) {
  // сохраним старый URL чтобы ревокнуть после назначения нового
  const oldUrl = _bgObjectUrl;

  // сначала чистим, но НЕ ревокаем сейчас (чтобы не убить, если где-то гонка)
  cleanupBgMedia({ revoke: false });

  const v = ensureBgVideoEl();
  v.hidden = false;

  const im = document.getElementById("bgImg");
  if (im) im.hidden = true;

  v.loop = true;
  v.playsInline = true;
  applyBgVideoSound(v, loadBgState()?.sound);
  applyBgVideoClipLoop(v, loadBgState()?.clip);

  _bgObjectUrl = URL.createObjectURL(blob);
  v.src = _bgObjectUrl;
  v.load();
  try { await v.play(); } catch (e) { console.warn("play blocked", e); }

  // теперь можно безопасно ревокнуть старый
  if (oldUrl) {
    try { URL.revokeObjectURL(oldUrl); } catch {}
  }
}


/* ---------- ROT helpers ---------- */
function normRot(rot){
  let r = Number(rot) || 0;
  r = ((r % 360) + 360) % 360;
  // фиксируем в 0/90/180/270
  const snaps = [0, 90, 180, 270];
  let best = 0, bestD = 999;  
  for (const s of snaps){
    const d = Math.abs(s - r);
    if (d < bestD){ bestD = d; best = s; }
  }
  return best;
}





/* ---------- Focus + Apply to actual background ---------- */
function clamp(n, a, b){ return Math.max(a, Math.min(b, n)); }
function normFocus(f){
  const x = clamp(Number(f?.x ?? 50), 0, 100);
  const y = clamp(Number(f?.y ?? 50), 0, 100);
  return { x, y };
}
function coverScaleForRotation(w, h, rotDeg) {
  const r = ((rotDeg % 360) + 360) % 360;
  if (r === 90 || r === 270) {
    // чтобы после поворота 90° картинка закрывала прямоугольник экрана
    return Math.max(w / h, h / w);
  }
  return 1; // 0° или 180°
}

function applyBgFocus(focus, rot) {
  const f = normFocus(focus);
  const r = normRot(rot ?? 0);

  const pos = `${f.x}% ${f.y}%`;

  // ⚠️ Поставь сюда ID/элементы РЕАЛЬНОГО фона (не из модалки)
  const bgImg = document.getElementById("bgImg");
  const bgVid = document.getElementById("bgVideo");

  // контейнер, который задаёт размер "экрана" (на что фон натянут)
  const box =
    document.getElementById("bgLayer") ||
    document.getElementById("bg") ||
    document.body;

  const rect = box.getBoundingClientRect();
  const sc = coverScaleForRotation(rect.width, rect.height, r);
  const b = loadBgState()?.blur || 0;
  const brightness = clamp(Number(loadBgState()?.brightness ?? 100), 50, 150);
  const brightnessFactor = brightness / 100;
  const hasVisualFilter = !!b || brightness !== 100;
  const filterValue = hasVisualFilter
    ? `${b ? `blur(${b}px) ` : ""}${brightness !== 100 ? `brightness(${brightnessFactor})` : ""}`.trim()
    : "";
  const extraScale = 1 + Math.min(0.12, (b || 0) / 200);
  const finalScale = sc * extraScale;
  const hasTransform = r !== 0 || Math.abs(finalScale - 1) > 0.001;
  const transformValue = hasTransform ? `rotate(${r}deg) scale(${finalScale})` : "";
  const videoTransformValue = hasTransform ? `translateZ(0) ${transformValue}` : "translateZ(0)";

  if (bgImg) {
    bgImg.style.objectFit = "cover";
    bgImg.style.objectPosition = pos;
    bgImg.style.transformOrigin = "50% 50%";
    bgImg.style.transform = transformValue;
    try { bgImg.style.filter = filterValue; } catch(e){}
  }

  if (bgVid) {
    bgVid.style.objectFit = "cover";
    bgVid.style.objectPosition = pos;
    bgVid.style.transformOrigin = "50% 50%";
    bgVid.style.transform = videoTransformValue;
    try { bgVid.style.filter = filterValue; } catch(e){}
  }
}




/* ---------- State ---------- */
function saveBgState(state) {
  const prev = loadBgState() || {};
  const nextKind = state.kind || prev.kind || 'image';
  const hasExplicitBlur = Object.prototype.hasOwnProperty.call(state || {}, "blur");
  const hasExplicitBrightness = Object.prototype.hasOwnProperty.call(state || {}, "brightness");
  const rawValue = String(state.value ?? prev.value ?? "");
  const safeRawValue = (nextKind === "video" && rawValue.startsWith("blob:"))
    ? ("idb:" + BG_VIDEO_KEY)
    : rawValue;
  const isDataImage = rawValue.startsWith("data:image/");
  const shouldStoreInIdb = isDataImage && rawValue.length > 1_500_000;
  const finalValue = shouldStoreInIdb ? ("idb:" + BG_IMAGE_KEY) : safeRawValue;
  const clip = nextKind === "video"
    ? normVideoClip(state.clip ?? prev.clip ?? null)
    : null;
  const st = {
    kind: nextKind,
    value: finalValue,
    focus: normFocus(state.focus ?? prev.focus),
    rot: normRot(state.rot ?? prev.rot ?? 0),
    blur: clamp(Number(hasExplicitBlur ? state.blur : (nextKind === "image" ? 0 : (prev.blur ?? 0))), 0, 100),
    brightness: clamp(Number(hasExplicitBrightness ? state.brightness : (nextKind === "image" ? 100 : (prev.brightness ?? 100))), 50, 150),
    sound: (typeof state.sound === "boolean") ? state.sound : (typeof prev.sound === "boolean" ? prev.sound : false),
    clip
  };
  try {
    localStorage.setItem(BG_STATE_KEY, JSON.stringify(st));
  } catch (e) {
    if (isDataImage) {
      const stIdb = { ...st, value: "idb:" + BG_IMAGE_KEY };
      try { localStorage.setItem(BG_STATE_KEY, JSON.stringify(stIdb)); } catch (e2) {
        console.warn("saveBgState failed", e2);
      }
    } else {
      console.warn("saveBgState failed", e);
    }
  }

  if (isDataImage && (shouldStoreInIdb || st.value === ("idb:" + BG_IMAGE_KEY))) {
    idbPut(BG_IMAGE_KEY, rawValue).catch(() => {});
  }
  broadcastGntdStateChange("BACKGROUND_CHANGED");
}

function loadBgState() {
  try {
    const s = JSON.parse(localStorage.getItem(BG_STATE_KEY) || "null");
    if (s && (s.kind === "image" || s.kind === "video") && typeof s.value === "string") {
      s.focus = normFocus(s.focus);
      s.rot = normRot(s.rot ?? 0);
      s.blur = clamp(Number(s.blur ?? 0), 0, 100);
      s.brightness = clamp(Number(s.brightness ?? 100), 50, 150);
      s.sound = (typeof s.sound === "boolean") ? s.sound : false;
      s.clip = (s.kind === "video") ? normVideoClip(s.clip ?? null) : null;
      return s;
    }
  } catch {}

  const legacy = localStorage.getItem(BG_KEY_LEGACY);
  if (legacy && legacy.trim()) {
    const st = { kind: "image", value: legacy.trim(), focus: {x:50,y:50}, rot: 0 };
    saveBgState(st);
    return st;
  }
  return null;
}

function isSupportedRotationImageValue(rawValue) {
  const value = String(rawValue || "").trim();
  if (!value) return false;
  if (value.startsWith("blob:") || value.startsWith("idb:")) return false;
  if (/\.(mp4|webm|ogg)(\?|#|$)/i.test(value)) return false;
  if (value.startsWith("data:") && !value.startsWith("data:image/")) return false;
  if (/^http:\/\//i.test(value)) return false;
  return true;
}

function normalizeBgRotationItem(rawItem) {
  if (!rawItem || typeof rawItem !== "object") return null;
  const kind = String(rawItem.kind || "image").trim().toLowerCase();
  const value = String(rawItem.value || "").trim();
  if (kind !== "image") return null;
  if (!isSupportedRotationImageValue(value)) return null;
  return { kind: "image", value };
}

function loadBgRotationState() {
  try {
    const parsed = JSON.parse(localStorage.getItem(BG_ROTATION_KEY) || "null");
    const itemsRaw = Array.isArray(parsed?.items) ? parsed.items : [];
    const items = [];
    const seen = new Set();

    itemsRaw.forEach((item) => {
      const normalized = normalizeBgRotationItem(item);
      if (!normalized) return;
      if (seen.has(normalized.value)) return;
      seen.add(normalized.value);
      items.push(normalized);
    });

    const enabled = !!parsed?.enabled && items.length > 0;
    const lastValueRaw = String(parsed?.lastValue || "").trim();
    const lastValue = seen.has(lastValueRaw) ? lastValueRaw : "";

    return { enabled, items, lastValue };
  } catch {
    return { enabled: false, items: [], lastValue: "" };
  }
}

function saveBgRotationState(state) {
  const sourceItems = Array.isArray(state?.items) ? state.items : [];
  const items = [];
  const seen = new Set();

  sourceItems.forEach((item) => {
    const normalized = normalizeBgRotationItem(item);
    if (!normalized) return;
    if (seen.has(normalized.value)) return;
    seen.add(normalized.value);
    items.push(normalized);
  });

  const lastValueRaw = String(state?.lastValue || "").trim();
  const payload = {
    enabled: !!state?.enabled && items.length > 0,
    items,
    lastValue: seen.has(lastValueRaw) ? lastValueRaw : ""
  };

  localStorage.setItem(BG_ROTATION_KEY, JSON.stringify(payload));
  broadcastGntdStateChange("BACKGROUND_CHANGED");
  return payload;
}

function pickWallpaperForNewTabRotation() {
  if (!hasFeature(PREMIUM_FEATURE_WALLPAPER_ROTATION)) return null;

  const state = loadBgRotationState();
  if (!state.enabled || !state.items.length) return null;

  let pool = state.items;
  if (state.lastValue && state.items.length > 1) {
    const filtered = state.items.filter((item) => item.value !== state.lastValue);
    if (filtered.length) pool = filtered;
  }

  const idx = Math.floor(Math.random() * pool.length);
  const chosen = pool[idx] || state.items[0];
  if (!chosen?.value) return null;

  saveBgRotationState({ ...state, lastValue: chosen.value });
  return chosen.value;
}

/* ---------- Set background ---------- */
function waitForBackgroundImageReady(img, timeoutMs = 1400) {
  if (!img) return Promise.resolve();
  if (img.complete && img.naturalWidth > 0) return Promise.resolve();

  const decodePromise = typeof img.decode === "function"
    ? img.decode().catch(() => {})
    : new Promise((resolve) => {
        const done = () => {
          img.removeEventListener("load", done);
          img.removeEventListener("error", done);
          resolve();
        };
        img.addEventListener("load", done, { once: true });
        img.addEventListener("error", done, { once: true });
      });

  return Promise.race([
    decodePromise,
    new Promise((resolve) => window.setTimeout(resolve, timeoutMs))
  ]);
}

async function setImageBackground(url) {
  cleanupBgMedia();
  document.body.classList.remove("bg-video");
  const im = ensureBgImgEl();
  im.hidden = false;
  im.loading = "eager";
  im.decoding = "async";
  try { im.fetchPriority = "high"; } catch {}
  im.src = url;

  const v = document.getElementById("bgVideo");
  if (v) v.hidden = true;

  await waitForBackgroundImageReady(im);
}

async function setImageBackgroundFromBlob(blob) {
  cleanupBgMedia();
  document.body.classList.remove("bg-video");
  const im = ensureBgImgEl();
  im.hidden = false;
  im.loading = "eager";
  im.decoding = "async";
  try { im.fetchPriority = "high"; } catch {}

  _bgObjectUrl = URL.createObjectURL(blob);
  im.src = _bgObjectUrl;

  const v = document.getElementById("bgVideo");
  if (v) v.hidden = true;

  await waitForBackgroundImageReady(im);
}

async function setVideoBackgroundFromUrl(url) {
  cleanupBgMedia();
  document.body.classList.add("bg-video");
  const v = ensureBgVideoEl();
  v.hidden = false;

  const im = document.getElementById("bgImg");
  if (im) im.hidden = true;

  v.src = url;
  v.load();
  v.loop = true;
  prepareBgVideoForPlayback(v);
  applyBgVideoSound(v, loadBgState()?.sound);
  applyBgVideoClipLoop(v, loadBgState()?.clip);

  const canPlay = await new Promise((resolve) => {
    let done = false;
    const finish = (ok) => {
      if (done) return;
      done = true;
      try { v.removeEventListener("canplay", onCanPlay); } catch {}
      try { v.removeEventListener("loadeddata", onCanPlay); } catch {}
      try { v.removeEventListener("error", onError); } catch {}
      try { clearTimeout(timer); } catch {}
      resolve(ok);
    };
    const onCanPlay = () => finish(true);
    const onError = () => finish(false);
    const timer = setTimeout(() => finish(v.readyState >= 2), 6000);
    v.addEventListener("canplay", onCanPlay, { once: true });
    v.addEventListener("loadeddata", onCanPlay, { once: true });
    v.addEventListener("error", onError, { once: true });
  });

  if (!canPlay) {
    throw new Error("Video background could not be loaded");
  }

  syncBgVideoPlaybackForVisibility();
}

async function setVideoBackgroundFromBlob(blob) {
  cleanupBgMedia();
  document.body.classList.add("bg-video");
  const v = ensureBgVideoEl();
  v.hidden = false;

  const im = document.getElementById("bgImg");
  if (im) im.hidden = true;

  _bgObjectUrl = URL.createObjectURL(blob);
  v.src = _bgObjectUrl;
   v.load();     
  v.loop = true;
  prepareBgVideoForPlayback(v);
  applyBgVideoSound(v, loadBgState()?.sound);
  applyBgVideoClipLoop(v, loadBgState()?.clip);

  const canPlay = await new Promise((resolve) => {
    let done = false;
    const finish = (ok) => {
      if (done) return;
      done = true;
      try { v.removeEventListener("canplay", onCanPlay); } catch {}
      try { v.removeEventListener("loadeddata", onCanPlay); } catch {}
      try { v.removeEventListener("error", onError); } catch {}
      try { clearTimeout(timer); } catch {}
      resolve(ok);
    };
    const onCanPlay = () => finish(true);
    const onError = () => finish(false);
    const timer = setTimeout(() => finish(v.readyState >= 2), 6000);
    v.addEventListener("canplay", onCanPlay, { once: true });
    v.addEventListener("loadeddata", onCanPlay, { once: true });
    v.addEventListener("error", onError, { once: true });
  });

  if (!canPlay) {
    throw new Error("Video background blob could not be loaded");
  }

  syncBgVideoPlaybackForVisibility();
}

// Open (or create) IndexedDB used for background video storage
async function idbOpen() {
  return new Promise((resolve, reject) => {
    try {
      const req = indexedDB.open(BG_DB_NAME, BG_DB_VERSION);
      req.onupgradeneeded = () => {
        const db = req.result;
        if (!db.objectStoreNames.contains(BG_DB_STORE)) db.createObjectStore(BG_DB_STORE);
      };
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => reject(req.error || new Error('IDB open error'));
    } catch (e) {
      reject(e);
    }
  });
}


async function idbPut(key, value) {
  const db = await idbOpen();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(BG_DB_STORE, "readwrite");
    tx.objectStore(BG_DB_STORE).put(value, key);
    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onerror = () => { db.close(); reject(tx.error); };
  });
}
async function idbGet(key) {
  const db = await idbOpen();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(BG_DB_STORE, "readonly");
    const req = tx.objectStore(BG_DB_STORE).get(key);
    req.onsuccess = () => { db.close(); resolve(req.result || null); };
    req.onerror = () => { db.close(); reject(req.error); };
  });
}

async function idbDel(key) {
  // 1) ключ должен быть валидным
  if (key === undefined || key === null || key === "") {
    console.warn("[idbDel] skip: invalid key =", key);
    return;
  }

  const db = await idbOpen();

  return new Promise((resolve, reject) => {
    let tx;

    try {
      // 2) транзакция по нужному store
      tx = db.transaction(BG_DB_STORE, "readwrite");
      tx.objectStore(BG_DB_STORE).delete(key);
    } catch (e) {
      db.close();
      reject(e);
      return;
    }

    tx.oncomplete = () => { db.close(); resolve(); };
    tx.onabort = () => { const err = tx.error; db.close(); reject(err); };
    tx.onerror  = () => { const err = tx.error; db.close(); reject(err); };
  });
}

/* ---------- Apply on start ---------- */
async function applySavedOrDefaultBackground() {
  const showDefaultBackground = async () => {
    const def = assetUrl("assets/default-bg.jpg");
    await setImageBackground(def);
    applyBgFocus({x:50,y:50}, 0);
  };
  const saveAndShowDefaultBackground = async () => {
    const def = assetUrl("assets/default-bg.jpg");
    saveBgState({ kind: "image", value: def, focus:{x:50,y:50}, rot:0, blur: 0, brightness: 100, sound: false, clip: null });
    await showDefaultBackground();
  };

  let st = null;
  try {
    st = loadBgState();
  } catch {
    st = null;
  }

  const rotationValue = pickWallpaperForNewTabRotation();
  if (rotationValue) {
    const base = st || {};
    st = {
      kind: "image",
      value: rotationValue,
      focus: normFocus(base.focus),
      rot: normRot(base.rot ?? 0),
      blur: 0,
      brightness: 100,
      sound: false,
      clip: null
    };
    saveBgState(st);
  }

  if (!st) {
    saveAndShowDefaultBackground();
    return;
  }

  if (st.kind === "image") {
    if (st.value === "idb:" + BG_IMAGE_KEY) {
      const storedImage = await idbGet(BG_IMAGE_KEY).catch(() => null);
      if (storedImage instanceof Blob) {
        await setImageBackgroundFromBlob(storedImage);
        applyBgFocus(st.focus, st.rot);
        return;
      }
      if (storedImage) {
        await setImageBackground(storedImage);
        applyBgFocus(st.focus, st.rot);
        return;
      }
      await showDefaultBackground();
      return;
    }

    if (!st.value || String(st.value).startsWith("blob:")) {
      await showDefaultBackground();
      return;
    }

    await setImageBackground(st.value);
    applyBgFocus(st.focus, st.rot);
    return;
  }

  // video
  try {
    if (st.value === "idb:" + BG_VIDEO_KEY) {
      const blob = await idbGet(BG_VIDEO_KEY).catch(() => null);
      if (blob) {
        await setVideoBackgroundFromBlob(blob);
        applyBgFocus(st.focus, st.rot);
        return;
      }
      await showDefaultBackground();
      return;
    }

    const value = String(st.value || "").trim();
    if (!value || value.startsWith("blob:")) {
      await showDefaultBackground();
      return;
    }

    await setVideoBackgroundFromUrl(value);
    applyBgFocus(st.focus, st.rot);
    return;
  } catch {
    await showDefaultBackground();
    return;
  }
}

/* ---------- Reset helper ---------- */
async function resetBackgroundToDefault() {
  cleanupBgMedia();
  await idbDel(BG_VIDEO_KEY).catch(() => {});
  await idbDel(BG_IMAGE_KEY).catch(() => {});
  const def = assetUrl("assets/default-bg.jpg");
  saveBgState({ kind: "image", value: def, focus:{x:50,y:50}, rot:0, blur: 0, brightness: 100, sound: false, clip: null });
  setImageBackground(def);
  applyBgFocus({x:50,y:50}, 0);
}
document.addEventListener("DOMContentLoaded", async () => {
  const card  = document.getElementById("onboardingCard");
  const close = document.getElementById("onboardingClose");
  const link  = document.getElementById("onboardingLink");
  const titleEl = document.getElementById("onboardingTitle");
  const hintEl = document.getElementById("onboardingHint");

  if (!card || !close) return;

  // ТУТ твой туториал (YouTube / страница / любая ссылка)
  const TUTORIAL_URL = "https://www.youtube.com/watch?v=YOUR_VIDEO_ID";
  if (link) link.href = TUTORIAL_URL;

  const KEY = "onboardingDismissed.v1";
  const lang = String(localStorage.getItem("app.language") || "en").trim();
  const onboardingMap = {
    en: { title: "Watch a video to get started", hint: "Click to open the tutorial", close: "Close" },
    ru: { title: "Посмотрите видео, чтобы начать", hint: "Нажмите, чтобы открыть обучение", close: "Закрыть" },
    uk: { title: "Перегляньте відео, щоб почати", hint: "Натисніть, щоб відкрити навчання", close: "Закрити" },
    de: { title: "Schau dir ein Video an, um zu starten", hint: "Klicken, um das Tutorial zu öffnen", close: "Schließen" },
    tr: { title: "Başlamak için bir video izleyin", hint: "Eğitimi açmak için tıklayın", close: "Kapat" },
    az: { title: "Başlamaq üçün videoya baxın", hint: "Təlimatı açmaq üçün klikləyin", close: "Bağla" },
    kk: { title: "Бастау үшін бейнені қараңыз", hint: "Нұсқаулықты ашу үшін басыңыз", close: "Жабу" },
    uz: { title: "Boshlash uchun videoni ko'ring", hint: "Qo'llanmani ochish uchun bosing", close: "Yopish" },
    es: { title: "Mira un video para empezar", hint: "Haz clic para abrir el tutorial", close: "Cerrar" },
    fr: { title: "Regardez une vidéo pour commencer", hint: "Cliquez pour ouvrir le tutoriel", close: "Fermer" },
    pt: { title: "Assista a um vídeo para começar", hint: "Clique para abrir o tutorial", close: "Fechar" },
    zh_CN: { title: "观看视频快速开始", hint: "点击打开教程", close: "关闭" },
    zh_TW: { title: "觀看影片快速開始", hint: "點擊開啟教學", close: "關閉" }
  };
  const onboardingText = onboardingMap[lang] || onboardingMap.en;

  if (titleEl) titleEl.textContent = onboardingText.title;
  if (hintEl) hintEl.textContent = onboardingText.hint;
  close.setAttribute("aria-label", onboardingText.close);

  const hasChromeStorage = !!chrome?.storage?.local;

  function getFlag() {
    return new Promise((resolve) => {
      if (!hasChromeStorage) return resolve(localStorage.getItem(KEY) === "1");
      chrome.storage.local.get([KEY], (res) => resolve(!!res?.[KEY]));
    });
  }

  function setFlag() {
    if (!hasChromeStorage) {
      localStorage.setItem(KEY, "1");
      return Promise.resolve();
    }
    return new Promise((resolve) => {
      chrome.storage.local.set({ [KEY]: true }, resolve);
    });
  }

  // показать только если не закрывали раньше
  const dismissed = await getFlag();
  if (!dismissed) card.hidden = false;

  close.addEventListener("click", async () => {
    card.hidden = true;
    await setFlag();
  });
});

/* ======================
   SEARCH (NEW WIDGET)
====================== */
const searchForm = document.getElementById("searchForm");
const searchInput = document.getElementById("searchInput");
const searchSuggestList = document.getElementById("searchSuggestList");
const SEARCH_HISTORY_KEY = "search.history.v1";
const SEARCH_HISTORY_LIMIT = 80;
const SEARCH_SUGGEST_LIMIT = 8;
const SEARCH_BOOKMARK_LIMIT = 250;
let searchBookmarkSuggestions = [];

function loadSearchHistory() {
  try {
    const raw = localStorage.getItem(SEARCH_HISTORY_KEY);
    const parsed = JSON.parse(raw || "[]");
    if (!Array.isArray(parsed)) return [];
    return parsed
      .filter((item) => typeof item === "string")
      .map((item) => item.trim())
      .filter((item, idx, arr) => item && arr.indexOf(item) === idx)
      .slice(0, SEARCH_HISTORY_LIMIT);
  } catch {
    return [];
  }
}

function saveSearchHistory(items) {
  try {
    localStorage.setItem(
      SEARCH_HISTORY_KEY,
      JSON.stringify((Array.isArray(items) ? items : []).slice(0, SEARCH_HISTORY_LIMIT))
    );
  } catch {
    // Ignore storage errors to keep search working.
  }
}

function rememberSearchQuery(query) {
  const normalized = String(query || "").trim();
  if (!normalized) return;

  const history = loadSearchHistory();
  const deduped = [normalized, ...history.filter((item) => item.toLowerCase() !== normalized.toLowerCase())];
  saveSearchHistory(deduped);
}

function normalizeBookmarkSuggestions(rawBookmarks) {
  if (!Array.isArray(rawBookmarks)) return [];

  const seen = new Set();
  const normalized = [];

  for (const item of rawBookmarks) {
    if (!item || typeof item !== "object") continue;
    const url = String(item.url || "").trim();
    if (!/^https?:\/\//i.test(url)) continue;
    const key = url.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);

    const title = String(item.title || "").trim();
    normalized.push({
      title,
      url,
      matchText: `${title} ${url}`.toLowerCase().trim()
    });

    if (normalized.length >= SEARCH_BOOKMARK_LIMIT) break;
  }

  return normalized;
}

function refreshBookmarkSuggestions() {
  if (!chrome?.storage?.local?.get) return;
  chrome.storage.local.get(["bookmarks"], (res) => {
    if (chrome.runtime?.lastError) return;
    searchBookmarkSuggestions = normalizeBookmarkSuggestions(res?.bookmarks);
    updateSearchSuggestions(searchInput?.value || "");
  });
}

function updateSearchSuggestions(inputValue) {
  if (!searchSuggestList) return;

  const q = String(inputValue || "").trim().toLowerCase();
  const history = loadSearchHistory();

  const rows = [];
  for (const item of history) {
    const low = item.toLowerCase();
    if (!q || low.includes(q)) {
      rows.push({
        value: item,
        label: "",
        starts: q ? low.startsWith(q) : false,
        source: 0
      });
    }
  }

  for (const bm of searchBookmarkSuggestions) {
    if (!q || bm.matchText.includes(q)) {
      rows.push({
        value: bm.url,
        label: bm.title,
        starts: q ? bm.matchText.startsWith(q) : false,
        source: 1
      });
    }
  }

  rows.sort((a, b) => {
    if (a.starts !== b.starts) return a.starts ? -1 : 1;
    if (a.source !== b.source) return a.source - b.source;
    return 0;
  });

  const ranked = [];
  const seenValues = new Set();
  for (const row of rows) {
    const key = String(row.value || "").toLowerCase();
    if (!key || seenValues.has(key)) continue;
    seenValues.add(key);
    ranked.push(row);
    if (ranked.length >= SEARCH_SUGGEST_LIMIT) break;
  }

  searchSuggestList.textContent = "";
  for (const item of ranked) {
    const option = document.createElement("option");
    option.value = item.value;
    if (item.label) option.label = item.label;
    searchSuggestList.appendChild(option);
  }
}

function doSearch(query) {
  const q = (query || "").trim();
  if (!q) return;

  // твой текущий путь (как раньше)
  if (chrome?.runtime?.sendMessage) {
    chrome.runtime.sendMessage({ type: "SEARCH", query: q }, () => void chrome.runtime.lastError);
    return;
  }

  // fallback
  window.location.href = "https://www.google.com/search?q=" + encodeURIComponent(q);
}

if (searchForm && searchInput) {
  refreshBookmarkSuggestions();

  if (chrome?.storage?.onChanged?.addListener && !window.__searchBookmarkStorageListenerAdded) {
    chrome.storage.onChanged.addListener((changes, areaName) => {
      if (areaName !== "local") return;
      if (!changes || !Object.prototype.hasOwnProperty.call(changes, "bookmarks")) return;
      refreshBookmarkSuggestions();
    });
    window.__searchBookmarkStorageListenerAdded = true;
  }

  updateSearchSuggestions("");

  searchInput.addEventListener("focus", () => {
    updateSearchSuggestions(searchInput.value);
  });

  searchInput.addEventListener("input", () => {
    updateSearchSuggestions(searchInput.value);
  });

  searchForm.addEventListener("submit", (e) => {
    e.preventDefault();
    rememberSearchQuery(searchInput.value);
    doSearch(searchInput.value);
  });

  // ESC очищает поле
  searchInput.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      searchInput.value = "";
      searchInput.blur();
    }
  });
}





/**
 * Модалка фокуса/поворота.
 * Возвращает focus {x,y,rot} или null (cancel)
 *
 * Требуются элементы:
 * #bgFocus, #bgFocusBackdrop, #bgFocusClose, #bgFocusCancel, #bgFocusApply,
 * #bgFocusCenter, #bgFocusPreview, #bgFocusImg, #bgFocusVid
 *
 * Дополнительно (ОЧЕНЬ желательно) кнопки поворота:
 * #bgRotateLeft  (↺) и #bgRotateRight (↻)
 * Если их нет — поворот просто останется каким был.
 */
function openBgFocusEditor({
  kind,
  src,
  initialFocus,
  initialRot = null,
  initialBlur = null,
  initialBrightness = null,
  initialClip = null,
  maxClipDuration = BG_VIDEO_MAX_CLIP_SECONDS
}) {
  const st0 = loadBgState();
  // Explicitly check for null/undefined to allow 0 as a valid value
  let rot = normRot(initialRot !== null && initialRot !== undefined ? initialRot : (st0?.rot ?? 0));

  // текущий src для картинки (после “запекания” поворота)
  let currentSrc = src;

  // helpers
  const isDataUrl = (s) => typeof s === "string" && s.startsWith("data:");
  const isGifDataUrl = (s) => typeof s === "string" && s.startsWith("data:image/gif");

  // Повернуть пиксели на 90° (CW / CCW) и вернуть новый dataURL
  const rotateDataUrl90 = (dataUrl, dir /* +1 CW, -1 CCW */) => {
    return new Promise((resolve, reject) => {
      const im = new Image();
      im.onload = () => {
        try {
          const w = im.naturalWidth || im.width;
          const h = im.naturalHeight || im.height;

          const c = document.createElement("canvas");
          c.width = h;
          c.height = w;
          const ctx = c.getContext("2d");
          if (!ctx) return reject(new Error("no canvas ctx"));
          try {
            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = "high";
          } catch {}

          // центр
          ctx.translate(c.width / 2, c.height / 2);
          ctx.rotate((dir * Math.PI) / 2);

          // рисуем по центру
          ctx.drawImage(im, -w / 2, -h / 2);

          // Keep lossy formats at near-max quality when rotation is baked into pixels.
          const m = String(/^data:(image\/[a-zA-Z0-9.+-]+);/i.exec(dataUrl)?.[1] || "image/png").toLowerCase();

          let out;
          if (m === "image/jpeg" || m === "image/jpg") {
            out = c.toDataURL("image/jpeg", 0.98);
          } else if (m === "image/webp") {
            out = c.toDataURL("image/webp", 0.98);
          } else {
            out = c.toDataURL(m);
          }

          resolve(out);
        } catch (e) {
          reject(e);
        }
      };
      im.onerror = () => reject(new Error("image load failed"));
      im.src = dataUrl;
    });
  };

  // Попытаться повернуть URL-изображение через fetch -> dataURL -> canvas
  const rotateUrl90 = async (url, dir /* +1 CW, -1 CCW */) => {
    const res = await fetch(url);
    if (!res.ok) throw new Error("fetch failed");
    const blob = await res.blob();
    const dataUrl = await new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = () => resolve(String(r.result || ""));
      r.onerror = reject;
      r.readAsDataURL(blob);
    });
    if (!dataUrl) throw new Error("dataUrl failed");
    return rotateDataUrl90(dataUrl, dir);
  };

  // Пересчитать focus при повороте пикселей (чтобы центр “смотрел” туда же)
  const remapFocusAfterBake = (f, dir /* +1 CW, -1 CCW */) => {
    const x = clamp(f.x, 0, 100);
    const y = clamp(f.y, 0, 100);

    // объект-позиция: x% y%
    // CW: (x,y) -> (y, 100-x)
    // CCW: (x,y) -> (100-y, x)
    if (dir === 1) return { x: y, y: 100 - x };
    return { x: 100 - y, y: x };
  };

  return new Promise((resolve) => {
    const wrap = document.getElementById("bgFocus");
    const backdrop = document.getElementById("bgFocusBackdrop");
    const btnClose = document.getElementById("bgFocusClose");
    const btnCancel = document.getElementById("bgFocusCancel");
    const btnApply = document.getElementById("bgFocusApply");
    const btnCenter = document.getElementById("bgFocusCenter");

    const btnRotL = document.getElementById("bgRotateLeft");
    const btnRotR = document.getElementById("bgRotateRight");

    const preview = document.getElementById("bgFocusPreview");
    const img = document.getElementById("bgFocusImg");
    const vid = document.getElementById("bgFocusVid");
    const blurToggle = document.getElementById('bgFocusBlurToggle');
    const blurWrap = document.getElementById('bgFocusBlurWrap');
    const blurLabel = document.getElementById('bgFocusBlurLabel');
    const blurInput = document.getElementById('bgFocusBlurInput');
    const blurValueEl = document.getElementById('bgFocusBlurValue');
    const soundToggle = document.getElementById("bgFocusSoundToggle");
    const brightnessWrap = document.getElementById("bgFocusBrightnessWrap");
    const brightnessLabel = document.getElementById("bgFocusBrightnessLabel");
    const brightnessInput = document.getElementById("bgFocusBrightness");
    const brightnessValue = document.getElementById("bgFocusBrightnessValue");
    const clipWrap = document.getElementById("bgFocusClip");
    const clipLabel = document.getElementById("bgFocusClipLabel");
    const clipRange = document.getElementById("bgFocusClipRange");
    const clipTrack = document.getElementById("bgFocusClipTrack");
    const clipThumbs = document.getElementById("bgFocusClipThumbs");
    const clipHandleStart = document.getElementById("bgFocusClipHandleStart");
    const clipHandleEnd = document.getElementById("bgFocusClipHandleEnd");
    const clipStartLabel = document.getElementById("bgFocusClipStartLabel");
    const clipEndLabel = document.getElementById("bgFocusClipEndLabel");
    const clipStart = document.getElementById("bgFocusClipStart");
    const clipEnd = document.getElementById("bgFocusClipEnd");
    const clipStartValue = document.getElementById("bgFocusClipStartValue");
    const clipEndValue = document.getElementById("bgFocusClipEndValue");
    const clipTickStart = document.getElementById("bgFocusClipTickStart");
    const clipTickMid = document.getElementById("bgFocusClipTickMid");
    const clipTickEnd = document.getElementById("bgFocusClipTickEnd");

    // если модалки нет — вернем как есть
    if (!wrap || !preview || !img || !vid) {
      resolve({
        focus: normFocus(initialFocus),
        rot: normRot(loadBgState()?.rot ?? 0),
        src,
        clip: null,
        brightness: clamp(Number(loadBgState()?.brightness ?? 100), 50, 150)
      });
      return;
    }

    let focus = normFocus(initialFocus);
    let blur = clamp(Number(initialBlur !== null && initialBlur !== undefined ? initialBlur : (loadBgState()?.blur ?? 0)), 0, 100);
    let brightness = clamp(Number(initialBrightness !== null && initialBrightness !== undefined ? initialBrightness : (loadBgState()?.brightness ?? 100)), 50, 150);
    let soundOn = !!loadBgState()?.sound;
    let clip = normVideoClip(initialClip);
    let videoDuration = 0;
    const clipMax = Number(maxClipDuration) > 0 ? Number(maxClipDuration) : BG_VIDEO_MAX_CLIP_SECONDS;
    let onVidMeta = null;

const sync = () => {
  const pos = `${focus.x}% ${focus.y}%`;
  img.style.objectFit = "cover";
  img.style.objectPosition = pos;
  vid.style.objectFit = "cover";
  vid.style.objectPosition = pos;

  const r = preview.getBoundingClientRect();
  const rotDeg = normRot(rot);
  const sc = coverScaleForRotation(r.width, r.height, rotDeg);
  const extraScale = 1 + Math.min(0.12, (blur || 0) / 200);
  const fitScale = sc * extraScale;
  const hasVisualFilter = !!blur || brightness !== 100;
  const filterValue = hasVisualFilter
    ? `${blur ? `blur(${blur}px) ` : ""}${brightness !== 100 ? `brightness(${(brightness / 100).toFixed(2)})` : ""}`.trim()
    : "";
  const hasTransform = rotDeg !== 0 || Math.abs(fitScale - 1) > 0.001;
  const transformValue = hasTransform ? `rotate(${rotDeg}deg) scale(${fitScale})` : "";

  if (kind === "video") {
    vid.style.transformOrigin = "50% 50%";
    vid.style.transform = transformValue;
    img.style.transform = "";
    try { vid.style.filter = filterValue; } catch(e){}
  } else {
    img.style.transformOrigin = "50% 50%";
    img.style.transform = transformValue;
    vid.style.transform = "";
    try { img.style.filter = filterValue; } catch(e){}
  }
};

    const updateBrightnessUi = () => {
      if (brightnessLabel) brightnessLabel.textContent = t("background.brightness", getBrightnessLabel());
      if (brightnessInput) brightnessInput.value = String(brightness);
      if (brightnessValue) brightnessValue.textContent = `${Math.round(brightness)}%`;
    };

    const onBrightnessInput = () => {
      if (!brightnessInput) return;
      brightness = clamp(Number(brightnessInput.value || 100), 50, 150);
      updateBrightnessUi();
      sync();
    };

    const updateClipLabels = () => {
      if (!clipStartValue || !clipEndValue || !clipRange) return;
      if (!clip) {
        clipStartValue.textContent = "0:00";
        clipEndValue.textContent = videoDuration > 0 ? formatTimeShort(videoDuration) : formatTimeShort(clipMax);
        clipRange.textContent = `${clipStartValue.textContent} – ${clipEndValue.textContent}`;
        return;
      }
      clipStartValue.textContent = formatTimeShort(clip.start);
      clipEndValue.textContent = formatTimeShort(clip.end);
      clipRange.textContent = `${clipStartValue.textContent} – ${clipEndValue.textContent}`;
    };

    const updateClipVisuals = () => {
      if (!clipTrack || !clipStart || !clipEnd) return;

      const max = Math.max(1, Number(clipStart.max || clipMax || 1));
      const start = Number(clipStart.value || 0);
      const end = Number(clipEnd.value || 0);

      const startPct = clamp((start / max) * 100, 0, 100);
      const endPct = clamp((end / max) * 100, 0, 100);

      clipTrack.style.setProperty("--clip-start", `${startPct}%`);
      clipTrack.style.setProperty("--clip-end", `${endPct}%`);

      if (clipHandleStart) clipHandleStart.style.left = `${startPct}%`;
      if (clipHandleEnd) clipHandleEnd.style.left = `${endPct}%`;
    };

    const updateClipTicks = () => {
      const max = Math.max(0, videoDuration || clipMax || 0);
      if (clipTickStart) clipTickStart.textContent = `0с.`;
      if (clipTickMid) clipTickMid.textContent = `${Math.round(max / 2)}с.`;
      if (clipTickEnd) clipTickEnd.textContent = `${Math.round(max)}с.`;
    };

    const updateClipThumbs = () => {
      if (!clipThumbs) return;
      clipThumbs.style.backgroundImage = "none";

      if (kind !== "video" || !src) return;

      const makeThumb = () => {
        try {
          const canvas = document.createElement("canvas");
          canvas.width = 240;
          canvas.height = 96;
          const ctx = canvas.getContext("2d");
          if (!ctx) return;
          ctx.drawImage(vid, 0, 0, canvas.width, canvas.height);
          // Preview-only thumbnail for clip UI; final background continues using original video source.
          const thumb = canvas.toDataURL("image/jpeg", 0.75);
          clipThumbs.style.backgroundImage = `url(${thumb})`;
        } catch {
          clipThumbs.style.backgroundImage = "none";
        }
      };

      if (vid.readyState >= 2) makeThumb();
      else {
        const onCanPlay = () => {
          vid.removeEventListener("canplay", onCanPlay);
          makeThumb();
        };
        vid.addEventListener("canplay", onCanPlay);
      }
    };

    const renderClipUi = () => {
      if (!clipWrap || kind !== "video") return;

      const hasLongVideo = videoDuration > clipMax + 0.05;
      clipWrap.hidden = !hasLongVideo;

      if (clipLabel) clipLabel.textContent = t("background.videoFragment", getClipActionLabel());
      if (clipStartLabel) clipStartLabel.textContent = t("background.videoStart", "Start");
      if (clipEndLabel) clipEndLabel.textContent = t("background.videoEnd", "End");

      if (!hasLongVideo || !clipStart || !clipEnd) {
        updateClipLabels();
        updateClipTicks();
        updateClipVisuals();
        return;
      }

      const max = Math.max(videoDuration, clipMax);
      clipStart.min = "0";
      clipStart.max = String(max);
      clipStart.step = "0.1";

      clipEnd.min = "0";
      clipEnd.max = String(max);
      clipEnd.step = "0.1";

      if (!clip) {
        clip = { start: 0, end: Math.min(videoDuration, clipMax) };
      }

      clip = normVideoClip(clip, videoDuration, clipMax) || { start: 0, end: Math.min(videoDuration, clipMax) };
      clipStart.value = String(clip.start);
      clipEnd.value = String(clip.end);

      updateClipLabels();
      updateClipTicks();
      updateClipVisuals();
      updateClipThumbs();
    };

    const onClipInput = (changed) => {
      if (kind !== "video" || !clipStart || !clipEnd || videoDuration <= 0) return;

      const hasLongVideo = videoDuration > clipMax + 0.05;
      if (!hasLongVideo) {
        clip = null;
        renderClipUi();
        applyBgVideoClipLoop(vid, clip);
        return;
      }

      let start = Number(clipStart.value || 0);
      let end = Number(clipEnd.value || 0);

      start = clamp(start, 0, videoDuration);
      end = clamp(end, 0, videoDuration);

      if (changed === "start") {
        if (end - start > clipMax) end = start + clipMax;
        if (end - start < BG_VIDEO_MIN_CLIP_SECONDS) end = start + BG_VIDEO_MIN_CLIP_SECONDS;
      } else {
        if (end - start > clipMax) start = end - clipMax;
        if (end - start < BG_VIDEO_MIN_CLIP_SECONDS) start = end - BG_VIDEO_MIN_CLIP_SECONDS;
      }

      start = clamp(start, 0, videoDuration);
      end = clamp(end, 0, videoDuration);

      if (end - start > clipMax) {
        if (changed === "start") end = clamp(start + clipMax, 0, videoDuration);
        else start = clamp(end - clipMax, 0, videoDuration);
      }

      clip = normVideoClip({ start, end }, videoDuration, clipMax);
      if (!clip) clip = { start: 0, end: Math.min(videoDuration, clipMax) };

      clipStart.value = String(clip.start);
      clipEnd.value = String(clip.end);
      updateClipLabels();
      updateClipVisuals();
      applyBgVideoClipLoop(vid, clip);
    };

    const onClipStartInput = () => onClipInput("start");
    const onClipEndInput = () => onClipInput("end");


    // rotation handlers
    const onRotL = async (e) => {
      e.stopPropagation();

      // ✅ Если это IMAGE и не GIF — запекаем поворот (dataURL или URL через fetch)
      if (kind === "image" && !isGifDataUrl(currentSrc)) {
        try {
          btnRotL && (btnRotL.disabled = true);
          btnRotR && (btnRotR.disabled = true);

          if (isDataUrl(currentSrc)) {
            currentSrc = await rotateDataUrl90(currentSrc, -1);
          } else {
            try {
              currentSrc = await rotateUrl90(currentSrc, -1);
            } catch (e) {
              // CORS blocked: fallback to CSS rotate
              focus = { x: 50, y: 50 };
              rot = normRot(rot - 90);
              sync();
              return;
            }
          }
          
          // Пересчитать focus до загрузки нового src
          focus = remapFocusAfterBake(focus, -1);
          rot = 0;
          
          // Дождаться загрузки нового src перед синхронизацией
          const onImgLoaded = () => {
            img.removeEventListener("load", onImgLoaded);
            sync();
          };
          img.addEventListener("load", onImgLoaded);
          img.src = currentSrc;
          
          // Если картинка уже кэширована, onload может не сработать
          if (img.complete) {
            setTimeout(onImgLoaded, 0);
          }
        } catch (err) {
          console.warn(err);
        } finally {
          btnRotL && (btnRotL.disabled = false);
          btnRotR && (btnRotR.disabled = false);
        }
        return;
      }

      // fallback (GIF или URL с CORS) — крутим как раньше
      // Сбросить фокус в центр перед ротацией, чтобы ротировать полную картинку, а не смещённый обрезок
      focus = { x: 50, y: 50 };
      rot = normRot(rot - 90);
      sync();
    };

    const onRotR = async (e) => {
      e.stopPropagation();

      if (kind === "image" && !isGifDataUrl(currentSrc)) {
        try {
          btnRotL && (btnRotL.disabled = true);
          btnRotR && (btnRotR.disabled = true);

          if (isDataUrl(currentSrc)) {
            currentSrc = await rotateDataUrl90(currentSrc, +1);
          } else {
            try {
              currentSrc = await rotateUrl90(currentSrc, +1);
            } catch (e) {
              // CORS blocked: fallback to CSS rotate
              // Сбросить фокус в центр перед ротацией, чтобы ротировать полную картинку, а не смещённый обрезок
              focus = { x: 50, y: 50 };
              rot = normRot(rot + 90);
              sync();
              return;
            }
          }
          
          // Пересчитать focus до загрузки нового src
          focus = remapFocusAfterBake(focus, +1);
          rot = 0;
          
          // Дождаться загрузки нового src перед синхронизацией
          const onImgLoaded = () => {
            img.removeEventListener("load", onImgLoaded);
            sync();
          };
          img.addEventListener("load", onImgLoaded);
          img.src = currentSrc;
          
          // Если картинка уже кэширована, onload может не сработать
          if (img.complete) {
            setTimeout(onImgLoaded, 0);
          }
        } catch (err) {
          console.warn(err);
        } finally {
          btnRotL && (btnRotL.disabled = false);
          btnRotR && (btnRotR.disabled = false);
        }
        return;
      }

      focus = { x: 50, y: 50 };
      rot = normRot(rot + 90);
      sync();
    };

    btnRotL?.addEventListener("click", onRotL);
    btnRotR?.addEventListener("click", onRotR);

    const cleanup = () => {
      preview.onpointerdown = null;
      document.onpointermove = null;
      document.onpointerup = null;

      btnRotL?.removeEventListener("click", onRotL);
      btnRotR?.removeEventListener("click", onRotR);
      if (blurToggle) {
        try { blurToggle.onclick = null; } catch(e){}
      }
      if (blurInput) {
        try { blurInput.removeEventListener("input", onBlurInput); } catch(e){}
      }
      if (soundToggle) {
        try { soundToggle.onclick = null; } catch(e){}
        soundToggle.hidden = true;
      }
      if (brightnessInput) {
        brightnessInput.removeEventListener("input", onBrightnessInput);
      }
      if (brightnessWrap) {
        brightnessWrap.hidden = false;
      }
      if (clipWrap) clipWrap.hidden = true;
      clipStart?.removeEventListener("input", onClipStartInput);
      clipEnd?.removeEventListener("input", onClipEndInput);
      if (onVidMeta) {
        vid.removeEventListener("loadedmetadata", onVidMeta);
        onVidMeta = null;
      }

      backdrop?.removeEventListener("click", onCancel);
      btnClose?.removeEventListener("click", onCancel);
      btnCancel?.removeEventListener("click", onCancel);
      btnApply?.removeEventListener("click", onApply);
      btnCenter?.removeEventListener("click", onCenter);

      wrap.hidden = true;
      img.hidden = true;
      vid.hidden = true;

      try { vid.pause(); } catch {}
      applyBgVideoClipLoop(vid, null);
      vid.removeAttribute("src");
      try { vid.load?.(); } catch {}
    };

    const onCancel = () => { cleanup(); resolve(null); };

    // ✅ возвращаем currentSrc для image — чтобы ты сохранил именно повернутую картинку
    const onApply = () => {
      const finalClip = kind === "video"
        ? normVideoClip(clip, videoDuration, clipMax)
        : null;

      cleanup();
      resolve({
        focus,
        rot: normRot(rot),
        src: (kind === "image" ? currentSrc : src),
        blur,
        brightness,
        sound: soundOn,
        clip: finalClip
      });
    };

    const onCenter = () => { focus = { x: 50, y: 50 }; sync(); };

    // show correct media
    if (kind === "video") {
      img.hidden = true;
      vid.hidden = false;
      vid.src = src;
      vid.loop = true;
      vid.playsInline = true;
      applyBgVideoSound(vid, soundOn);
      applyBgVideoClipLoop(vid, clip);

      onVidMeta = () => {
        videoDuration = Number(vid.duration || 0);
        if (videoDuration > clipMax + 0.05) {
          clip = normVideoClip(clip, videoDuration, clipMax)
            || { start: 0, end: Math.min(videoDuration, clipMax) };
        } else {
          clip = null;
        }
        renderClipUi();
        updateClipVisuals();
        applyBgVideoClipLoop(vid, clip);
      };

      vid.addEventListener("loadedmetadata", onVidMeta);
      if (vid.readyState >= 1) onVidMeta();

      clipStart?.addEventListener("input", onClipStartInput);
      clipEnd?.addEventListener("input", onClipEndInput);

      vid.play?.().catch(()=>{});
    } else {
      vid.hidden = true;
      img.hidden = false;
      // Ensure no inherited transforms before loading
      img.style.transform = "";
      img.style.filter = "";
      img.style.objectPosition = "50% 50%";
      // Load image and sync after loaded
      const onImgLoad = () => {
        img.removeEventListener("load", onImgLoad);
        sync();
      };
      img.addEventListener("load", onImgLoad);
      img.src = currentSrc;
      // If already cached, onload might not fire
      if (img.complete) {
        setTimeout(() => onImgLoad(), 0);
      }
      if (clipWrap) clipWrap.hidden = true;
    }

    // For video, sync immediately
    if (kind === "video") {
      sync();
    }
    updateBrightnessUi();
    brightnessInput?.addEventListener("input", onBrightnessInput);

    const layoutPanel = document.getElementById("layoutPanel");
    if (layoutPanel) {
      layoutPanel.setAttribute("data-open", "0");
      document.body.classList.remove("drawer-open");
    }

    wrap.hidden = false;

    // init blur toggle + slider
    const FIXED_BLUR = 12;
    const getBlurPremiumLabel = () => t("background.blur", "Blur");
    let blurSliderUnlocked = false;
    if (blurWrap) {
      blurWrap.hidden = true;
      blurWrap.style.display = "none";
    }
    const updateBlurUi = () => {
      const blurText = t("background.blur", "Blur");
      const showBlurSlider = blurSliderUnlocked && !!blur;
      if (blurToggle) {
        blurToggle.textContent = blur ? `${blurText}: ${blur}px` : `${blurText}: Off`;
        blurToggle.classList.toggle('active', !!blur);
      }
      if (blurWrap) {
        blurWrap.hidden = !showBlurSlider;
        blurWrap.style.display = showBlurSlider ? "grid" : "none";
      }
      if (blurInput && blur) blurInput.value = String(blur);
      if (blurLabel) blurLabel.textContent = blurText;
      if (blurValueEl) blurValueEl.textContent = blur ? `${Math.round(blur)}px` : "0px";
    };
    const onBlurInput = () => {
      if (!blurInput) return;
      const effectiveState = getEffectivePremiumState();
      const premiumStatus = getPremiumStatus(effectiveState);
      if (premiumStatus === PREMIUM_STATUS_LOADING) {
        showMiniNotice(getPremiumCheckingText(), false);
        blurInput.value = String(clamp(Number(blur || FIXED_BLUR), 1, 40));
        updateBlurUi();
        updateBlurPremiumGate();
        return;
      }
      if (!hasPremium(effectiveState)) {
        showPremiumRequiredNotice(getBlurPremiumLabel());
        blurInput.value = String(clamp(Number(blur || FIXED_BLUR), 1, 40));
        updateBlurUi();
        updateBlurPremiumGate();
        return;
      }
      blur = clamp(Number(blurInput.value || 1), 1, 40);
      updateBlurUi();
      sync();
    };
    const updateBlurPremiumGate = () => {
      if (!blurInput) return;
      const effectiveState = getEffectivePremiumState();
      const premiumStatus = getPremiumStatus(effectiveState);
      const pending = premiumStatus === PREMIUM_STATUS_LOADING;
      const locked = !pending && !hasPremium(effectiveState);
      setPremiumGateState(blurInput, {
        locked,
        pending,
        badge: effectiveState?.uiOverride ? "DEV PRO" : "PRO",
        title: getPremiumOnlyMessage(getBlurPremiumLabel())
      });
    };
    if (blurToggle) {
      blurToggle.addEventListener('click', () => {
        blurSliderUnlocked = true;
        blur = blur ? 0 : (blurInput ? clamp(Number(blurInput.value || FIXED_BLUR), 1, 40) : FIXED_BLUR);
        updateBlurUi();
        sync();
      });
    }
    blurInput?.addEventListener("input", onBlurInput);
    updateBlurPremiumGate();
    updateBlurUi();

    try {
      if (soundToggle) {
        const updateSoundLabel = () => {
          soundToggle.textContent = soundOn
            ? t("background.videoSoundOn", "Sound: On")
            : t("background.videoSoundOff", "Sound: Off");
          soundToggle.setAttribute("aria-pressed", soundOn ? "true" : "false");
        };
        soundToggle.hidden = (kind !== "video");
        updateSoundLabel();
        soundToggle.onclick = () => {
          soundOn = !soundOn;
          applyBgVideoSound(vid, soundOn);
          updateSoundLabel();
        };
      }
    } catch(e){}

    // drag -> update focus (для image rot всегда 0, для video можно оставить как есть)
    let down = false;
    let lastX = 0, lastY = 0;

    preview.onpointerdown = (e) => {
      down = true;
      lastX = e.clientX;
      lastY = e.clientY;
      try { preview.setPointerCapture?.(e.pointerId); } catch {}
    };

    document.onpointermove = (e) => {
      if (!down) return;

      const r = preview.getBoundingClientRect();
      const dx = (e.clientX - lastX) / Math.max(1, r.width);
      const dy = (e.clientY - lastY) / Math.max(1, r.height);

      let ux = dx, uy = dy;

      // Учитываем поворот для обоих видео и изображений (в том числе CSS-ротация при fallback)
      const rotDeg = normRot(rot);
      if (rotDeg === 90)  { ux = dy;  uy = -dx; }
      if (rotDeg === 180) { ux = -dx; uy = -dy; }
      if (rotDeg === 270) { ux = -dy; uy = dx; }

      focus.x = clamp(focus.x - ux * 100, 0, 100);
      focus.y = clamp(focus.y - uy * 100, 0, 100);

      lastX = e.clientX;
      lastY = e.clientY;
      sync();
    };

    document.onpointerup = () => { down = false; };

    backdrop?.addEventListener("click", onCancel);
    btnClose?.addEventListener("click", onCancel);
    btnCancel?.addEventListener("click", onCancel);
    btnApply?.addEventListener("click", onApply);
    btnCenter?.addEventListener("click", onCenter);
  });
};


/* ---------- Duration check (для upload) ---------- */
function getVideoDurationSeconds(fileOrBlob) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(fileOrBlob);
    const v = document.createElement("video");
    v.preload = "metadata";
    v.onloadedmetadata = () => {
      const d = Number(v.duration || 0);
      URL.revokeObjectURL(url);
      resolve(d);
    };
    v.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("Cannot read video metadata"));
    };
    v.src = url;
  });
}




