  function lsGetJSON(key, fallback) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : fallback;
    } catch {
      return fallback;
    }
  }
  function lsSetJSON(key, val) {
    localStorage.setItem(key, JSON.stringify(val));
  }

  function storeGet(keys) {
    return new Promise((resolve) => {
      if (HAS_STORAGE) {
        chrome.storage.local.get(keys, (res) => resolve(res || {}));
      } else {
        const out = {};
        for (const k of keys) out[k] = lsGetJSON(k, null);
        resolve(out);
      }
    });
  }
async function setFavorite(slotIdx, bm) {
  const maxSlot = favorites.length - 1; // 5
  const slot = Math.max(0, Math.min(maxSlot, Number(slotIdx)));

  if (!bm) {
    favorites[slot] = null;
    await saveFavorites();
    renderFavoritesWidget();
    return;
  }

  favorites[slot] = {
    title: String(bm.title || "").trim() || canonUrl(bm.url),
    url: canonUrl(bm.url),
    icon: String(bm.icon || ""),
    comment: normalizeBookmarkComment(bm.comment || ""),
  };

  await saveFavorites();
  renderFavoritesWidget();
  renderBookmarks();
}

  function storeSet(obj) {
    return new Promise((resolve) => {
      if (HAS_STORAGE) {
        chrome.storage.local.set(obj, () => resolve());
      } else {
        for (const [k, v] of Object.entries(obj)) lsSetJSON(k, v);
        resolve();
      }
    });
  }
async function saveFavSize() {
  await bmSet({ [FAV_SIZE_KEY]: favSize });
  broadcastGntdStateChange("BOOKMARKS_CHANGED");
}
function normalizeFavorites(v) {
  const arr = Array.isArray(v) ? v.slice(0, 9) : [];
  while (arr.length < 9) arr.push(null);

  return arr.map((x) => {
    if (!x || typeof x !== "object") return null;
    const title = String(x.title || "").trim();
    const url = canonUrl(x.url);
    const icon = String(x.icon || "");
    const comment = normalizeBookmarkComment(x.comment || "");
    if (!url) return null;
    return { title: title || url, url, icon, comment };
  });
}

