function getFolderWidgetTitle(groupName = "") {
  const locale = getLocale();
  const labels = {
    en: { base: "Folder", withGroup: "Folder: {group}" },
    ru: { base: "Папка", withGroup: "Папка: {group}" },
    uk: { base: "Папка", withGroup: "Папка: {group}" },
    de: { base: "Ordner", withGroup: "Ordner: {group}" },
    tr: { base: "Klasör", withGroup: "Klasör: {group}" },
    az: { base: "Qovluq", withGroup: "Qovluq: {group}" },
    kk: { base: "Қалта", withGroup: "Қалта: {group}" },
    uz: { base: "Papka", withGroup: "Papka: {group}" },
    es: { base: "Carpeta", withGroup: "Carpeta: {group}" },
    fr: { base: "Dossier", withGroup: "Dossier : {group}" },
    pt: { base: "Pasta", withGroup: "Pasta: {group}" },
    zh_CN: { base: "文件夹", withGroup: "文件夹：{group}" },
    zh_TW: { base: "資料夾", withGroup: "資料夾：{group}" }
  };

  const txt = labels[locale] || labels.en;
  const safeName = String(groupName || "").trim();
  return safeName ? txt.withGroup.replace("{group}", safeName) : txt.base;
}

function setFolderWidgetMeta(widgetEl, groupName) {
  if (!widgetEl) return;
  const safeName = String(groupName || "").trim();
  widgetEl.dataset.group = safeName;
  widgetEl.dataset.title = getFolderWidgetTitle(safeName);
  const titleEl = widgetEl.querySelector(".folder-widget-title") || widgetEl.querySelector("h2");
  if (titleEl) titleEl.textContent = getFolderWidgetTitle(safeName);
}

function openBookmarksPanelForGroup(groupName = "") {
  document.getElementById("workspace")?.classList.add("show-bookmarks");
  const safeName = String(groupName || "").trim();
  if (!safeName || !groups[safeName] || !bmGroupSelect) return;
  renderGroupSelect();
  bmGroupSelect.value = safeName;
  bmActiveGroup = safeName;
  lastGroup = safeName;
  void saveBookmarkGroupState({ [BM_KEYS.lastGroup]: lastGroup }, BM_KEYS.lastGroup);
}

function renderFolderWidget(widgetEl, data = {}) {
  const perf = startPerf("render.folderWidget");
  if (!widgetEl) return;

  const groupName = String(data?.group || widgetEl.dataset.group || "").trim();
  const slotsEl = widgetEl.querySelector(".folder-slots") || widgetEl.querySelector(".fav-slots");
  if (!slotsEl) return;

  setFolderWidgetMeta(widgetEl, groupName);
  slotsEl.innerHTML = "";

  const groupBookmarks = groupName
    ? bookmarks.filter((bm) => bm.group === groupName).slice(0, getFavSlotCount())
    : [];

  for (let i = 0; i < getFavSlotCount(); i++) {
    const bm = groupBookmarks[i];
    const row = document.createElement("div");
    row.className = "fav-slot" + (bm ? "" : " fav-empty");

    if (bm) {
      const href = normalizeUrl(bm.url)?.href || bm.url;

      const img = document.createElement("img");
      img.className = "fav-ico";
      img.alt = String(bm.title || "");
      img.title = String(bm.title || "");
      img.loading = "lazy";
      img.decoding = "async";
      img.referrerPolicy = "no-referrer";
      img.src = resolveBookmarkIcon(bm);

      const clearBtn = document.createElement("button");
      clearBtn.className = "fav-clear";
      clearBtn.type = "button";
      clearBtn.title = "Remove bookmark";
      clearBtn.textContent = "✕";

      row.append(img, clearBtn);
      row.addEventListener("click", (e) => {
        if (e.target.closest("button")) return;
        openUrl(href);
      });
      row.addEventListener("mousedown", (e) => {
        if (e.button !== 1) return;
        if (e.target.closest("button")) return;
        e.preventDefault();
        openUrl(href, { newTab: true });
      });
      clearBtn.addEventListener("click", async (e) => {
        e.stopPropagation();
        const slot = slotOfUrl(href);
        if (slot !== -1) await setFavorite(slot, null);
        bookmarks = bookmarks.filter((item) => item !== bm);
        saveBookmarks();
        renderBookmarks();
      });
    } else {
      const num = document.createElement("div");
      num.className = "fav-num";
      num.textContent = "+";

      const addBtn = document.createElement("button");
      addBtn.className = "fav-add";
      addBtn.type = "button";
      addBtn.title = groupName ? `Add bookmark to ${groupName}` : "Open bookmarks";
      addBtn.textContent = "+";

      row.append(num, addBtn);
      addBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        openBookmarksPanelForGroup(groupName);
      });
    }

    slotsEl.appendChild(row);
  }

  endPerf(perf, {
    group: groupName || "",
    renderedSlots: getFavSlotCount(),
    bookmarksInGroup: groupBookmarks.length
  });
}

function refreshFolderWidgets() {
  document.querySelectorAll('[data-widget="folder"]').forEach((widgetEl) => {
    renderFolderWidget(widgetEl, { group: widgetEl.dataset.group || "" });
  });
}

async function createFolderWidget({ mountEl, instanceId, initialData }) {
  if (!mountEl || !folderWidgetTpl?.content) return null;

  const node = folderWidgetTpl.content.firstElementChild.cloneNode(true);
  node.id = instanceId;
  node.dataset.instance = instanceId;
  node.classList.add("widget", "folder-widget");

  setFolderWidgetMeta(node, initialData?.group || "");
  renderFolderWidget(node, initialData);

  mountEl.appendChild(node);
  return node;
}

async function addFolderWidget({ mountEl, groupName }) {
  const safeGroupName = String(groupName || "").trim();
  if (!mountEl || !safeGroupName) return null;

  const instanceId = uid("folder");
  const idx = await loadFolderWidgetsIndex();
  idx.push(instanceId);
  await saveFolderWidgetsIndex(idx);
  await saveFolderWidgetData(instanceId, { group: safeGroupName });

  return createFolderWidget({ mountEl, instanceId, initialData: { group: safeGroupName } });
}

async function restoreFolderWidgets({ mountEl }) {
  if (!mountEl) return;

  document.querySelectorAll('.widget.folder-widget[data-instance]').forEach((widget) => widget.remove());

  const idx = await loadFolderWidgetsIndex();
  for (const instanceId of idx) {
    if (!instanceId || document.getElementById(instanceId)) continue;
    const data = await loadFolderWidgetData(instanceId);
    await createFolderWidget({ mountEl, instanceId, initialData: data });
  }
}

async function renameFolderWidgetsGroup(oldName, nextName) {
  const from = String(oldName || "").trim();
  const to = String(nextName || "").trim();
  if (!from || !to || from === to) return;

  const idx = await loadFolderWidgetsIndex();
  for (const instanceId of idx) {
    const data = await loadFolderWidgetData(instanceId);
    if (data.group !== from) continue;
    data.group = to;
    await saveFolderWidgetData(instanceId, data);
    const node = document.getElementById(instanceId);
    if (node) setFolderWidgetMeta(node, to);
  }

  refreshFolderWidgets();
}

async function removeFolderWidgetsByGroup(groupName) {
  const targetGroup = String(groupName || "").trim();
  if (!targetGroup) return;

  const idx = await loadFolderWidgetsIndex();
  const kept = [];
  const keysToRemove = [];

  for (const instanceId of idx) {
    const data = await loadFolderWidgetData(instanceId);
    if (data.group === targetGroup) {
      keysToRemove.push(FOLDER_WIDGET_DATA_KEY(instanceId));
      document.getElementById(instanceId)?.remove();
      widgetOrder = widgetOrder.filter((id) => id !== instanceId);
      hiddenWidgets.delete(instanceId);
      continue;
    }
    kept.push(instanceId);
  }

  await saveFolderWidgetsIndex(kept);
  if (keysToRemove.length) await bmRemove(keysToRemove);
  saveLayoutConfig();
  renderCustomizeList();
}

async function ensureBookmarkGroup(name, { skipBookmarkRender = false } = {}) {
  const perf = startPerf("flow.ensureBookmarkGroup");
  const groupName = String(name || "").trim();
  if (!groupName) {
    endPerf(perf, { created: false, emptyName: true });
    return "";
  }

  let created = false;

  if (!groups[groupName]) {
    groups[groupName] = { color: "#4f46e5", description: "" };
    groupOrder = placeNameAfter(getOrderedGroupNames(), groupName, "__end__");
    lastGroup = groupName;
    await saveBookmarkGroupState({
      [BM_KEYS.groups]: groups,
      [BM_KEYS.groupOrder]: groupOrder,
      [BM_KEYS.lastGroup]: lastGroup
    }, "bookmark-group-created");
    created = true;
  }

  renderGroupSelect();
  renderBookmarkGroupEditor(groupName);

  if (!skipBookmarkRender) {
    renderBookmarks();
  }

  endPerf(perf, { group: groupName, created, skipBookmarkRender });
  return groupName;
}

bmGet([BM_KEYS.bookmarks, BM_KEYS.groups, BM_KEYS.groupOrder, BM_KEYS.lastGroup, BM_KEYS.sharedGroups, FAV_KEY, FAV_SIZE_KEY]).then((data) => {

    bookmarks = Array.isArray(data[BM_KEYS.bookmarks]) ? data[BM_KEYS.bookmarks] : [];
    groups = (data[BM_KEYS.groups] && typeof data[BM_KEYS.groups] === "object") ? data[BM_KEYS.groups] : {};
    sharedGroups = normalizeSharedGroupState(data[BM_KEYS.sharedGroups]);
  groupOrder = normalizeGroupOrder(data[BM_KEYS.groupOrder]);
    lastGroup = typeof data[BM_KEYS.lastGroup] === "string" ? data[BM_KEYS.lastGroup] : "";
    if (pruneDeletedSharedGroupsFromLocalState()) {
      groupOrder = normalizeGroupOrder(groupOrder);
    }
    // ensure every bookmark has stable id (needed for drag&drop)
    let changed = false;
    for (const b of bookmarks) {
      if (!b.id) { b.id = genBmId(); changed = true; }
    }
    if (changed) bmSet({ [BM_KEYS.bookmarks]: bookmarks });

    favorites = normalizeFavorites(data[FAV_KEY]);
    renderFavoritesWidget();

    renderGroupSelect();
    scheduleBookmarksRender(120);
    renderBookmarkGroupEditor();
    handleSharedBookmarkGroupFromLocation();
    startSharedBookmarkGroupsRuntime();
    scheduleSharedBookmarkGroupPull("startup", 500);
favSize = normalizeFavSize(data[FAV_SIZE_KEY]);

applyFavSizeClass();
renderFavoritesWidget();

    if (chrome?.storage?.onChanged && !window.__bookmarkStorageListenerAdded) {
      chrome.storage.onChanged.addListener((changes, area) => {
        if (area !== "local") return;
        if (suppressLocalBookmarkStorageEvents > 0) return;

        if (changes[BM_KEYS.groups]) {
          groups = changes[BM_KEYS.groups].newValue || {};
          pruneDeletedSharedGroupsFromLocalState();
          groupOrder = normalizeGroupOrder(groupOrder);
          renderGroupSelect();
          renderNewGroupAfterSelect();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
          renderBookmarkGroupEditor();
        }
        if (changes[BM_KEYS.groupOrder]) {
          groupOrder = normalizeGroupOrder(changes[BM_KEYS.groupOrder].newValue);
          renderGroupSelect();
          renderNewGroupAfterSelect();
          renderBookmarkGroupTabs();
          renderBookmarkGroupEditor();
          scheduleBookmarksRender();
        }
        if (changes[BM_KEYS.bookmarks]) {
          bookmarks = changes[BM_KEYS.bookmarks].newValue || [];
          pruneDeletedSharedGroupsFromLocalState();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
          renderBookmarkGroupEditor();
        }
        if (changes[BM_KEYS.sharedGroups]) {
          sharedGroups = normalizeSharedGroupState(changes[BM_KEYS.sharedGroups].newValue);
          pruneDeletedSharedGroupsFromLocalState();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
        }
        if (changes[FAV_KEY]) {
          favorites = normalizeFavorites(changes[FAV_KEY].newValue);
          renderFavoritesWidget();
          scheduleBookmarksRender();
        }
        if (changes[FAV_SIZE_KEY]) {
          favSize = normalizeFavSize(changes[FAV_SIZE_KEY].newValue);
          applyFavSizeClass();
          renderFavoritesWidget();
        }
        if (changes[BM_KEYS.lastGroup]) {
          lastGroup = changes[BM_KEYS.lastGroup].newValue || "";
          if (bmGroupSelect && lastGroup && groups[lastGroup]) bmGroupSelect.value = lastGroup;
          if (lastGroup && groups[lastGroup]) bmActiveGroup = lastGroup;
          renderBookmarkGroupTabs();
          renderBookmarkGroupEditor(lastGroup);
        }
      });
      window.__bookmarkStorageListenerAdded = true;
    }

    if (!window.__bookmarkLocalStorageListenerAdded) {
      window.addEventListener("storage", (event) => {
        const key = String(event.key || "");
        if (!key || event.newValue == null) return;
        const value = parseLocalStorageBackupValue(event.newValue);

        if (key === BM_KEYS.groups) {
          groups = value && typeof value === "object" ? value : {};
          pruneDeletedSharedGroupsFromLocalState();
          groupOrder = normalizeGroupOrder(groupOrder);
          renderGroupSelect();
          renderNewGroupAfterSelect();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
          renderBookmarkGroupEditor();
        } else if (key === BM_KEYS.groupOrder) {
          groupOrder = normalizeGroupOrder(value);
          renderGroupSelect();
          renderNewGroupAfterSelect();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
          renderBookmarkGroupEditor();
        } else if (key === BM_KEYS.bookmarks) {
          bookmarks = Array.isArray(value) ? value : [];
          pruneDeletedSharedGroupsFromLocalState();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
          renderBookmarkGroupEditor();
        } else if (key === BM_KEYS.sharedGroups) {
          sharedGroups = normalizeSharedGroupState(value);
          pruneDeletedSharedGroupsFromLocalState();
          renderBookmarkGroupTabs();
          scheduleBookmarksRender();
        } else if (key === BM_KEYS.lastGroup) {
          lastGroup = typeof value === "string" ? value : "";
          if (bmGroupSelect && lastGroup && groups[lastGroup]) bmGroupSelect.value = lastGroup;
          if (lastGroup && groups[lastGroup]) bmActiveGroup = lastGroup;
          renderBookmarkGroupTabs();
          renderBookmarkGroupEditor(lastGroup);
        }
      });
      window.__bookmarkLocalStorageListenerAdded = true;
    }
  });
  // ===== Bookmark ID helper (needed for drag & drop / favorites) =====
  function genBmId(){
    try{
      if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
    }catch(e){}
    return "bm_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 10);
  }

  function saveBookmarks() {
    const payload = { [BM_KEYS.bookmarks]: bookmarks };
    if (syncAllSharedGroupBookmarkSnapshots()) {
      payload[BM_KEYS.sharedGroups] = sharedGroups;
    }
    bmSet(payload);
    broadcastGntdStateChange("BOOKMARKS_CHANGED");
  }

  function cloneBookmarkStorageValue(value) {
    if (typeof structuredClone === "function") {
      try { return structuredClone(value); } catch {}
    }
    try { return JSON.parse(JSON.stringify(value)); } catch {}
    return value;
  }

  function markBookmarkGroupStorageUpdated(reason = "bookmark-groups") {
    markCloudLocalUpdated(reason, { allowBeforeInitialSync: true });
  }

  async function saveBookmarkGroupState(values, reason = "bookmark-groups", options = {}) {
    const shouldMarkCloudDirty = options.markCloudDirty !== false;
    const suppressCloudEcho = !!options.suppressCloudEcho;
    if (shouldMarkCloudDirty) markBookmarkGroupStorageUpdated(reason);
    const payload = {};
    Object.entries(values || {}).forEach(([key, value]) => {
      payload[key] = cloneBookmarkStorageValue(value);
    });
    if (suppressCloudEcho) cloudStorageEchoSuppressions += 1;
    try {
      await bmSet(payload, { suppressLocalEcho: !!options.suppressLocalEcho });
    } finally {
      if (suppressCloudEcho) {
        cloudStorageEchoSuppressions = Math.max(0, cloudStorageEchoSuppressions - 1);
      }
    }
    if (options.broadcast !== false) broadcastGntdStateChange("BOOKMARKS_CHANGED");
  }

  function saveGroups() {
    return saveBookmarkGroupState({ [BM_KEYS.groups]: groups }, BM_KEYS.groups);
  }
  function saveGroupOrder() {
    return saveBookmarkGroupState({ [BM_KEYS.groupOrder]: groupOrder }, BM_KEYS.groupOrder);
  }

  function normalizeGroupOrder(rawOrder) {
    const existing = Object.keys(groups || {});
    const uniqueExisting = [];
    const seenExisting = new Set();
    existing.forEach((name) => {
      if (!seenExisting.has(name)) {
        seenExisting.add(name);
        uniqueExisting.push(name);
      }
    });

    const incoming = Array.isArray(rawOrder) ? rawOrder : [];
    const out = [];
    const seen = new Set();

    incoming.forEach((name) => {
      if (typeof name !== "string") return;
      if (!groups[name]) return;
      if (seen.has(name)) return;
      seen.add(name);
      out.push(name);
    });

    uniqueExisting.forEach((name) => {
      if (!seen.has(name)) {
        seen.add(name);
        out.push(name);
      }
    });

    return out;
  }

  function getOrderedGroupNames() {
    groupOrder = normalizeGroupOrder(groupOrder);
    return [...groupOrder];
  }

  function placeNameAfter(list, name, afterName) {
    const base = Array.isArray(list) ? list.filter((x) => x !== name) : [];
    const target = String(afterName || "__end__");

    if (target === "__start__") {
      base.unshift(name);
      return base;
    }

    if (target !== "__end__") {
      const idx = base.indexOf(target);
      if (idx >= 0) {
        base.splice(idx + 1, 0, name);
        return base;
      }
    }

    base.push(name);
    return base;
  }

