  function renderNewGroupAfterSelect() {
    if (!newGroupAfterSelect) return;

    const txt = getNewGroupPositionTexts();
    const names = getOrderedGroupNames();
    const prev = newGroupAfterSelect.value || "__end__";
    const shortName = (v) => {
      const raw = String(v || "").trim();
      return raw.length > 18 ? `${raw.slice(0, 18)}…` : raw;
    };

    newGroupAfterSelect.title = txt.label;
    newGroupAfterSelect.setAttribute("aria-label", txt.label);

    newGroupAfterSelect.innerHTML = "";

    const startOpt = document.createElement("option");
    startOpt.value = "__start__";
    startOpt.textContent = txt.start;
    newGroupAfterSelect.appendChild(startOpt);

    names.forEach((name) => {
      const opt = document.createElement("option");
      opt.value = name;
      opt.textContent = shortName(name);
      opt.title = `${txt.after}: ${name}`;
      newGroupAfterSelect.appendChild(opt);
    });

    const endOpt = document.createElement("option");
    endOpt.value = "__end__";
    endOpt.textContent = txt.end;
    newGroupAfterSelect.appendChild(endOpt);

    newGroupAfterSelect.value = Array.from(newGroupAfterSelect.options).some(o => o.value === prev)
      ? prev
      : "__end__";

    renderNewGroupAfterMenu();
    syncNewGroupAfterTrigger();
  }

  function syncNewGroupAfterTrigger() {
    if (!newGroupAfterTriggerText || !newGroupAfterSelect) return;
    const selected = newGroupAfterSelect.options[newGroupAfterSelect.selectedIndex];
    newGroupAfterTriggerText.textContent = selected?.textContent || t("bookmarks.atEnd", "At end");
  }

  function positionNewGroupAfterMenu() {
    if (!newGroupAfterMenu || !newGroupAfterTrigger) return;

    const rect = newGroupAfterTrigger.getBoundingClientRect();
    const viewportPad = 10;
    const width = Math.max(140, Math.round(rect.width));
    const left = Math.max(viewportPad, Math.min(Math.round(rect.left), window.innerWidth - width - viewportPad));

    const spaceBelow = Math.floor(window.innerHeight - rect.bottom - 16);
    const spaceAbove = Math.floor(rect.top - 16);
    const openUp = spaceBelow < 180 && spaceAbove > spaceBelow;

    newGroupAfterMenu.style.position = "fixed";
    newGroupAfterMenu.style.left = `${left}px`;
    newGroupAfterMenu.style.width = `${width}px`;
    newGroupAfterMenu.style.zIndex = "2147483647";

    if (openUp) {
      const maxHeight = Math.max(120, Math.min(260, spaceAbove));
      newGroupAfterMenu.style.maxHeight = `${maxHeight}px`;
      newGroupAfterMenu.style.top = `${Math.max(viewportPad, Math.round(rect.top - maxHeight - 8))}px`;
    } else {
      const maxHeight = Math.max(120, Math.min(260, spaceBelow));
      newGroupAfterMenu.style.maxHeight = `${maxHeight}px`;
      newGroupAfterMenu.style.top = `${Math.round(rect.bottom + 8)}px`;
    }
  }

  function closeNewGroupAfterMenu() {
    if (!newGroupAfterMenu || !newGroupAfterWrap || !newGroupAfterTrigger) return;
    newGroupAfterMenu.hidden = true;
    newGroupAfterWrap.classList.remove("is-open");
    newGroupAfterTrigger.setAttribute("aria-expanded", "false");

    newGroupAfterMenu.style.position = "";
    newGroupAfterMenu.style.left = "";
    newGroupAfterMenu.style.top = "";
    newGroupAfterMenu.style.width = "";
    newGroupAfterMenu.style.zIndex = "";

    if (newGroupAfterMenuHost && newGroupAfterMenu.parentElement !== newGroupAfterMenuHost) {
      newGroupAfterMenuHost.appendChild(newGroupAfterMenu);
    }
  }

  function openNewGroupAfterMenu() {
    if (!newGroupAfterMenu || !newGroupAfterWrap || !newGroupAfterTrigger) return;

    if (newGroupAfterMenu.parentElement !== document.body) {
      document.body.appendChild(newGroupAfterMenu);
    }

    newGroupAfterMenu.hidden = false;
    newGroupAfterWrap.classList.add("is-open");
    newGroupAfterTrigger.setAttribute("aria-expanded", "true");
    positionNewGroupAfterMenu();
  }

  function renderNewGroupAfterMenu() {
    if (!newGroupAfterMenu || !newGroupAfterSelect) return;
    newGroupAfterMenu.innerHTML = "";

    const options = Array.from(newGroupAfterSelect.options || []);
    if (!options.length) {
      closeNewGroupAfterMenu();
      return;
    }

    options.forEach((opt) => {
      const item = document.createElement("button");
      item.type = "button";
      item.className = "bm-group-menu-item";
      item.textContent = opt.textContent || "";
      item.setAttribute("role", "option");
      if (opt.disabled) item.disabled = true;
      if (opt.value === newGroupAfterSelect.value) item.classList.add("is-active");

      item.addEventListener("click", () => {
        if (opt.disabled) return;
        newGroupAfterSelect.value = opt.value;
        newGroupAfterSelect.dispatchEvent(new Event("change", { bubbles: true }));
        closeNewGroupAfterMenu();
      });

      newGroupAfterMenu.appendChild(item);
    });

    if (!newGroupAfterMenu.hidden) positionNewGroupAfterMenu();
  }

  function normalizeUrl(url) {
    if (!url) return null;

    try {
      if (!/^https?:\/\//i.test(url)) {
        url = "https://" + url;
      }
      return new URL(url);
    } catch {
      return null;
    }
  }

