  function isCustomizeModeActive() {
    return document.body.classList.contains("layout-editing");
  }

  function renderBookmarkGroupEditor(preferredGroup = "") {
    if (!bmEditGroupSelect || !bmEditGroupName || !bmEditGroupDescription || !bmEditGroupColor || !bmEditGroupSave) return;

    const txt = getGroupEditorTexts();
    if (bmEditGroupHead) bmEditGroupHead.textContent = txt.head;
    if (bmEditGroupSelectLabel) bmEditGroupSelectLabel.textContent = txt.selectLabel;
    if (bmEditGroupNameLabel) bmEditGroupNameLabel.textContent = txt.nameLabel;
    if (bmEditGroupDescriptionLabel) bmEditGroupDescriptionLabel.textContent = t("bookmarks.description", "Description");
    if (bmEditGroupColorLabel) bmEditGroupColorLabel.textContent = txt.colorLabel;
    bmEditGroupSave.textContent = txt.save;
    bmEditGroupName.placeholder = t("bookmarks.newGroupName", "New group name");
    bmEditGroupDescription.placeholder = t("bookmarks.description", "Description");

    const names = getOrderedGroupNames();
    bmEditGroupSelect.innerHTML = "";

    if (!names.length) {
      const opt = document.createElement("option");
      opt.value = "";
      opt.textContent = txt.empty;
      opt.selected = true;
      bmEditGroupSelect.appendChild(opt);

      bmEditGroupSelect.disabled = true;
      bmEditGroupName.disabled = true;
      bmEditGroupDescription.disabled = true;
      bmEditGroupColor.disabled = true;
      bmEditGroupSave.disabled = true;
      bmEditGroupName.value = "";
      bmEditGroupDescription.value = "";
      bmEditGroupColor.value = "#4f46e5";
      if (bmEditGroupTrigger) bmEditGroupTrigger.disabled = true;
      closeBmEditGroupMenu();
      renderBmEditGroupMenu();
      syncBmEditGroupTrigger();
      return;
    }

    bmEditGroupSelect.disabled = false;
    bmEditGroupName.disabled = false;
    bmEditGroupDescription.disabled = false;
    bmEditGroupColor.disabled = false;
    bmEditGroupSave.disabled = false;

    names.forEach((name) => {
      const opt = document.createElement("option");
      opt.value = name;
      opt.textContent = name;
      bmEditGroupSelect.appendChild(opt);
    });

    const selected = (preferredGroup && groups[preferredGroup])
      ? preferredGroup
      : ((bmEditGroupSelect.value && groups[bmEditGroupSelect.value])
        ? bmEditGroupSelect.value
        : ((lastGroup && groups[lastGroup]) ? lastGroup : names[0]));

    bmEditGroupSelect.value = selected;
    bmEditGroupName.value = selected;
    bmEditGroupDescription.value = normalizeBookmarkGroupDescription(groups[selected]?.description || "");
    bmEditGroupColor.value = groups[selected]?.color || "#4f46e5";

    const canEdit = isCustomizeModeActive() && canEditBookmarkGroup(selected);
    bmEditGroupSelect.disabled = !canEdit;
    bmEditGroupName.disabled = !canEdit;
    bmEditGroupDescription.disabled = !canEdit;
    bmEditGroupColor.disabled = !canEdit;
    bmEditGroupSave.disabled = !canEdit;
    if (bmEditGroupTrigger) bmEditGroupTrigger.disabled = !canEdit;
    applySharedGroupEditGate(bmEditGroupSave, selected);
    if (!canEdit) closeBmEditGroupMenu();
    renderBmEditGroupMenu();
    syncBmEditGroupTrigger();
  }

  function initBookmarkGroupEditorHandlers() {
    if (!bmEditGroupSelect || !bmEditGroupName || !bmEditGroupDescription || !bmEditGroupColor || !bmEditGroupSave) return;
    if (bmEditGroupSave.dataset.bound === "1") return;

    bmEditGroupSave.dataset.bound = "1";

    bmEditGroupSelect.addEventListener("change", () => {
      renderBookmarkGroupEditor(bmEditGroupSelect.value);
      renderBmEditGroupMenu();
      syncBmEditGroupTrigger();
    });

    bmEditGroupSave.addEventListener("click", async () => {
      if (!isCustomizeModeActive()) return;

      const oldName = String(bmEditGroupSelect.value || "").trim();
      if (!oldName || !groups[oldName]) return;
      if (!guardBookmarkGroupEdit(oldName)) return;

      const txt = getGroupEditorTexts();
      const nextName = String(bmEditGroupName.value || "").trim();
      if (!nextName) {
        alert(txt.required);
        return;
      }

      if (nextName !== oldName && groups[nextName]) {
        alert(txt.conflict);
        return;
      }

      const nextColor = String(bmEditGroupColor.value || "").trim() || "#4f46e5";
      const nextDescription = normalizeBookmarkGroupDescription(bmEditGroupDescription.value || "");

      if (nextName !== oldName) {
        groups[nextName] = { ...(groups[oldName] || {}), color: nextColor, description: nextDescription };
        delete groups[oldName];
        if (sharedGroups[oldName]) {
          sharedGroups[nextName] = sharedGroups[oldName];
          delete sharedGroups[oldName];
        }
        groupOrder = getOrderedGroupNames().map((name) => name === oldName ? nextName : name);

        bookmarks.forEach((b) => {
          if (b.group === oldName) b.group = nextName;
        });

        if (lastGroup === oldName) lastGroup = nextName;
      } else {
        groups[oldName] = { ...(groups[oldName] || {}), color: nextColor, description: nextDescription };
      }

      await saveBookmarkGroupState({
        [BM_KEYS.groups]: groups,
        [BM_KEYS.groupOrder]: groupOrder,
        [BM_KEYS.bookmarks]: bookmarks,
        [BM_KEYS.lastGroup]: lastGroup || nextName,
        [BM_KEYS.sharedGroups]: sharedGroups
      }, "bookmark-group-edit");

      if (nextName !== oldName) {
        await renameFolderWidgetsGroup(oldName, nextName);
      }

      renderGroupSelect();
      renderBookmarks();
      renderBookmarkGroupEditor(nextName);
    });
  }

  bmGroupSelect?.addEventListener("change", () => {
    lastGroup = bmGroupSelect.value;
    void saveBookmarkGroupState({ [BM_KEYS.lastGroup]: lastGroup }, BM_KEYS.lastGroup);
    syncBmGroupTrigger();
    renderBmGroupMenu();
  });

  bmSortSelect?.addEventListener("change", () => {
    renderBookmarks();
  });

  bmGroupTrigger?.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!bmGroupMenu) return;
    if (bmGroupMenu.hidden) openBmGroupMenu();
    else closeBmGroupMenu();
  });

  newGroupAfterSelect?.addEventListener("change", () => {
    syncNewGroupAfterTrigger();
    renderNewGroupAfterMenu();
  });

  newGroupAfterTrigger?.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!newGroupAfterMenu) return;
    if (newGroupAfterMenu.hidden) openNewGroupAfterMenu();
    else closeNewGroupAfterMenu();
  });

  window.addEventListener("resize", () => {
    if (!newGroupAfterMenu || newGroupAfterMenu.hidden) return;
    positionNewGroupAfterMenu();
  });

  window.addEventListener("scroll", () => {
    if (!newGroupAfterMenu || newGroupAfterMenu.hidden) return;
    positionNewGroupAfterMenu();
  }, true);

  bmEditGroupTrigger?.addEventListener("click", (e) => {
    e.stopPropagation();
    if (!bmEditGroupMenu || bmEditGroupTrigger.disabled) return;
    if (bmEditGroupMenu.hidden) openBmEditGroupMenu();
    else closeBmEditGroupMenu();
  });

  document.addEventListener("click", (e) => {
    const target = e.target;
    if (!(target instanceof Node)) return;

    if (bmGroupWrap && bmGroupMenu && !bmGroupMenu.hidden && !bmGroupWrap.contains(target)) {
      closeBmGroupMenu();
    }
    if (
      newGroupAfterMenu
      && !newGroupAfterMenu.hidden
      && !newGroupAfterWrap?.contains(target)
      && !newGroupAfterMenu.contains(target)
    ) {
      closeNewGroupAfterMenu();
    }
    if (bmEditGroupWrap && bmEditGroupMenu && !bmEditGroupMenu.hidden && !bmEditGroupWrap.contains(target)) {
      closeBmEditGroupMenu();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    closeBmGroupMenu();
    closeNewGroupAfterMenu();
    closeBmEditGroupMenu();
  });

  renderBmGroupMenu();
  syncBmGroupTrigger();
  renderNewGroupAfterMenu();
  syncNewGroupAfterTrigger();
  renderBmEditGroupMenu();
  syncBmEditGroupTrigger();

  initBookmarkGroupEditorHandlers();
  let bookmarkGroupEditorRaf = 0;
  const scheduleBookmarkGroupEditorRender = () => {
    if (bookmarkGroupEditorRaf) return;
    bookmarkGroupEditorRaf = requestAnimationFrame(() => {
      bookmarkGroupEditorRaf = 0;
      renderBookmarkGroupEditor();
    });
  };
  new MutationObserver(scheduleBookmarkGroupEditorRender)
    .observe(document.body, { attributes: true, attributeFilter: ["class"] });

  function getSelectedGroupColor() {
    return document.getElementById("newGroupColor")?.value || "#4f46e5";
  }

  document.getElementById("bmPickIcon")?.addEventListener("click", () => {
    openIconPicker((iconStr) => {
      selectedBmIcon = iconStr || "";
      setIconPreview(selectedBmIcon);
    });
  });
function clampWidgetsBelowSearch() {
  const dashArea = document.getElementById("dashArea");
  const search = document.getElementById("searchCard");
  if (!dashArea || !search) return;

  const gap = 18; // небольшой отступ
  const dashRect = dashArea.getBoundingClientRect();
  const searchRect = search.getBoundingClientRect();

  // нижняя граница search относительно dashArea
  const minTop = (searchRect.bottom - dashRect.top) + gap;

  const widgets = [...dashArea.querySelectorAll(".widget")]
    .filter(el => el.id !== "searchCard");

  for (const w of widgets) {
    // если нет inline top (grid режим) — пропускаем
    const t = parseFloat(w.style.top);
    if (!Number.isFinite(t)) continue;

    if (t < minTop) w.style.top = `${minTop}px`;
  }
}

  function scheduleBookmarksRender(delay = 0) {
    if (bmScheduledRenderTimer) window.clearTimeout(bmScheduledRenderTimer);
    bmScheduledRenderTimer = window.setTimeout(() => {
      bmScheduledRenderTimer = 0;
      window.requestAnimationFrame(() => renderBookmarks());
    }, Math.max(0, Number(delay) || 0));
  }

  function getBookmarkRenderLimit(groupName, totalItems, groupCount = 1) {
    const safeGroupName = String(groupName || "");
    const storedLimit = Number(bmExpandedRenderLimits.get(safeGroupName) || 0);
    const defaultLimit = bmActiveGroup === "__all__"
      ? Math.max(12, Math.ceil(BM_ALL_RENDER_LIMIT / Math.max(1, Number(groupCount) || 1)))
      : BM_GROUP_RENDER_LIMIT;
    const resolved = storedLimit > 0 ? storedLimit : defaultLimit;
    return Math.min(Math.max(resolved, 0), Math.max(0, Number(totalItems) || 0));
  }

  function appendBookmarkShowMore(ul, groupName, shownCount, totalCount) {
    if (!ul || shownCount >= totalCount) return;
    const li = document.createElement("li");
    li.className = "bm-show-more";

    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "bm-show-more-btn";
    btn.textContent = `${t("bookmarks.showMore", "Show more")} (${shownCount}/${totalCount})`;
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const nextLimit = Math.min(totalCount, shownCount + BM_RENDER_LIMIT_STEP);
      bmExpandedRenderLimits.set(String(groupName || ""), nextLimit);
      renderBookmarks();
    });

    li.appendChild(btn);
    ul.appendChild(li);
  }

  function renderBookmarks() {
    const perf = startPerf("render.bookmarks");
    if (!bmList) return;
    bmList.innerHTML = "";

    const grouped = {};
    bookmarks.forEach(bm => {
      if (!grouped[bm.group]) grouped[bm.group] = [];
      grouped[bm.group].push(bm);
    });

    const groupNames = getOrderedGroupNames();
    renderBookmarkGroupTabs(grouped);

    const baseNames = groupNames.length ? groupNames : Object.keys(grouped);
    const namesToRender = bmActiveGroup === "__all__"
      ? baseNames
      : baseNames.filter((name) => name === bmActiveGroup);

    if (bmActiveGroup !== "__all__" && namesToRender.length === 1) {
      bmList.appendChild(renderSharedGroupPanel(namesToRender[0]));
    }

    namesToRender.forEach(groupName => {
      const color = groups[groupName]?.color || "#4f46e5";
      const description = normalizeBookmarkGroupDescription(groups[groupName]?.description || "");
      const allItems = sortBookmarksForLibrary(grouped[groupName] || []);
      const visibleLimit = getBookmarkRenderLimit(groupName, allItems.length, namesToRender.length);
      const items = allItems.slice(0, visibleLimit);
      const safeGroupName = escapeHtml(groupName);
      const safeDescription = escapeHtml(description);
      const safeColor = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.test(String(color || "")) ? color : "#4f46e5";
      const canEditGroup = canEditBookmarkGroup(groupName);

      const block = document.createElement("div");
      block.className = "bookmark-group";
      block.dataset.group = groupName;
      block.classList.toggle("is-edit-locked", !canEditGroup);

      block.innerHTML = `
        <h3 class="bookmark-group-title" style="color:${safeColor}">
          <span class="bm-gtxt">${safeGroupName} <small>${allItems.length}</small></span>
          <span class="bm-actions">
            <button class="bm-openall" type="button" title="Open all">⇑</button>
            <button class="del-group" type="button" title="Delete group">×</button>
          </span>
        </h3>
        ${safeDescription ? `<p class="bm-group-desc">${safeDescription}</p>` : ""}
        <ul class="bm-items"></ul>
      `;

      block.querySelector(".bm-openall").onclick = async () => {
        const urls = bookmarks
          .filter(b => b.group === groupName)
          .map(b => {
            const p = normalizeUrl(b.url);
            return p ? p.href : b.url;
          })
          .filter(Boolean);

        if (chrome?.tabs?.create) {
          for (let i = 0; i < urls.length; i++) {
            chrome.tabs.create({ url: urls[i], active: i === 0 });
          }
          return;
        }

        window.open(urls[0], "_blank", "noopener,noreferrer");
        alert("Браузер блокирует Massive opening of tabs. Please start as an extension or enable popups for this page.");
      };

      applySharedGroupEditGate(block.querySelector(".del-group"), groupName);
      block.querySelector(".del-group").onclick = async () => {
        if (!guardBookmarkGroupEdit(groupName)) return;
        const serverGroupId = String(sharedGroups?.[groupName]?.serverId || sharedGroups?.[groupName]?.serverGroupId || sharedGroups?.[groupName]?.groupId || "").trim();
        if (isSharedBookmarkGroup(groupName)) {
          markSharedGroupDeletedLocally(groupName, serverGroupId);
          if (serverGroupId) removeGuestSharedInviteAccessRecord(serverGroupId);
          void requestSharedBookmarkGroupDeleteOrLeave(groupName);
        }
        void removeFolderWidgetsByGroup(groupName);
        delete groups[groupName];
        delete sharedGroups[groupName];
        bookmarks = bookmarks.filter(b => b.group !== groupName);
        groupOrder = getOrderedGroupNames().filter((name) => name !== groupName);
        if (bmActiveGroup === groupName) bmActiveGroup = "__all__";
        await saveBookmarkGroupState({
          [BM_KEYS.groups]: groups,
          [BM_KEYS.groupOrder]: groupOrder,
          [BM_KEYS.bookmarks]: bookmarks,
          [BM_KEYS.sharedGroups]: sharedGroups
        }, "bookmark-group-delete");
        renderGroupSelect();
        renderBookmarks();
        renderBookmarkGroupEditor();
      };

      const ul = block.querySelector(".bm-items");
      // drop zone for moving bookmarks into this group
      const allowDrop = (e) => { e.preventDefault(); block.classList.add("bm-drop"); };
      const clearDrop = () => block.classList.remove("bm-drop");

      block.addEventListener("dragover", allowDrop);
      block.addEventListener("dragleave", clearDrop);
      block.addEventListener("drop", (e) => {
        e.preventDefault();
        clearDrop();

        const bmId = e.dataTransfer.getData("text/bm-id") || e.dataTransfer.getData("text/plain");
        if (!bmId) return;

        // если бросили на конкретный элемент — вставим перед ним (приятно)
        const before = e.target.closest(".bm-item")?.dataset?.bmId || null;
        const dragged = bookmarks.find((b) => b.id === bmId);
        if ((dragged && !guardBookmarkGroupEdit(dragged.group)) || !guardBookmarkGroupEdit(groupName)) return;
        moveBookmarkToGroup(bmId, groupName, before);
      });

      items.forEach(bm => {
        const li = document.createElement("li");

        const href = normalizeUrl(bm.url)?.href || bm.url;
        const favSlot = slotOfUrl(href);
        const isFav = favSlot !== -1;
        const canEditItem = canEditBookmarkGroup(bm.group);

        li.classList.add("bm-item");
        li.classList.toggle("is-edit-locked", !canEditItem);
        li.dataset.url = href;
        li.dataset.title = String(bm.title || "");
        // draggable
        li.dataset.bmId = bm.id;
        li.draggable = canEditItem;

        li.addEventListener("dragstart", (e) => {
          if (!canEditBookmarkGroup(bm.group)) {
            e.preventDefault();
            showSharedGroupPremiumRequired();
            return;
          }
          // не стартуем drag с кнопок (звезда/удаление/и т.п.)
          if (e.target.closest("button, input, textarea, select, a")) {
            e.preventDefault();
            return;
          }
          e.dataTransfer.effectAllowed = "move";
          e.dataTransfer.setData("text/bm-id", bm.id);
          li.classList.add("bm-dragging");
        });

        li.addEventListener("dragend", () => {
          li.classList.remove("bm-dragging");
        });

        li.innerHTML = `
          <div class="bm-bookmark-row">
            <div class="bm-left">
              <img class="bm-icon" src="${escapeHtml(resolveBookmarkIcon(bm) || "")}" loading="lazy" decoding="async" referrerpolicy="no-referrer">
              <div class="bm-text">
                <div class="bm-title">${escapeHtml(String(bm.title || ""))}</div>
              </div>
            </div>

            <button class="bm-fav ${isFav ? "is-on" : ""}" type="button" title="Favorite">${isFav ? "★" : "☆"}</button>
            <button class="bm-del" type="button" title="Delete">×</button>
          </div>
        `;

        li.addEventListener("click", (e) => {
          if (e.target.closest("button, a, input, textarea, select, .no-open")) return;

          const url = li.dataset.url;
          if (!url) return;

          openUrl(url);
        });

        li.addEventListener("mousedown", (e) => {
          if (e.button !== 1) return;
          if (e.target.closest("button, a, input, textarea, select, .no-open")) return;

          const url = li.dataset.url;
          if (!url) return;

          e.preventDefault();
          openUrl(url, { newTab: true });
        });

        li.querySelector(".bm-icon").onclick = () => {
          if (!guardBookmarkGroupEdit(bm.group)) return;
          openIconPicker((iconStr) => {
            bm.icon = iconStr || "";
            saveBookmarks();
            queueServerSharedBookmarkUpsert(bm.group, bm);
            renderBookmarks();
          });
        };

        li.querySelector(".bm-fav").onclick = async (e) => {
          e.stopPropagation();
          e.preventDefault();

          const entry = {
            id: bm.id,
            title: String(bm.title || "").trim() || href,
            url: href,
            group: String(bm.group || ""),
            icon: String(bm.icon || ""),
          };

          if (isFav) {
            await setFavorite(favSlot, null);
            return;
          }

          showFavPicker(entry, li.querySelector(".bm-fav"));
        };

        applySharedGroupEditGate(li.querySelector(".bm-del"), bm.group);

        li.querySelector(".bm-del").onclick = async (e) => {
          e.stopPropagation();
          if (!guardBookmarkGroupEdit(bm.group)) return;

          const s = slotOfUrl(href);
          if (s !== -1) await setFavorite(s, null);

            queueServerSharedBookmarkDelete(bm.group, bm);
            bookmarks = bookmarks.filter(x => x !== bm);
          
            // CRITICAL: Update shared group snapshot immediately after deletion
            // Prevents other users seeing deleted bookmarks due to stale snapshots
            if (isSharedBookmarkGroup(bm.group)) {
              syncSharedGroupBookmarkSnapshot(bm.group);
            }
          
            await saveBookmarkGroupState({
              [BM_KEYS.bookmarks]: bookmarks,
              [BM_KEYS.sharedGroups]: sharedGroups
            }, "bookmark-delete-shared");
            renderBookmarks();
        };

        ul.appendChild(li);
      });

      appendBookmarkShowMore(ul, groupName, items.length, allItems.length);

      bmList.appendChild(block);
    });

    endPerf(perf, {
      groupsRendered: namesToRender.length,
      totalBookmarks: bookmarks.length
    });

    refreshFolderWidgets();
  }

  registerWidgetRender("bookmarks", () => {
    bmGet([BM_KEYS.bookmarks, BM_KEYS.groups, BM_KEYS.groupOrder, BM_KEYS.lastGroup, BM_KEYS.sharedGroups])
      .then((data) => {
        bookmarks = Array.isArray(data[BM_KEYS.bookmarks]) ? data[BM_KEYS.bookmarks] : [];
        groups = (data[BM_KEYS.groups] && typeof data[BM_KEYS.groups] === "object") ? data[BM_KEYS.groups] : {};
        sharedGroups = normalizeSharedGroupState(data[BM_KEYS.sharedGroups]);
        groupOrder = normalizeGroupOrder(data[BM_KEYS.groupOrder]);
        lastGroup = typeof data[BM_KEYS.lastGroup] === "string" ? data[BM_KEYS.lastGroup] : "";
        if (pruneDeletedSharedGroupsFromLocalState()) {
          groupOrder = normalizeGroupOrder(groupOrder);
        }
        renderGroupSelect();
        scheduleBookmarksRender();
        renderBookmarkGroupEditor(lastGroup);
      })
      .catch((err) => {
        console.error("[CLOUD SYNC] Failed to refresh bookmarks widget", err);
      });
  });
  function moveBookmarkToGroup(bmId, toGroup, beforeId = null) {
    if (!bmId || !toGroup || !groups[toGroup]) return;

    const fromIndex = bookmarks.findIndex(b => b.id === bmId);
    if (fromIndex < 0) return;

    const bm = bookmarks[fromIndex];
    if (!guardBookmarkGroupEdit(bm.group) || !guardBookmarkGroupEdit(toGroup)) return;
    const fromGroup = String(bm.group || "").trim();
    const previousSharedBookmark = { ...bm, group: fromGroup };

    // если бросили в ту же группу и без reorder — ничего не делаем
    if (bm.group === toGroup && !beforeId) return;

    // remove
    bookmarks.splice(fromIndex, 1);

    // change group
    bm.group = toGroup;

    // insert position
    let insertAt = bookmarks.length;

    if (beforeId) {
      const beforeIndex = bookmarks.findIndex(b => b.id === beforeId);
      if (beforeIndex >= 0) insertAt = beforeIndex;
    } else {
      // вставляем в конец целевой группы (после последнего элемента этой группы)
      const lastIdx = [...bookmarks]
        .map((b, i) => ({ b, i }))
        .filter(x => x.b.group === toGroup)
        .map(x => x.i)
        .pop();
      if (typeof lastIdx === "number") insertAt = lastIdx + 1;
    }

    bookmarks.splice(insertAt, 0, bm);

    saveBookmarks();
    if (fromGroup !== toGroup) {
      queueServerSharedBookmarkDelete(fromGroup, previousSharedBookmark);
      bm.serverId = "";
    }
    queueServerSharedBookmarkUpsert(toGroup, bm);
    scheduleBookmarksRender(120);
  }

  function addBookmarkToGroup(entry, toGroup) {
    const groupName = String(toGroup || "").trim();
    if (!groupName || !groups[groupName]) return false;
    if (!guardBookmarkGroupEdit(groupName)) return false;

    const href = canonUrl(entry?.url);
    if (!href) return false;

    const alreadyExists = bookmarks.some((bm) => {
      return String(bm?.group || "").trim() === groupName && canonUrl(bm?.url) === href;
    });

    if (alreadyExists) return false;

    const bookmark = {
      id: genBmId(),
      title: String(entry?.title || "").trim() || href,
      url: href,
      group: groupName,
      icon: String(entry?.icon || ""),
      comment: normalizeBookmarkComment(entry?.comment || "")
    };
    bookmarks.push(bookmark);

    saveBookmarks();
    queueServerSharedBookmarkUpsert(groupName, bookmark);
    scheduleBookmarksRender();
    return true;
  }

  if (addGroupBtn) {
    addGroupBtn.onclick = async () => {
      const name = $("newGroupName").value.trim();
      const color = getSelectedGroupColor();
      const afterName = String(newGroupAfterSelect?.value || "__end__");
      if (!name || groups[name]) return;

      const previousGroups = { ...groups };
      const previousGroupOrder = Array.isArray(groupOrder) ? [...groupOrder] : groupOrder;
      const previousLastGroup = lastGroup;
      const previousActiveGroup = bmActiveGroup;
      groups[name] = { color, description: "" };
      groupOrder = placeNameAfter(getOrderedGroupNames(), name, afterName);
      lastGroup = name;
      bmActiveGroup = name;
      try {
        await saveBookmarkGroupState({
          [BM_KEYS.groups]: groups,
          [BM_KEYS.groupOrder]: groupOrder,
          [BM_KEYS.lastGroup]: lastGroup
        }, "bookmark-group-add");
      } catch (err) {
        groups = previousGroups;
        groupOrder = previousGroupOrder;
        lastGroup = previousLastGroup;
        bmActiveGroup = previousActiveGroup;
        console.error("[BOOKMARKS] failed to create group", err);
        showMiniNotice(t("bookmarks.groupSaveFailed", "Couldn't save folder"), true);
        return;
      }
      renderGroupSelect();
      if (bmGroupSelect && groups[name]) bmGroupSelect.value = name;
      syncBmGroupTrigger();
      renderBookmarkGroupTabs();
      scheduleBookmarksRender();
      renderBookmarkGroupEditor(name);
      $("newGroupName").value = "";
      if (newGroupAfterSelect) newGroupAfterSelect.value = "__end__";
      syncNewGroupAfterTrigger();
      renderNewGroupAfterMenu();
    };
  }

  if (bmImportBrowserBtn) {
    refreshBookmarkImportButtonText();
    bmImportBrowserBtn.addEventListener("click", () => {
      importBrowserBookmarks();
    });
  }

  if (bmExportBookmarksBtn) {
    bmExportBookmarksBtn.textContent = "Export";
    bmExportBookmarksBtn.title = getExportBookmarkLabel();
    bmExportBookmarksBtn.addEventListener("click", () => {
      exportBookmarksToFile();
    });
  }

  if (bmForm) {
    bmForm.onsubmit = e => {
      e.preventDefault();
      const activeGroup = String(bmActiveGroup || "").trim();
      const selectedGroup = String(bmGroupSelect?.value || "").trim();
      const group = activeGroup && activeGroup !== "__all__" && groups[activeGroup]
        ? activeGroup
        : selectedGroup;
      if (!groups[group]) return;
      if (!guardBookmarkGroupEdit(group)) return;

      const bookmark = {
        id: genBmId(),
        title: $("bmTitle").value.trim(),
        url: $("bmUrl").value.trim(),
        group,
        icon: selectedBmIcon || "",
        comment: ""
      };
      bookmarks.push(bookmark);

      selectedBmIcon = "";
      setIconPreview("");

      bmForm.reset();
      saveBookmarks();
      queueServerSharedBookmarkUpsert(group, bookmark);
      scheduleBookmarksRender();
    };
  }

  // ======================
  // WELCOME
  // ======================
  const KEY = "user.nickname";
  const bar = document.getElementById("welcomeBar");
  const nameBtn = document.getElementById("welcomeName");
  const input = document.getElementById("welcomeInput");

  if (bar && nameBtn && input) {
    function setName(nick) {
      const clean = (nick || "").trim();
      const finalNick = clean ? clean : "Friend";
      nameBtn.textContent = finalNick;
      localStorage.setItem(KEY, finalNick);
    }

    const saved = localStorage.getItem(KEY);
    if (saved && saved.trim()) nameBtn.textContent = saved.trim();

    function startEdit() {
      bar.classList.add("editing");
      input.value = (localStorage.getItem(KEY) || "").trim() === "Friend" ? "" : (localStorage.getItem(KEY) || "");
      input.focus();
      input.select();
    }

    function finishEdit(save) {
      if (save) setName(input.value);
      bar.classList.remove("editing");
    }

    nameBtn.addEventListener("click", startEdit);

    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") finishEdit(true);
      if (e.key === "Escape") finishEdit(false);
    });

    input.addEventListener("blur", () => finishEdit(true));

    registerWidgetRender("welcome", () => {
      const syncedName = String(localStorage.getItem(KEY) || "").trim();
      nameBtn.textContent = syncedName || "Friend";
    });
  }
  /* =========================
     BOOKMARKS SEARCH
  ========================= */

  function initBookmarksSearch() {
    const input = document.getElementById("bmSearch");
    const clearBtn = document.getElementById("bmSearchClear");
    const view = document.getElementById("bookmarksView");

    if (!input || !view) return;

    const getItems = () =>
      Array.from(view.querySelectorAll(".bm-item, .bookmark-item"));

    const getGroups = () =>
      Array.from(view.querySelectorAll(".bm-group, .bookmark-group"));

    function normalize(s) {
      return (s || "").toLowerCase().trim();
    }

    function applySearch(q) {
      const query = normalize(q);
      const items = getItems();
      const groups = getGroups();

      if (!query) {
        // показать всё
        items.forEach(el => (el.style.display = ""));
        groups.forEach(g => (g.style.display = ""));
        return;
      }

      // сначала скрываем всё
      items.forEach(el => (el.style.display = "none"));
      groups.forEach(g => (g.style.display = "none"));

      // показываем совпадения
      items.forEach(el => {
        const title =
          el.dataset.title ||
          el.querySelector(".bm-title")?.textContent ||
          "";

        const url =
          el.dataset.url ||
          el.querySelector(".bm-url")?.textContent ||
          "";

        if (
          normalize(title).includes(query) ||
          normalize(url).includes(query)
        ) {
          el.style.display = "";
          const group = el.closest(".bm-group, .bookmark-group");
          if (group) group.style.display = "";
        }
      });
    }

    // input
    input.addEventListener("input", e => {
      applySearch(e.target.value);
    });

    // Enter → открыть первую найденную
    input.addEventListener("keydown", e => {
      if (e.key === "Enter") {
        const first = getItems().find(
          el => el.style.display !== "none"
        );
        if (first) {
          const link = first.querySelector("a");
          if (link) link.click();
          else if (first.dataset.url) openUrl(first.dataset.url);
        }
      }

      // Esc → очистить
      if (e.key === "Escape") {
        input.value = "";
        applySearch("");
        input.blur();
      }
    });

    // кнопка ×
    if (clearBtn) {
      clearBtn.addEventListener("click", () => {
        input.value = "";
        applySearch("");
        input.focus();
      });
    }
  }

  /* ======================
     SIDEBAR / BOOKMARKS PANEL
  ====================== */
  const app = document.getElementById("workspace");
  const openBookmarks = document.getElementById("openBookmarks");
  const closeBookmarks = document.getElementById("closeBookmarks");
  const openTimePanel = document.getElementById("openTimePanel");
  const closeTimeView = document.getElementById("closeTimeView");

  function toggleBookmarks(force) {
    if (!app) return;
    if (force === true) {
      app.classList.add("show-bookmarks");
      app.classList.remove("show-time");
      openTimePanel?.classList.remove("is-active");
    } else if (force === false) {
      app.classList.remove("show-bookmarks");
    } else {
      const nextOpen = !app.classList.contains("show-bookmarks");
      app.classList.toggle("show-bookmarks", nextOpen);
      if (nextOpen) {
        app.classList.remove("show-time");
        openTimePanel?.classList.remove("is-active");
      }
    }
  }

  function toggleTimeView(force) {
    if (!app) return;
    const isOpen = app.classList.contains("show-time");
    const nextOpen = force === undefined ? !isOpen : !!force;
    app.classList.toggle("show-time", nextOpen);
    if (nextOpen) app.classList.remove("show-bookmarks");
    openTimePanel?.classList.toggle("is-active", nextOpen);
  }

  openTimePanel?.addEventListener("click", () => toggleTimeView());
  closeTimeView?.addEventListener("click", () => toggleTimeView(false));
  openBookmarks?.addEventListener("click", () => toggleBookmarks());
  closeBookmarks?.addEventListener("click", () => toggleBookmarks(false));

  function isBookmarksOpen() {
    return app?.classList.contains("show-bookmarks");
  }

  function getVisibleBmItems() {
    const view = document.getElementById("bookmarksView");
    if (!view) return [];
    return Array.from(view.querySelectorAll(".bm-item")).filter(
      el => el.style.display !== "none"
    );
  }

  function bmSetFocus(el) {
    document.querySelectorAll(".bm-item.bm-kb-focus").forEach(x => x.classList.remove("bm-kb-focus"));
    if (el) {
      el.classList.add("bm-kb-focus");
      el.scrollIntoView({ block: "nearest" });
    }
  }

  function bmFocusSearch() {
    const inp = document.getElementById("bmSearch");
    if (inp) { inp.focus(); inp.select(); }
  }

  document.addEventListener("keydown", (e) => {
    // Alt+B — открыть панель закладок (не конфликтует с Chrome)
    // e.code используется чтобы работало на любой раскладке (рус, укр, и т.д.)
    if (e.altKey && !e.ctrlKey && !e.metaKey && e.code === "KeyB") {
      e.preventDefault();
      const wasOpen = isBookmarksOpen();
      toggleBookmarks(!wasOpen || undefined);
      if (!wasOpen) {
        setTimeout(bmFocusSearch, 50);
      }
      return;
    }

    // Ctrl+B / Cmd+B тоже поддерживаем (e.code не зависит от раскладки)
    if ((e.ctrlKey || e.metaKey) && !e.altKey && e.code === "KeyB") {
      e.preventDefault();
      const wasOpen = isBookmarksOpen();
      toggleBookmarks(!wasOpen || undefined);
      if (!wasOpen) {
        setTimeout(bmFocusSearch, 50);
      }
      return;
    }
  });

  document.addEventListener("keydown", (e) => {
    if (!isBookmarksOpen()) return;

    const tag = document.activeElement?.tagName;
    const inSearch = tag === "INPUT" || tag === "TEXTAREA";
    const focused = document.querySelector(".bm-item.bm-kb-focus");

    // ArrowDown: из поиска — переходим к первому результату;
    //            из списка — к следующему
    if (e.key === "ArrowDown") {
      e.preventDefault();
      const items = getVisibleBmItems();
      if (!items.length) return;
      if (inSearch || !focused) {
        document.activeElement?.blur();
        bmSetFocus(items[0]);
      } else {
        const idx = items.indexOf(focused);
        bmSetFocus(items[Math.min(idx + 1, items.length - 1)]);
      }
    }

    // ArrowUp: из списка — к предыдущему; если первый — возврат в поиск
    if (e.key === "ArrowUp") {
      e.preventDefault();
      const items = getVisibleBmItems();
      if (!items.length) return;
      if (!focused) {
        bmFocusSearch();
        return;
      }
      const idx = items.indexOf(focused);
      if (idx <= 0) {
        bmSetFocus(null);
        bmFocusSearch();
      } else {
        bmSetFocus(items[idx - 1]);
      }
    }

    // Enter: открыть выделенную закладку (или первую, если в поиске)
    if (e.key === "Enter" && !e.shiftKey) {
      if (focused) {
        e.preventDefault();
        const url = focused.dataset.url;
        if (url) openUrl(url, { newTab: e.ctrlKey || e.metaKey });
        return;
      }
      if (inSearch) {
        const items = getVisibleBmItems();
        if (items[0]) {
          e.preventDefault();
          const url = items[0].dataset.url;
          if (url) openUrl(url, { newTab: e.ctrlKey || e.metaKey });
        }
      }
    }

    // Escape: закрыть панель
    if (e.key === "Escape") {
      bmSetFocus(null);
      toggleBookmarks(false);
    }
  });

  function setupScrollShadow(el) {
    function update() {
      const scrollTop = el.scrollTop;
      const maxScroll = el.scrollHeight - el.clientHeight;

      el.classList.toggle("shadow-top", scrollTop > 4);
      el.classList.toggle("shadow-bottom", scrollTop < maxScroll - 4);
    }

    el.addEventListener("scroll", update);
    update();
  }

  const bookmarksCard = document.querySelector(".card.bookmarks");
  if (bookmarksCard) setupScrollShadow(bookmarksCard);

  // ======================
  // DATE WIDGET
  // ======================
  let currentCalendarDate = new Date();

  function getLocalDateInputValue(date = new Date()) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, "0");
    const day = String(date.getDate()).padStart(2, "0");
    return `${year}-${month}-${day}`;
  }

  function getStoredTodos() {
    try {
      const raw = JSON.parse(localStorage.getItem("todos") || "[]");
      return Array.isArray(raw) ? raw : [];
    } catch {
      return [];
    }
  }

  function updateDateTodoPreview() {
    const dateCard = document.getElementById("dateCard");
    const title = document.getElementById("dateTodayTodosTitle");
    const list = document.getElementById("dateTodayTodosList");
    if (!dateCard || !title || !list) return;

    if (!hasFeature(PREMIUM_FEATURE_DATE_TODO_PREVIEW)) {
      list.innerHTML = "";
      dateCard.classList.remove("has-date-todo-preview", "has-today-todos");
      return;
    }

    const todayKey = getLocalDateInputValue();
    const todayTodos = getStoredTodos()
      .filter((todo) => todo && typeof todo === "object" && todo.dueDate === todayKey)
      .slice(0, 50);

    title.textContent = t("widgets.dateTodayTodos", "Today");
    list.innerHTML = "";
    dateCard.classList.toggle("has-date-todo-preview", todayTodos.length > 0);
    dateCard.classList.toggle("has-today-todos", todayTodos.length > 0);

    if (!todayTodos.length) {
      return;
    }

    todayTodos.slice(0, 2).forEach((todo) => {
      const item = document.createElement("li");
      item.className = "date-today-todo" + (todo.done ? " is-done" : "");

      const dot = document.createElement("span");
      dot.className = "date-today-todo-dot";
      dot.setAttribute("aria-hidden", "true");

      const text = document.createElement("span");
      text.className = "date-today-todo-text";
      text.textContent = String(todo.text || "").trim() || t("widgets.todo", "To do");

      item.append(dot, text);
      list.appendChild(item);
    });

    const remaining = todayTodos.length - 2;
    if (remaining > 0) {
      const more = document.createElement("li");
      more.className = "date-today-todos-more";
      more.textContent = t("widgets.dateMoreTodos", "+{count} more").replace("{count}", String(remaining));
      list.appendChild(more);
    }
  }

  function refreshDateWidgetLocale() {
    const w = document.getElementById("dateWeekday");
    const d = document.getElementById("dateDay");
    const m = document.getElementById("dateMonth");
    if (!w || !d || !m) return;

    const now = new Date();
    w.textContent = now.toLocaleDateString(getLocale(), { weekday: "long" }).toUpperCase();
    d.textContent = String(now.getDate());
    m.textContent = now.toLocaleDateString(getLocale(), { month: "short" }).toUpperCase();
    updateDateTodoPreview();
  }

  function updateCalendarWeekdayHeaders() {
    const weekdayEls = document.querySelectorAll(".cal-weekdays > div");
    if (weekdayEls.length !== 7) return;

    const monday = new Date(Date.UTC(2026, 0, 5));
    for (let i = 0; i < 7; i++) {
      const date = new Date(monday);
      date.setUTCDate(monday.getUTCDate() + i);
      weekdayEls[i].textContent = date.toLocaleDateString(getLocale(), { weekday: "short" });
    }
  }

  function startDateWidget() {
    const w = document.getElementById("dateWeekday");
    const d = document.getElementById("dateDay");
    const m = document.getElementById("dateMonth");
    if (!w || !d || !m) return;

    const update = () => {
      refreshDateWidgetLocale();
    };

    update();
    setInterval(() => {
      if (!document.hidden) update();
    }, 60 * 1000);
    document.addEventListener("visibilitychange", () => {
      if (!document.hidden) update();
    });
  }

  function renderCalendar() {
    const grid = document.getElementById("calGrid");
    const title = document.getElementById("calTitle");
    if (!grid || !title) return;

    updateCalendarWeekdayHeaders();

    const year = currentCalendarDate.getFullYear();
    const month = currentCalendarDate.getMonth();
    const today = new Date();

    title.textContent = currentCalendarDate.toLocaleDateString(getLocale(), { month: "long", year: "numeric" });

    const firstDay = new Date(year, month, 1);
    let dayOfWeek = firstDay.getDay();
    dayOfWeek = dayOfWeek === 0 ? 6 : dayOfWeek - 1;

    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const prevMonthDays = new Date(year, month, 0).getDate();

    grid.innerHTML = "";

    for (let i = dayOfWeek - 1; i >= 0; i--) {
      const day = document.createElement("div");
      day.className = "cal-day is-out";
      day.textContent = prevMonthDays - i;
      grid.appendChild(day);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const day = document.createElement("div");
      day.className = "cal-day";
      day.textContent = d;
      
      if (year === today.getFullYear() && month === today.getMonth() && d === today.getDate()) {
        day.classList.add("is-today");
      }
      
      grid.appendChild(day);
    }

    const totalCells = dayOfWeek + daysInMonth;
    const remainingCells = 42 - totalCells;
    for (let d = 1; d <= remainingCells; d++) {
      const day = document.createElement("div");
      day.className = "cal-day is-out";
      day.textContent = d;
      grid.appendChild(day);
    }
  }

  const calPrev = document.getElementById("calPrev");
  const calNext = document.getElementById("calNext");

  calPrev?.addEventListener("click", () => {
    currentCalendarDate.setMonth(currentCalendarDate.getMonth() - 1);
    renderCalendar();
  });

  calNext?.addEventListener("click", () => {
    currentCalendarDate.setMonth(currentCalendarDate.getMonth() + 1);
    renderCalendar();
  });

  /* =========================================================
     CUSTOMIZE MODE (НОВОЕ) — drag/resize/hide/save
  ========================================================= */

  function syncLayoutItemStates(){
  document
    .querySelectorAll('#layoutPanel .layout-item input[type="checkbox"]')
    .forEach(cb => {
      const item = cb.closest('.layout-item');
      if (!item) return;

      const sync = () => item.classList.toggle('is-on', cb.checked);
      cb.removeEventListener('change', sync); // можно не надо, но ок
      cb.addEventListener('change', sync);
      sync();
    });
}

// ======================
// PHOTOS WIDGETS (MULTI, persistent, deletable)
// ======================
const PHOTOS_INDEX_KEY = "photos.widgets.v1";          // список инстансов
const PHOTOS_DATA_KEY  = (id) => `photos.data.${id}`; // данные одного инстанса
const PHOTOS_SELECTED_KEY = (id) => `photos.selected.${id}`; // instanceId -> number

const addPhotosBtn = document.getElementById("addPhotosBtn");
const dashArea = document.getElementById("dashArea");
const tpl = document.getElementById("photosWidgetTpl");



function pGet(keys) {
  const perf = startPerf("storage.read.pGet");
  return new Promise((resolve) => {
    if (hasChromeStorage) {
      chrome.storage.local.get(keys, (res) => {
        endPerf(perf, { keys: Array.isArray(keys) ? keys.length : 1, chrome: true });
        resolve(res || {});
      });
    }
    else {
      const out = {};
      for (const k of keys) {
        try { out[k] = JSON.parse(localStorage.getItem(k)); } catch { out[k] = null; }
      }
      endPerf(perf, { keys: Array.isArray(keys) ? keys.length : 1, chrome: false });
      resolve(out);
    }
  });
}

function pSet(obj) {
  const perf = startPerf("storage.write.pSet");
  const keyCount = Object.keys(obj || {}).length;
  return new Promise((resolve) => {
    if (hasChromeStorage) {
      chrome.storage.local.set(obj, () => {
        endPerf(perf, { keys: keyCount, chrome: true });
        resolve();
      });
    }
    else {
      for (const [k, v] of Object.entries(obj)) localStorage.setItem(k, JSON.stringify(v));
      endPerf(perf, { keys: keyCount, chrome: false });
      resolve();
    }
  });
}
async function getSelectedPhotoIndex(instanceId) {
  const res = await pGet([PHOTOS_SELECTED_KEY(instanceId)]);
  const n = Number(res[PHOTOS_SELECTED_KEY(instanceId)]);
  return Number.isFinite(n) && n >= 0 ? n : 0;
}

async function setSelectedPhotoIndex(instanceId, idx) {
  await pSet({ [PHOTOS_SELECTED_KEY(instanceId)]: Number(idx) || 0 });
}


function pRemove(keys) {
  return new Promise((resolve) => {
    if (hasChromeStorage) chrome.storage.local.remove(keys, () => resolve());
    else {
      for (const k of keys) localStorage.removeItem(k);
      resolve();
    }
  });
}

function uid(prefix = "photos") {
  return `${prefix}-${Math.random().toString(36).slice(2, 9)}`;
}

async function savePhotosIndex(list) {
  await pSet({ [PHOTOS_INDEX_KEY]: list });
  broadcastGntdStateChange("WIDGETS_CHANGED");
}

async function loadPhotosIndex() {
  const res = await pGet([PHOTOS_INDEX_KEY]);
  return Array.isArray(res[PHOTOS_INDEX_KEY]) ? res[PHOTOS_INDEX_KEY] : [];
}

async function savePhotosData(instanceId, data) {
  await pSet({ [PHOTOS_DATA_KEY(instanceId)]: data });
  broadcastGntdStateChange("WIDGETS_CHANGED");
}

async function loadPhotosData(instanceId) {
  const res = await pGet([PHOTOS_DATA_KEY(instanceId)]);
  const raw = res[PHOTOS_DATA_KEY(instanceId)] || {};
  const images = Array.isArray(raw.images) ? raw.images : [];
  const featured = typeof raw.featured === "string" ? raw.featured : "";
  const positions = raw.positions && typeof raw.positions === "object" ? raw.positions : {};
  return { images, featured, positions };
}

function clampPhotosOffsetY(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 50;
  return Math.max(0, Math.min(100, n));
}

function getFeaturedOffsetY(data) {
  const featured = data?.featured || "";
  if (!featured) return 50;
  return clampPhotosOffsetY(data?.positions?.[featured]);
}

function renderPhotosGrid(widgetEl, data) {
  const grid = widgetEl.querySelector(".photos-grid");
  if (!grid) return;

  grid.innerHTML = "";
  const featured = data?.featured || "";

  for (const src of (data?.images || [])) {
    const img = document.createElement("img");
    img.src = src;
    img.alt = "";
    img.loading = "lazy";
    img.decoding = "async";

    if (featured && src === featured) img.classList.add("is-featured");
    grid.appendChild(img);
  }
}
function applyPhotosCover(widgetEl, data) {
  const src = data?.featured || data?.images?.[0] || "";
  if (src) {
    widgetEl.style.setProperty("--photos-bg", `url("${src}")`);
    widgetEl.style.setProperty("--photos-bg-pos-y", `${getFeaturedOffsetY(data)}%`);
  } else {
    widgetEl.style.removeProperty("--photos-bg");
    widgetEl.style.removeProperty("--photos-bg-pos-y");
  }
}

// Widget sizes functions (save and load widget size preferences globally)
function saveWidgetSizes() {
  const sizes = {};
  const dashboard = document.querySelector(".widgets .dashboard");
  if (dashboard) {
    dashboard.querySelectorAll('[data-widget]').forEach(w => {
      if (w.classList.contains('widget-compact')) {
        sizes[w.id] = 'compact';
      }
      if (w.classList.contains('photos-wide')) {
        sizes[w.id] = 'wide';
      }
      if (w.classList.contains('wx-compact')) {
        sizes[w.id] = 'wx-compact';
      }
      if (w.classList.contains('date-wide')) {
        sizes[w.id] = 'date-wide';
      }
      if (w.classList.contains('is-calendar')) {
        sizes[w.id] = 'date-calendar';
      }
      if (w.classList.contains('search-compact')) {
        sizes[w.id] = 'search-compact';
      }
    });
  }
  localStorage.setItem('widget.sizes.v1', JSON.stringify(sizes));
  broadcastGntdStateChange("WIDGETS_CHANGED");
}

function loadWidgetSizes() {
  try {
    const sizes = JSON.parse(localStorage.getItem('widget.sizes.v1') || '{}');
    const dashboard = document.querySelector(".widgets .dashboard");
    if (dashboard) {
      dashboard.querySelectorAll('[data-widget]').forEach(w => {
        w.classList.remove('widget-compact', 'photos-wide', 'wx-compact', 'date-wide', 'is-calendar', 'search-compact');
        if (sizes[w.id] === 'compact') {
          w.classList.add('widget-compact');
        }
        if (sizes[w.id] === 'wide') {
          w.classList.add('photos-wide');
        }
        if (sizes[w.id] === 'wx-compact') {
          w.classList.add('wx-compact');
        }
        if (sizes[w.id] === 'date-wide') {
          w.classList.add('date-wide');
        }
        if (sizes[w.id] === 'date-calendar') {
          w.classList.add('date-wide');
          w.classList.add('is-calendar');
          // Render calendar after a small delay to ensure DOM is ready
          setTimeout(() => {
            currentCalendarDate = new Date();
            renderCalendar();
          }, 100);
        }
        if (sizes[w.id] === 'search-compact') {
          w.classList.add('search-compact');
        }
      });
    }
  } catch (e) {}
}

async function createPhotosWidget({ mountEl, instanceId, initialData }) {
  if (!tpl?.content) return;

  // клонируем из template
  const node = tpl.content.firstElementChild.cloneNode(true);

  node.dataset.instance = instanceId;
  node.id = instanceId; // чтобы в консоли было видно
  // на всякий случай
  node.classList.add("widget", "photos");

  const input = node.querySelector(".photos-input");
  const btnUpload = node.querySelector('[data-act="upload"]');
  const btnShuffle = node.querySelector('[data-act="shuffle"]');
const btnClose = node.querySelector('[data-act="close"]'); 


  let data = initialData || { images: [], featured: "", positions: {} };
  if (!data.positions || typeof data.positions !== "object") data.positions = {};

  // первичный рендер
  applyPhotosCover(node, data);

  renderPhotosGrid(node, data);
const grid = node.querySelector(".photos-grid");

grid?.addEventListener("click", async (e) => {
  // выбирать можно только в Customize mode
  if (!document.body.classList.contains("layout-editing")) return;

  const img = e.target.closest("img");
  if (!img) return;

  const src = img.src;
  if (!src) return;

  // сохраняем featured
  data.featured = src;
  if (!Number.isFinite(Number(data.positions[src]))) data.positions[src] = 50;

  // (опционально) делаем выбранную первой
  data.images = [src, ...data.images.filter(x => x !== src)];
 applyPhotosCover(node, data);
  renderPhotosGrid(node, data);
  await savePhotosData(instanceId, data);
});

  // Upload
 btnUpload?.addEventListener("click", () => {
  if (!document.body.classList.contains("layout-editing")) return;
  input?.click();
});

  input?.addEventListener("change", async () => {
    const perf = startPerf("flow.addPhoto.upload");
    const files = Array.from(input.files || []);
    if (!files.length) {
      endPerf(perf, { files: 0, reason: "no-files" });
      return;
    }
// если "главная" ещё не выбрана — назначаем первую
if (!data.featured && data.images.length) {
  data.featured = data.images[0];
  if (!Number.isFinite(Number(data.positions[data.featured]))) data.positions[data.featured] = 50;
}

    // Читаем в base64 (dataURL) -> сохраняется в storage
    const toDataUrl = (file) =>
      new Promise((resolve, reject) => {
        const r = new FileReader();
        r.onload = () => resolve(String(r.result || ""));
        r.onerror = reject;
        r.readAsDataURL(file);
      });

    const newImgs = await Promise.all(files.map((f) => toDataUrl(f)));

    data.images = [...data.images, ...newImgs];
      // ✅ если главная не выбрана — ставим первую
  if (!data.featured && data.images.length) data.featured = data.images[0];
  if (data.featured && !Number.isFinite(Number(data.positions[data.featured]))) {
    data.positions[data.featured] = 50;
  }
   applyPhotosCover(node, data);
  renderPhotosGrid(node, data);
    await savePhotosData(instanceId, data);

    // сброс input, чтобы можно было загрузить те же файлы снова
    input.value = "";
    endPerf(perf, {
      files: files.length,
      added: newImgs.length,
      totalImages: data.images.length
    });
  });

  // Shuffle (перемешать порядок)
btnShuffle?.addEventListener("click", async () => {
  if (!document.body.classList.contains("layout-editing")) return;

  if (!data.images?.length) return;
  data.images = [...data.images].sort(() => Math.random() - 0.5);

  // если featured пропал (редко) — восстановим
  if (!data.featured && data.images.length) data.featured = data.images[0];
  if (data.featured && !Number.isFinite(Number(data.positions[data.featured]))) {
    data.positions[data.featured] = 50;
  }

  applyPhotosCover(node, data);
  renderPhotosGrid(node, data);
  await savePhotosData(instanceId, data);
});

  // Clear (очистить все фото)
  const btnClear = node.querySelector('[data-act="clear"]');
  btnClear?.addEventListener("click", async () => {
    if (!document.body.classList.contains("layout-editing")) return;
    
    if (!confirm("Delete all photos from this widget?")) return;
    
    data.images = [];
    data.featured = "";
    data.positions = {};
    
    applyPhotosCover(node, data);
    renderPhotosGrid(node, data);
    await savePhotosData(instanceId, data);
  });

  // Size toggle (переключить размер)
  const btnSizeToggle = node.querySelector('[data-act="size-toggle"]');
  btnSizeToggle?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    if (!ensurePremiumFeature(PREMIUM_FEATURE_WIDGET_RESIZE, getPremiumFeatureLabel(PREMIUM_FEATURE_WIDGET_RESIZE))) return;
    node.classList.toggle("photos-wide");
    btnSizeToggle.textContent = "⤢";
    syncWidgetPositionSize(node);
    saveWidgetSizes();
  });

  const btnMoveUp = node.querySelector('[data-act="move-up"]');
  const btnMoveDown = node.querySelector('[data-act="move-down"]');
  const OFFSET_STEP = 5;

  async function moveFeaturedPhoto(direction) {
    if (!document.body.classList.contains("layout-editing")) return;
    if (!data?.featured) return;

    const current = getFeaturedOffsetY(data);
    const next = clampPhotosOffsetY(current + (direction * OFFSET_STEP));
    if (!data.positions || typeof data.positions !== "object") data.positions = {};
    data.positions[data.featured] = next;

    applyPhotosCover(node, data);
    await savePhotosData(instanceId, data);
  }

  btnMoveUp?.addEventListener("click", async (ev) => {
    ev.stopPropagation();
    await moveFeaturedPhoto(-1);
  });

  btnMoveDown?.addEventListener("click", async (ev) => {
    ev.stopPropagation();
    await moveFeaturedPhoto(1);
  });





  mountEl.appendChild(node);
  refreshPremiumUi();
  return node;
}

async function addPhotosWidget({ mountEl }) {
  const instanceId = uid("photos");
  const idx = await loadPhotosIndex();
  idx.push(instanceId);
  await savePhotosIndex(idx);

  const data = { images: [], featured: "", positions: {} };
  await savePhotosData(instanceId, data);

  return createPhotosWidget({ mountEl, instanceId, initialData: data });
}

async function restorePhotosWidgets({ mountEl }) {
  if (!mountEl) return;

  // 1) удаляем ЛЮБЫЕ старые photos; актуальный набор будет пересобран из индекса.
  document.querySelectorAll(".widget.photos").forEach((w) => {
    w.remove();
  });

  // 2) восстанавливаем сохранённые multi-инстансы
  const idx = await loadPhotosIndex();
  for (const instanceId of idx) {
    const data = await loadPhotosData(instanceId);
    await createPhotosWidget({ mountEl, instanceId, initialData: data });
  }
}

