const layoutBootstrapPromise = (async () => {
  if (dashArea) {
    // Restore photos immediately; folder widgets are restored via premium-aware sync to prevent flash/remove flicker.
    await restorePhotosWidgets({ mountEl: dashArea });
    await syncFolderWidgetsPremiumUi(getEffectivePremiumState());
  }

  // Now load and apply layout configuration AFTER widgets are restored
  loadLayoutConfig();
  loadWidgetSizes();
  applyHiddenWidgetsState();
  refreshPremiumUi();
  
  initLayoutCustomizer();
})();

addPhotosBtn?.addEventListener("click", async () => {
  const perf = startPerf("flow.addPhoto.widget");
  if (!dashArea) return;
  if (!ensurePremiumFeature(PREMIUM_FEATURE_PHOTOS_WIDGET, getPremiumFeatureLabel(PREMIUM_FEATURE_PHOTOS_WIDGET))) return;

  const node = await addPhotosWidget({ mountEl: dashArea });
  if (!node?.id) {
    endPerf(perf, { created: false });
    return;
  }

  // ✅ сказать кастомайзеру: "виджет добавлен"
  document.dispatchEvent(new CustomEvent("layout:widget-added", {
    detail: { id: node.id }
  }));
  endPerf(perf, { created: true, id: node.id });
});

async function handleAddFolderWidget() {
  const perf = startPerf("flow.addFolder.widget");
  if (!dashArea) return;
  const savedFolderWidgetIds = await loadFolderWidgetsIndex();
  const folderWidgetCount = Math.max(
    savedFolderWidgetIds.length,
    dashArea.querySelectorAll('.widget.folder-widget[data-instance]').length
  );
  if (!ensurePremiumCreateSlot(folderWidgetCount, "More folders", {
    folderWidgetCount,
    featureName: PREMIUM_FEATURE_DASHBOARD_FOLDERS
  })) return;

  const rawName = String(layoutFolderNameInput?.value || "").trim();
  if (!rawName) {
    layoutFolderNameInput?.focus();
    endPerf(perf, { created: false, reason: "empty-name" });
    return;
  }

  const groupName = await ensureBookmarkGroup(rawName, { skipBookmarkRender: true });
  if (!groupName) {
    endPerf(perf, { created: false, reason: "group-invalid" });
    return;
  }

  const node = await addFolderWidget({ mountEl: dashArea, groupName });
  if (!node?.id) {
    endPerf(perf, { created: false, reason: "widget-create-failed", group: groupName });
    return;
  }

  if (layoutFolderNameInput) layoutFolderNameInput.value = "";

  document.dispatchEvent(new CustomEvent("layout:widget-added", {
    detail: { id: node.id }
  }));
  endPerf(perf, { created: true, id: node.id, group: groupName });
}

addFolderWidgetBtn?.addEventListener("click", () => {
  void handleAddFolderWidget();
});

layoutFolderNameInput?.addEventListener("keydown", (e) => {
  if (e.key !== "Enter") return;
  e.preventDefault();
  void handleAddFolderWidget();
});

