  for (const [langCode, minLabel] of Object.entries(timeMinuteUnits)) {
    if (timeI18n[langCode]) timeI18n[langCode].min = minLabel;
  }

  const initLang = normalizeLanguage(localStorage.getItem("app.language") || currentLanguage || "en");
  let timeStrings = timeI18n[initLang] || timeI18n.en;
  let chartRange = "week";
  let timerId = null;
  let timePipWindow = null;
  let timePipOpening = null;
  let activeTimeView = "timer";
  let calendarViewMode = "month";
